window.__D("text/zohar/c013",{"p":[[9520011550,"<p>אָמַר רִבִּי יוּדָאי אָמַר רִבִּי יִצְחָק, מַה הֲוָה מַחֲשַׁבְתְּהוֹן דְּמִצְרָאֵי, דְּמִמְנַע מִיִּשְׂרָאֵל פִּרְיָה וּרְבִיָּה, וְשֻׁלְטָנָא דִּמְמָנָא עֲלֵיהוֹן דְּאָעִיל בְּלִבְּהוֹן כַּךְ. אֶלָּא, אָמַר לְהוֹן, הֲווֹ יַדְעִין, דְּזַמִּין בְּרָא חֲדָא לְמֵיפַק מִיִּשְׂרָאֵל, דְּיִתְעֲבֵיד דִּינָא בֶּאֱלהֵיהוֹן עַל יְדֵיהּ.</p>\n<p>דְּאָמַר רִבִּי יוֹחָנָן, בְּשָׁעָה שֶׁאָמַר מֹשֶׁה, (שמות י״ב:י״ב) וּבְכָל אֱלהֵי מִצְרַיִם אֶעֱשֶׂה שְׁפָטִים הָלַךְ דּוּמָה שָׂרוֹ שֶׁל מִצְרַיִם, ד' מֵאוֹת פַּרְסָה. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, גְּזֵרָה נִגְזְרָה לְפָנַי, דִּכְתִּיב, (ישעיהו כ״ד:כ״א) יִפְקֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְגוֹ'. בְּאוֹתָה שָׁעָה נִטְּלָה הַשְּׂרָרָה מִמֶּנּוּ, וְנִתְמַנָּה דּוּמָה שַׂר שֶׁל גֵּיהִנָּם, לִידוֹן שָׁם נַפְשׁוֹת הָרְשָׁעִים. וְרִבִּי יְהוּדָה אוֹמֵר עַל הַמֵּתִים נִתְמַנָּה.</p>\n<p>אָמַר רִבִּי חֲנִינָא, כְּתִיב (במדבר ל״ג:ד׳) וּבֵאלֹהֵיהֶם עָשָׂה יְיָ' שְׁפָטִים. וְכִי בֶּאֱלהַּ שֶׁל כֶּסֶף, וְשֶׁל זָהָב, וְשֶׁל עֵץ, וְשֶׁל אֶבֶן, יֶשׁ שְׁפָטִים. אֶלָּא אָמַר רִבִּי יוֹסֵי, שֶׁל כֶּסֶף וְשֶׁל זָהָב הָיוּ נִתָּכִים מֵאֲלֵיהֶם, וְשֶׁל עֵץ מִתְרַקְּבִין.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אֱלוֹהַּ שֶׁל מִצְרַיִם שֶׂה הָיָה, וְצִוָּה הַקָדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בּוֹ שְׁפָטִים, לִשְׂרוֹף אוֹתוֹ בָּאֵשׁ, כְּמָה דְּאַתְּ אָמֵר, (דברים ז׳:כ״ה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. כְּדֵי שֶׁיְּהֵא רֵיחוֹ נוֹדֶף. וְעוֹד, (שמות י״ב:ט׳) רֹאשׁוֹ עַל כְּרָעָיו וְעַל קִרְבּוֹ. וְעוֹד, שֶׁעַצְמוֹתָיו מוּשְׁלָכִים בַּשּׁוּק. וְזֹאת הָיְתָה לְמִצְרַיִם קָשֶׁה מִכּוּלָּן, הֲדָא הוּא דִּכְתִּיב, שְׁפָטִים.</p>\n<p>אָמַר רִבִּי יְהוּדָה בֵּאלהֵיהֶם מַמָּשׁ וְזֶהוּ שַׂר שֶׁלָּהֶם, לְקַיֵּים, יִפְקוֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. וְכָל זֶה הָיוּ יוֹדְעִים הַחֲכָמִים שֶׁבָּהֶם, וְכָּל שֶׁכֵּן שַׂר שֶׁלָּהֶם. עַל כֵּן כְּתִיב, הָבָה נִּתְחַכְּמָה לוֹ.</p>\n<p>רִבִּי יוֹחָנָן אָמַר, הַרְבֵּה עֲבוֹדָה זָרָה הָיוּ בְּמִצְרַיִם, וְנִילוּס אֱלוֹהַּ <Nonei></i>שֶׁלָּהֶם הָיָה, וּבִכְלַל אֱלהֵיהֶם הָיָה הוּא, וּבְכוּלָּם עָשָׂה ה' שְׁפָטִים. אָמַר רִבִּי אַבָּא, הָא דְּר' יוֹחָנָן דַּיְיקָא, וּפְשִׁיטָא, מִשּׁוּם דֶּאֱלֹהֵיהֶם נִלְקִים בַּתְּחִלָּה, וְאַחַר כַּךְ הָאוּמָה, וְכֵן נִילוּס נִלְקָה בַּתְּחִלָּה, וְהָעֵצִים וְהָאֲבָנִים, הֲדָא הוּא דִכְתִיב, (שמות ז׳:כ״א) וַיְהִי הַדָּם בְּכָל אֶרֶץ מִצְרַיִם וּבָעֵצִים וּבָאֲבָנִים, שֶׁהָיוּ לָהֶם אֱלהוּת מַמָּשׁ. וְאָמַר רִבִּי יִצְחָק, עַל צְבָא הַמָּרוֹם בַּמָּרוֹם כְּתִּיב, וְנִילוּס לֹא הָיָה בַּמָּרוֹם. אָמַר רִבִּי יוֹחָנָן, רוֹב מֵימָיו כְּדוּגְמָתָן בַּמָּרוֹם. אָמַר רִבִּי יִצְחָק, שַׂר שֶׁלָּהֶם נִלְקָה בַּתְּחִלָּה, וְאַחַר כַּךְ שְׁאַר אֱלהֵיהֶם.</p>\n<p>רִבִּי שִׁמְעוֹן בְּרִבִּי יוֹסֵי אוֹמֵר, לָקוּת אוּמָה שֶׁל מִצְרַיִם מַמָּשׁ, לָא הָיָה אֶלָּא בַּיָּם, דִּכְתִּיב, (שמות י״ד:כ״ח) לא נִשְׁאַר בָּהֶם עַד אֶחָד. וְקוֹדֶם זֶה, נַעֲשָׂה שְׁפָטִים בֵּאלהֵיהֶם. וְעַל דָּא כְּתִיב, הָבָה נִּתְחַכְּמָה לוֹ פֶּן יִרְבֶּה וְהָיָה כִּי תִקְרֶאנָה. וְנִתְנַבְּאוּ עַל הֶעָתִיד, כְּפִי מַה שֶאֵירַע לָהֶם. וְנוֹסַף גַּם הוּא עַל שׂוֹנְאֵינוּ, נִבְּאוּ עַל מַחֲנוֹת עֶלְיוֹנִים, שֶׁיִּהְיוּ שְׁרוּיִים בְּתוֹכָם. וְנִלְחַם בָּנוּ, נִבְּאוּ עַל מַה דִּכְתִּיב, (שמות י״ד:י״ד) ה' יִלָּחֵם לָכֶם וְגוֹ'. וְעָלָה מִן הָאָרֶץ, כְּמָה דְּאַתְּ אָמַר (שמות י״ד:ח׳) וּבְנִי יִשְׂרָאֵל יוֹצְאִים בְּיַד רָמָה.</p>"],[9520011551,"<p>(שמות ב׳:א׳) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. רִבִּי אֶלְעָזָר פָּתַח, (שיר השירים א׳:א׳) שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. תָּנָא, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, עָלָה בְּחֵפֶץ לְפָנָיו, וּבָרָא אֶת הַשָּׁמָיִם בִּימִינוֹ וְהָאָרֶץ בִּשְׂמֹאלוֹ, וְעָלָה בְּחֵפֶץ לְפָנָיו, לִנְהוֹג הַיּוֹם וְהַלַּיְלָה. וּבָרָא הַמַּלְאָכִים הַמְמוּנִים בְּחַסְדּוֹ, בַּיּוֹם. (נ\"א לומר שירה ביום זמן החסד) וּבָרָא הַמַּלְאָכִים הַמְמוּנִים לוֹמַר שִׁירָה בַּלַּיְלָה. הֲדָא הוּא דִּכְתִּיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. אֵלּוּ מִיָּמִין, וְאֵלּוּ מִשְּׂמֹאל, אֵלּוּ מַקְשִׁיבִים שִׁירַת הַיּוֹם, שִׁירָתָם שֶׁל יִשְׂרָאֵל קָדוֹשׁ. רִבִּי יִצְחָק אָמַר, אוֹתָם שֶׁאוֹמְרִים שִׁירָה בַּלַּיְלָה, מַקְשִׁיבִים שִׁירָתָם שֶׁל יִשְׂרָאֵל בַּיּוֹם, הֲדָא הוּא דִּכְתִּיב, (שיר השירים ח׳:י״ג) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, כַּת אַחַת, כְּלוּלָה מִשָּׁלֹשׁ כִּתּוֹת, אוֹמֶרֶת שִׁירָה בַּלַּיְלָה. הֲדָא הוּא דִכְתִיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, עֲשָׂרָה דְּבָרִים נִבְרָאוּ בְּיוֹם רִאשׁוֹן, מֵהֶם מִדַּת לַיְלָה, וּמֵהֶם מִדַּת יוֹם, וְעַל מִדַּת לַיְלָה כְּתִיב, וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ. כְּמָה דְאַתְּ אָמֵר, (איוב ט״ז:ט׳) אַפּוֹ טָרַף. וּכְתִיב, (מיכה ה׳:ז׳) וְטָרַף וְאֵין מַצִּיל. וְחֹק לְנַעֲרוֹתֶיהָ, כְּמָה דְּאַתְּ אָמַר (שמות ט״ו:כ״ה) חֹק וּמִשְׁפָּט. (תהילים קמ״ז:י״ט) חֻקָּיו וּמִשְׁפָּטָיו. (תהלים פ\"א) כִּי חֹק לְיִשְׂרָאֵל הוּא מִשְׁפַּט וְגוֹ'. מִכָּאן שְׁמִדַּת הַדִּין שׁוֹלֶטֶת בַּלַּיְלָה.</p>\n<p>וְתָנָא, אֵלּוּ הָאוֹמְרִים שִׁירָה בַּלַּיְלָה, אֵלּוּ הֵם שָׂרִים עַל כָּל בַּעֲלֵי שִׁיר. וּכְשֶׁפּוֹתְחִין הַחַיִּים שִׁירָה, מוֹסִיפִים הָעֶלְיוֹנִים כֹּחַ, לָדַעַת וּלְהַכִּיר וּלְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיגוּ. שָׁמַיִם וָאָרֶץ, מוֹסִיפִין כֹּחַ בְּהַאי שִׁירָה.</p>\n<p>אָמַר רִבִּי נְחֶמְיָה, אַשְׁרֵי הַזּוֹכֶה לָדַעַת בְּאוֹתוֹ שִׁיר, דְּתַנְיָא הַזּוֹכֶה בְּאוֹתוֹ שִׁיר, יָדַע בְּעִנְיָנֵי הַתּוֹרָה וְהַחָכְמָה, וְיַאֲזִין וְיַחֲקוֹר וְיוֹסִיף כֹּחַ וּגְבוּרָה בַּמֶּה שֶׁהָיָה, וּבַמֶּה שֶׁעָתִיד לִהְיוֹת, וּבָזֶה זָכָה שְׁלמֹה לָדַעַת.</p>\n<p>דְּתָנֵי רִבִּי שִׁמְעוֹן, דָּוִד עָלָיו הֲשָׁלוֹם, יָדַע בָּזֶה, וְתִקֵּן שִּׁירִים וְתוּשְׁבָּחוֹת הַרְבֵּה, וְרָמַז בָּהֶם הָעֲתִידוֹת לָבוֹא, וְהוֹסִיף כֹחַ וּגְבוּרָה בְּרוּחַ הַקּוֹדֶשׁ. יָדַע בְּעִנְיָינִי הַתּוֹרָה וְהַחָכְמָה, וְאִזֵּן וְחִקֵּר וְהוֹסִיף כֹּחַ וּגְבוּרָה בְּלָשׁוֹן הַקּוֹדֶשׁ.</p>\n<p>וּשְׁלמֹה זָכָה יוֹתֵר בְּאוֹתוֹ הַשִּׁיר, וְיָדַע הַחָכְמָה, וְאִזֵּן וְחִקֵּר וְתִקֵּן מְשָׁלִים הַרְבֵּה, וְעָשָׂה סֵפֶר מֵאוֹתוֹ הַשִּׁיר מַמָּשׁ, וְהַיְינוּ דִּכְתִּיב, (קהלת ב׳:ח׳) עָשִׂיתִי לִי שָׁרִים וְשָׁרוֹת. כְּלוֹמַר, קָנִיתִי לִי לָדַעַת שִׁיר, מֵאוֹתָן הַשִּׁירִים הָעֶלְיוֹנִים, וַאֲשֶׁר תַּחְתָּם. וְהַיְינוּ דִּכְתִּיב, שִׁיר הַשִּׁירִים, כְּלוֹמַר, שִׁיר, שֶׁל אוֹתָם שָׁרִים שֶׁל מַעְלָה. שִׁיר, שֶכּוֹלֵל כָּל עִנְיְינֵי הַתּוֹרָה וְהַחָכְמָה, וְכֹחַ וּגְבוּרָה, בְּמַּה שֶׁהָיָה, וְעָתִיד לִהְיוֹת, שִׁיר הַשִּׁירִים שֶׁל מַעְלָה מְשׁוֹרְרִים.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אֵלּוּ הַשָׁרִים, עָמְדוּ, עַד שֶׁנּוֹלַד לֵוִי, אֲבָל מִשֶּׁנּוֹלַד לֵוִי וְאֵילָךְ אָמְרוּ שִׁיר. כֵּיוָן שֶׁנּוֹלַד מֹשֶׁה וְנִמְשַׁח אַהֲרֹן, וְנִתְקַדְּשוּ הַלְּוִיִּם, נִשְׁלָם הַשִּׁיר, וְעָמְדוּ עַל מִשְׁמְרוֹתָם.</p>\n<p>וְאָמַר רִבִּי אֶלְעָזָר, בְּאוֹתָה שָׁעָה שֶׁנּוֹלַד לֵוִי, פָּתְחוּ לְמַעְלָה וְאָמְרוּ, (שיר השירים ה') מִי יִתֶּנֵךָ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי <Nonei></i>אֶמְצָאֲךָ בַחוּץ אֶשָּׁקְךָ גַּם לא יָבוּזוּ לִי. כֵּיוָן שֶׁיָּצְאוּ מִשֵּׁבֶט לֵוִי הַמְּשׁוֹרְרִים שֶׁל מַטָּה, וְנִתְקַדְּשוּ כּוּלָּם, וְעָמְדוּ עַל מִשְׁמְרוֹתָם, וְנִתְקַדְּשוּ אֵלֶּה לְנוֹכַח אֵלֶּה, חֲבֵרִים כְּאֶחָד, וְהָעוֹלָמוֹת אֶחָד, וּמֶלֶךְ אֶחָד שׁוֹכֵן עֲלֵיהֶם, בָּא שְׁלמֹה, וְעָשָׂה סֵפֶר מֵאוֹתוֹ שִׁיר שֶׁל אוֹתָם שָׁרִים, וְנִסְתַּם הַחָכְמָה בּוֹ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, לָמָּה נִקְרְאוּ הַשָׁרִים שֶׁל מַטָּה לְוִיִּים, עַל שֶׁנִּלְוִים וְנֶחְבָּרִים לְמַעְלָה כְּאֶחָד. וְהָשּׁוֹמֵעַ, נִלְוָה וְנִדְבָּק נַפְשׁוֹ לְמַעְלָה. וְעַל כֵּן אָמְרָה לֵאָה, (בראשית כ״ט:ל״ד) יִלָּוֶה אִישִׁי אֵלַי. רִבִּי תַּנְחוּם אָמַר, שֶבַּכֹּל נִלְוָה זֶרַע לֵוִי עִם הַשְּׁכִינָה, בְּמֹשֶׁה וְאַהֲרֹן וּמִרְיָם, וּבְכָל זַרְעוֹ אַחֲרָיו, וְהֵם הַנִּלְוִים אֶל ה' לְשָׁרְתוֹ.</p>\n<p>תָּא חֲזֵי, בְּשָׁעָה שֶׁעָמְדוּ הַמְּשׁוֹרְרִים לְמַעְלָה, לא עָמְדוּ עַל מִשְׁמַרְתָּם, עַד שֶׁנּוֹלְדוּ שְׁלֹשָׁה הָאַחִים: מֹשֶׁה, אַהֲרֹן, וּמִרְיָם. תִּינַח מֹשֶׁה וְאַהֲרֹן, מִרְיָם לָמָּה. אָמַר רִבִּי יוֹסֵי, הֲדָא הוּא דִכְתִיב, (קהלת ב') וְשָׁרוֹת. כְּמָה דְאַתְּ אָמֵר, (שמות ט״ו:כ״א) וַתַּעַן לָהֶם מִרְיָם.</p>\n<p>תָּאנָא, בְּאוֹתָה שָׁעָה שֶׁנּוֹלַד לֵוִי, נְטָלוֹ הַקָדוֹשׁ בָּרוּךְ הוּא, וּבְחָרוֹ מִכָּל אֶחָיו וְהוֹשִׁיבוֹ בָּאָרֶץ, וְהוֹלִיד לִקְהָת, וּקְהָת הוֹלִיד לְעַמְרָם, וְהוּא הוֹלִיד לְאַהֲרֹן וּמִרְיָם. פֵּירַשׁ מֵאִשְׁתּוֹ, וְהֶחזִירָהּ, בְּאוֹתָה שָׁעָה הָיוּ הַמְשׁוֹרְרִים שֶׁל מַעְלָה עוֹמְדִים וּמְשׁוֹרְרִים, גָּעַר בָּהֶם הַקָדוֹשׁ בָּרוּךְ הוּא, וְנִשְׁתָּכַּךְ הַשִּׁיר, עַד שֶׁנָּטָה קַו יְמִינוֹ, וְהוֹשִיט לְעַמְרָם.</p>\n<p>מַאי טַעְמָא נִקְרָא עַמְרָם. שֶׁיָּצָא מִמֶּנּוּ עַם רָם עַל כָּל רָמִים, וְלֹא נִזְכַּר שְׁמוֹ. מַאי טַעְמָא לֹא נִזְכַּר שְׁמוֹ. רִבִּי יְהוּדָה אָמַר בְּשֵׁם רִבִּי אֲבָהוּ, מִפְּנֵי שֶׁבְּצִנְעָא הָלַךְ, וּבְצִנְעָא חָזַר לְאִשְׁתּוֹ, כְּדֵי שֶׁלֹּא יַכִּירוּ בּוֹ, הֲדָא הוּא דִכְתִיב וַיֵּלֶךְ אִישׁ, וְלָא נֶאֱמַר וַיֵּלֶךְ עַמְרָם בְּפַרְהֶסְיָא. וַיִּקַּח אֶת בַּת לֵוִי, אַף הִיא בְּצִנְעָא חָזְרָה, וְלֹא נִזְכְּרָה שְׁמָהּ.</p>"],[9520011552,"<p>וַיֵּלֶךָ אִישׁ. רִבִּי אֲבָהוּ אָמַר, וַיֵּלֶךְ אִישׁ, זֶה גַּבְרִיאֵל. דִּכְתִּיב, (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל. שֶׁהָלַךְ הוּא וְהֶחזִירָהּ לְעַמְרָם. רִבִּי יְהוּדָה אָמַר, עַמְרָם מַמָּשׁ הָיָה, וְלֹא נִזְכַּר שְׁמוֹ, מִפְּנֵי שֶׁהֲלִיכָה זוֹ לֹא הָיְתָה מִמֶּנּוּ לְהִזְדַּוֵּוג לְאִשְׁתּוֹ, אֶלָּא מִלְּמַעְלָה.</p>\n<p>רִבִּי יִצְחָק אָמַר, בְּאַהֲרֹן וּמִרְיָם לא נְאֱמַר זִיוּוּג אֲבוֹתָם בַּתּוֹרָה, וּבְמֹשֶׁה כְּתִּיב וַיִּקַּח אֶת בַּת לֵוִי, לְהוֹרוֹת, שֶׁהַשְּׁכִינָה נִקְרֵאת עַל שֵׁם לֵוִי. וְלא הָיָה עַמְרָם רָאוּי לְהוֹלִיד לְמֹשֶׁה, עַד שֶׁנָּטַל חֵלֶק בַּשְּׁכִינָה, וְהוֹלִיד לְמֹשֶׁה. הֲדָא הוּא דִּכְתִּיב, וַיִּקַּח אֶת בַּת לֵוִי. וּלְפִיכָךְ כְּתִיב, (שמות ב׳:א׳) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, זָכָה עַמְרָם שֶׁיָּצָא מִמֶּנּוּ בֶּן, שֶׁזָּכָה לְקוֹל גָּדוֹל, דִּכְתִּיב, (שמות י״ט:י״ט) וְהָאֱלהִים יַעֲנֶנּוּ בְּקוֹל. וְעַמְרָם זָכָה לְבַת קוֹל, דִּכְתִּיב וַיִּקַּח אֶת בַּת לֵוִי. כְּלוֹמַר, בַּת קוֹל. וּלְפִיכָךְ כְּתִיב וַיֵּלֶךְ. כְּלוֹמַר, שֶׁהָלַךְ לְמַדְרֵגָה זוֹ. תָּאנָא, כְּשֶׁנּוֹלַד מֹשֶׁה, יִיחֵד הַקָדוֹשׁ בָּרוּךְ הוּא שְׁמוֹ עָלָיו, דִּכְתִּיב וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא. וּכְתִיב, (תהילים קמ״ה:ט׳) טוֹב ה' לַכֹּל. וּכְתִיב, (תהילים ל״ד:ט׳) טַעֲמוּ וּרְאוּ כִּי טוֹב ה'.</p>"],[9520011553,"<p>(שמות ב׳:כ״ג) וַיְהִי בַיָּמִים הָרַבִּים הָהֵם. רִבִּי יְהוֹשֻׁעַ דְּסַכְנִין אָמַר, וַיְהִי בַיָּמִים הָרַבִּים הָהֵם, סוֹף גָּלוּתָם הָיָה, שֶׁהָיוּ יִשְׂרָאֵל מְשׁוּעֲבָּדִים בְּכָל עֲבוֹדָה. בַּיָּמִים הָרַבִּים הָהֵם, שֶׁהָיוּ רָבִּים לְיִשְׂרָאֵל בְּמִצְרַיִם, וְכֵיוָן שֶׁנִּשְׁתַּלַּם קֵץ גָּלוּתָם, מַה כְּתִיב, וַיָּמָת מֶלֶךְ מִצְרַיִם. מַאי טַעְמָא. שֶׁהוּרַד שַׂר מִצְרַיִם מִמַּעֲלָתוֹ, וְנָפַל מִגַּאֲוָתוֹ. וְכֵיוָן שֶׁנָּפַל מֶלֶךְ מִצְרַיִם, שֶׁהוּא שַׂר שֶׁלָּהֶן, זָכַר הַקָדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, וְשָׁמַע תְּפִלָּתָם.</p>"],[9520011554,"<p>אָמַר רִבִּי יְהוּדָה, בֹּא וּרְאֵה שֶׁכַּךְ הוּא, שֶׁכָּל זְמָן שֶׁהַשַׂר שֶׁלָּהֶם נִתְנָה לוֹ שְׂרָרָה עַל יִשְׂרָאֵל, לא נִשְׁמַע צַעֲקָתָם שֶׁל יִשְׂרָאֵל, כֵּיוָן שֶׁנָּפַל הַשַּׂר שֶׁלָּהֶם, כְּתִיב וַיָּמָת מֶלֶךְ מִצְרַיִם, וּמִיָּד וַיֵּאָנְחוּ בְּנֵי יִשְׂרָאֵל מִן הָעֲבוֹדָה וַיִזְעָקוּ וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים. שֶׁעַד אוֹתָהּ שָׁעָה לא נַעֲנוּ בְּצַעֲקָתָם.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, בֹּא וּרְאֵה רַחֲמָנוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁהוּא מְרַחֵם עַל יִשְׂרָאֵל, כּוֹפֶה לְמִדַּת הַדִּין, וּמוֹרִידָהּ, וּמְרַחֵם עֲלֵיהֶם. וְהַיְינוּ דִּתְנָן, שֶׁהַּקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיד שְׁתֵּי דְּמָעוֹת לַיָּם הַגָּדוֹל. מַאן אִינּוּן שְׁתֵּי דְּמָעוֹת. אָמַר רִבִּי יוֹסֵי, לָאו <Nonei></i>מִלָּא בְּרִירָא הִיא, דְּהָא אֲמַר לֵיהּ לְאוֹבָא טַמְיָא, דְּהוּא כָּדִיב, וּמִלֵיה כְּדִיבָן.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, לָאו בָּתַר אוֹבָא טַמְיָא אַזְלִינָן, דִּבְרִירָא דְּמִלָּה הוּא, דִּתְנָן, בַּעֲשָׂרָה כִּתְרֵי מַלְכָּא, אִית תְּרֵין דִּמְעִין לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהֵן שְׁתֵּי מִדּוֹת דִּין, שֶׁהַדִּין בָּא מִשְּׁתֵּיהֶן, כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״א:י״ט) שְׁתַּיִם הִנֵּה קוֹרְאוֹתַיִךְ. וּכְשֶׁהַקָדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת בָּנָיו, הוּא מוֹרִיד אוֹתָם לַיָּם הַגָּדוֹל, שֶׁהוּא (ויקרא קל\"ז ע\"ב) יָם הַחָכְמָה לְהַמְתִּיקָן, וְהוֹפֵךְ מִדַּת הַדִּין לְמִדַּת רַחֲמִים, וּמְרַחֵם עָלַיְיהוּ. אָמַר רִבִּי יְהוּדָה, שְׁתֵּי דְּמָעוֹת, שֶׁמֵּהֶם בָּאִים הַדְּמָעוֹת, מֵהֶם בָּא הַדִּין.</p>\n<p>אָמַר רִבִּי יְהוּדָה כְּתִיב, (שמות י״ד:י׳) וְהִנֵּה מִצְרַיִם נוֹסֵעַ אַחֲרֵיהֶם. וְאָמַר רִבִּי יוֹסֵי זֶה שַׂר שֶׁל מִצְרַיִם הוּא, וְאַתְּ אָמַרְתְּ וַיָּמָת מֶלֶךְ מִצְרַיִם, זֶה שַׂר שֶׁל מִצְרַיִם. אָמַר רִבִּי יִצְחָק, הַאי מִלָּה קָא מְסַיֵּיעַ לְהַהוּא דִּלְעֵילָּא, כְּתִיב הָכָא וְהִנֵּה מִצְרַיִם, וּכְתִיב הָתָם וַיָּמָת מֶלֶךְ מִצְרַיִם. מְלַמֵּד דְּעַכְשָׁיו לא הָיָה מֶלֶךְ, דְּהוֹרִידוּהוּ מִגְּדוּלָתוֹ. וּלְפִיכָךְ כְּתִיב, וְהִנֵּה מִצְרַיִם, וְלָא כְּתִיב מֶלֶךְ מִצְרַיִם. וּמַה דְּאָמַר וַיָּמָת. כְּמָה דְאַתְּ אָמֵר (שמות ד׳:י״ט) כִּי מֵתוּ כָּל הָאֲנָשִׁים הַמְבַקְשִׁים אֶת נַפְשֶׁךָ.</p>\n<p>אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוֹשֻׁעַ, בֹּא וּרְאֵה, כָּל מַלְכֵי מִצְרַיִם פַּרְעֹה שְׁמָם. וּבְכָאן לֹא נֶאֱמַר אֶלָּא מֶלֶךְ מִצְרַיִם סְתָם. וּבִמְקוֹמוֹ פַּרְעֹה, וְהוּא פַּרְעֹה מַמָּשׁ. תָּא חֲזֵי, בְּעוֹד דְּאִית שׁוּלְטָנוּתָא דִּלְעֵילָּא, אִית שׁוּלְטָנוּתָא בְּעַמָּא דִּלְתַתָּא, אִתְעָדֵי שׁוּלְטָנוּתָא דִּלְעֵילָּא, אִתְעָדֵי שׁוּלְטָנוּתָא דִּלְתַתָּא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כְּתִיב (זכריה י\"ד) הִנִּה יוֹם בָּא לַיְיָ' וְגוֹ' וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ' וְגוֹ'. וְכִי שְׁאַר יוֹמִין לָאו אִינּוּן דִּילֵיהּ. אֶלָּא אָמַר רִבִּי אַבָּא, מְלַמֵּד, שֶׁשְּׁאָר הַיָּמִים, נִתָּנִים לְשָׂרִים, וְאוֹתוֹ יוֹם, אֵינוֹ שֶׁל הַשָּׂרִים, אֶלָּא שֶׁל הַקָדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לַעֲשׂוֹת דִּין בַּעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. מִפְּנִי שֶׁבְּאוֹתוֹ יוֹם, יִפְּלוּ כָּל הַשָּׂרִים מִמַּעֲלָתָם. וְעַל דָּא כְּתִיב, (ישעיהו ב׳:י״א) וְנִשְׂגַּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא. שֶׁאוֹתוֹ יוֹם לא יִהְיֶה מַעֲלָה לְשָּׂרִים.</p>"],[9520011555,"<p>אָמַר רִבִּי אַבָּא, כְּשֶׁהַקָדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִּין בַּשָּׂרִים שֶׁל מַעְלָה, מַה כְּתִיב, (ישעיהו ל״ד:ה׳) כִּי רִוְּתָה בַּשָׁמַיִם חַרְבִּי. וְכִי חֶרֶב אִית לַיְיָ'. אֶלָּא אָמַר רִבִּי יִצְחָק, חֶרֶב אִית לֵיהּ, דִּכְתִּיב, (ישעיהו ל״ד:ה׳) חֶרֶב לַיְיָ' מָלְאָה דָּם. וּכְתִיב (ישעיהו ס״ו:ט״ז) וּבְחַרְבּוֹ אֶת כָּל בָּשָׂר.</p>\n<p>אָמַר רִבִּי אַבָּא, הַחֶרֶב הַזֶּה הוּא הַדִּין שֶׁעוֹשֶׂה, דִּכְתִּיב, (דברי הימים א כ״א:ט״ז) וַיַּרְא (דוד) אֶת מַלְאַךְ ה' עוֹמֵד בֵּין הָאָרֶץ וּבֵין הַשָּׁמַיִם וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. וְכִי חֶרֶב שְׁלוּפָה הָיְתָה בְּיַד הַמַּלְאָךְ, אֶלָּא, שֶׁהָיְתָה הָרְשׁוּת נְתוּנָה בְּיָדוֹ לַעֲשׂוֹת דִּין.</p>\n<p>וְהָא אָמַר רִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, אָמַר לִי מַלְאָךְ הַמָּוֶת, אִי לָאו דְּחֵיְיסְנָא לִיקָרָא דְּבִרְיָיתָא, פָּרַעְנָא לְהוּ בֵּית הַשְּׁחִיטָה, כַּבְּהֵמָה. אָמַר רִבִּי אַבָּא, כֹּלָּא מִשּׁוּם דְּאִתְיְיהִיב רְשׁוּתָא בִּידֵיהּ, לְמֶעְבַּד גְּמַר דִּינָא, הֲדָא הוּא דִכְתִיב, (יהושע ה׳:י״ג) וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ, הָרְשׁוּת נְתוּנָה בְּיָדוֹ לַעֲשׂוֹת דִּין. אִי הָכִי מַאי (דברי הימים א כ״א:כ״ז) וַיָּשֶׁב חַרְבּוֹ אֶל נְדָנָהּ. אָמַר רִבִּי אַבָּא, שֶׁנֶּחֱזַר הַדִּין לְבַעַל הַדִּין, וְהָרְשׁוּת לְמִי שֶהָרְשׁוּת שֶׁלּוֹ.</p>"],[9520011556,"<p>וַיֵּאָנְחוּ בְּנֵי יִשְׂרָאֵל, וַיִּתְאַנְּחוּ לָא כְּתִיב, אֶלָּא וַיֵּאָנְחוּ, כְּלוֹמַר, נִתְאַנְּחוּ (ס\"א האניחו) לוֹ לְמַעְלָה (ס\"א כלומר נאנחו למטה) שֶׁהָאֲנָחָה הָיְתָה בִּשְׁבִילָם לְמַעְלָה.</p>\n<p>ר' בְּרֶכְיָה אָמַר, בְּנֵי יִשְׂרָאֵל דִּלְעֵילָּא הֲווֹ, וּמַאן אִינּוּן בְּנֵי יִשְׂרָאֵל. אִינּוּן דְּאִתְקְרוּן בְּנֵי פּוּלְחָנָא. כְּלוֹמַר, אוֹתָם שֶׁהֵם מִן הָעֲבוֹדָה שֶׁל מַעְלָה. וַתַּעַל שַׁוְעָתָם אֶל הָאֱלהִים, שֶׁעַד אוֹתָהּ שָׁעָה לָא עָלְתָה שַׁוְעָתָם לְפָנָיו.</p>\n<p>אָמַר רִבִּי יִצְחָק כַּד עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּפָמַלְיָיא שֶׁל מַעְלָה, הַהוּא דִּינָא מַאי הֲוֵי. אָמַר רִבִּי אֶלְעָזָר, מַעְבַּר לְהוּ בְּהַהוּא נְהַר דִּינוּר, וְאַעְבַּר לוֹן מִשּׁוּלְטָנֵיהוֹן, וּמָנֵי שׁוּלְטָנִין אַחֲרָנִין דִּשְׁאַר עַמִּין. אֲמַר לֵיהּ וְהָא כְּתִיב (תהילים ק״ד:ד׳) מְשָׁרְתָיו אֵשׁ לוֹהֵט. אֲמַר לֵיהּ, אִית אֶשָּׁא קַשְׁיָא מֵאֶשָּׁא, וְאִית אֶשָּׁא דְּדַחְיָא אֶשָּׁא.</p>"],[9520011557,"<p>אָמַר רִבִּי יִצְחָק, תְּלַת עִנְיָינֵי הָכָא: אֲנָחָה, שַׁוְעָה, צְעָקָה. וְכָל חַד מִתְפָּרְשָׁא מְאַחֲרָא. אֲנָחָה: כְּתִּיב, וַיֵּאָנְחוּ בְּנֵי יִשְׂרָאֵל. צְעָקָה: דִּכְתִּיב, וַיִּצְעָקוּ. שַׁוְעָה: דִּכְתִּיב, וַתַּעַל שַׁוְעָתָם. וְכָל חַד בִּלְחוֹדוֹי מִתְפָּרְשָׁא, וְכֻלְּהוּ עָבְדוּ יִשְׂרָאֵל. אָמַר רִבִּי יְהוּדָה, צְעָקָה וְשַׁוְעָה עָבְדוּ, אֲנָחָה לָא עָבְדוּ, מַשְׁמַע מִדִּכְתִּיב וַיֵּאָנְחוּ וּלְמַעְלָה הָיְתָה הָאֲנָחָה בִּשְׁבִילָם.</p>\n<p>צְעָקָה וְשַׁוְעָה בְּמַאי אִתְפָּרְשָׁן, אָמַר רִבִּי יִצְחָק, אֵין לָךְ שַׁוְעָה, אֶלָּא בַּתְּפִלָה. שֶׁנֶּאֱמַר, (תהילים ל״ט:י״ג) שְׁמָעָה תְפִלָּתִי יְיָ' וְשַׁוְעָתִי הַאֲזִינָה. (תהלים פ\"ח) אֵלֶיךָ יְיָ' שִׁוַּעְתִּי. (תהילים ל׳:ג׳) שִׁוַּעְתִּי אֵלֶיךָ וַתִּרְפָּאֵנִי. צְעָקָה שֶׁצּוֹעֵק וְאֵינוֹ אוֹמֵר כְּלוּם. אָמַר רִבִּי <Nonei></i>יְהוּדָה, הִלְכָּךְ גְּדוֹלָה צְעָקָה מִכּוּלָּן, שֶׁצְּעָקָה הִיא בַּלֵּב. הֲדָא הוּא דִכְתִיב, (איכה ב׳:י״ח) צָעַק לִבָּם אֶל יְיָ'. צְעָקָה וּזְעָקָה דָּבָר אֶחָד הוּא, וְזֶה קְרוֹבָה לְהַקָדוֹשׁ בָּרוּךְ הוּא, יוֹתֵר מִתְּפִלָּה וַאֲנָחָה, דִּכְתִּיב, (שמות כ״ב:כ״ב) כִּי אִם צָעוֹק יִצְעַק אֵלַי שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ.</p>\n<p>אָמַר רִבִּי בְּרֶכְיָה, בְּשָׁעָה שֶׁאָמַר הַקָדוֹשׁ בָּרוּךְ הוּא לִשְׁמוּאֵל, (שמואל א ט״ו:י״א) נִחַמְתִּי כִּי הִמְלַכְתִּי אֶת שָׁאוּל לְמֶלֶךְ. מַה כְּתִּיב, וַיִּחַר לִשְׁמוּאֵל, וַיִצְעַק אֶל יְיָ' כָּל הַלַּיְלָה. הִנִּיחַ הַכֹּל, וְלָקַח צְעָקָה, מִשּׁוּם דְּהִיא קְרוֹבָה לְקוּדְשָׁא בְּרִיךְ הוּא יַתִּיר מִכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלָי.</p>\n<p>תָּנוּ רַבָּנָן, הַאי מַאן דְּצַלֵּי וּבָכֵי וְצָעִיק, עַד לָא יָכִיל לְמִרְחָשׁ בְּשִׂפְוָותֵיהּ, הַאי צְלוֹתָא שְׁלֵימָתָא דְּהִיא בְּלִבָּא, וּלְעוֹלָם לָא הַדְרָא רֵיקָנַיָּא. אָמַר רִבִּי יְהוּדָה, גְּדוֹלָה צְעָקָה, שְׁקוֹרֵעַ גְּזַר דִּינוֹ שֶׁל אָדָם מִכָּל יָמָיו.</p>\n<p>רִבִּי יִצְחָק אָמַר, גְּדוֹלָה צְעָקָה, שֶׁמּוֹשֶׁלֶת עַל מִדַּת הַדִּין שֶׁל מַעְלָה. רִבִּי יוֹסֵי אָמַר, גְּדוֹלָה צְעָקָה, שֶׁמּוֹשֶׁלֶת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בִּשְׁבִיל צְעָקָה נוֹחֵל הָאָדָם הָעוֹלָם הַזֶּה וּהָעוֹלָם הַבָּא, דִּכְתִּיב, (תהילים ק״ז:ו׳) וַיִּצְעֲקוּ אֶל ה' בַּצַּר לָהֶם מִמְּצוּקוֹתֵיהֶם יַצִּילֵם.</p>"],[9520011558,"<p>(שמות ג׳:א׳) וּמֹשֶׁה הָיָה רוֹעֶה אֶת צֹאן יִתְרוֹ חוֹתְנוֹ כֹּהֵן מִדְיָן. רִבִּי שִׁמְעוֹן פָּתַח, (שיר השירים ב׳:ט״ז) דּוֹדִי לִי וַאֲנִי לוֹ הָרוֹעֶה בַּשּׁוֹשַׁנִּים. אָמַר רַבִּי שִׁמְעוֹן, אוֹי לָהֶם לַבְּרִיּוֹת, שֶׁאֵינָם מַשְׁגִּיחִים וְאֵינָם יוֹדְעִים, בְּשָׁעָה שֶׁעָלָה בְּמַחֲשָׁבָה לִפְנִי הַקָּדוֹשׁ בְּרִיךְ הוּא, לִבְרוֹא עוֹלָמוֹ, כָּל הָעוֹלָמוֹת עָלוּ בְּמַחֲשָׁבָה אַחַת, וּבְמַחֲשָׁבָה זוּ נִבְרָאוּ כּוּלָּם, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ. וּבְמַחֲשָׁבָה זוּ, שֶׁהִיא הַחָכְמָה, נִבְרָא הָעוֹלָם הַזֶּה, וְהָעוֹלָם שֶׁל מַעְלָה.</p>\n<p>נָטָה יְמִינוֹ, וּבָרָא הָעוֹלָם שֶׁל מַעְלָה. נָטָה שְׂמֹאלוֹ, וּבָרָא הָעוֹלָם הַזֶּה, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ח:י״ג) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם. קוֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו. וְכֻלָּם בְּרֶגַע אַחַת (ובשעה אחת) נִבְרָאוּ, וְעָשָׂה הָעוֹלָם הַזֶּה, כְּנֶגֶד הָעוֹלָם שֶׁל מַעְלָה. וְכָל מַה שֶּׁיֵּשׁ לְמַעְלָה, כְּדוּגְמָתוֹ לְמַטָּה. וְכָל מַה שֶּׁיֵּשׁ לְמַטָּה, כְּדוּגְמָתוֹ בַּיָּם. וְהַכֹּל אֶחָד. בָּרָא בָּעֶלְיוֹנִים הַמַּלְאָכִים, בָּרָא בָּעוֹלָם הַזֶּה בְּנֵי אָדָם, בָּרָא בַּיָּם לִוְיָתָן, כְּמָה דְאַתְּ אָמֵר (שמותל\"ו) לְחַבֵּר אֶת הָאֹהֶל לִהְיוֹת אֶחָד.</p>\n<p>כְּתִיב בָּאָדָם, (בראשית ט׳:ו׳) כִּי בְּצֶלֶם אֱלהִים עָשָׂה אֶת הָאָדָם. וּכְתִיב, (תהילים ח׳:ו׳) וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים. אִי בְּנִי נָשָׁא יַקִּירִין בְּעוֹבַדָיְיהוּ (נ\"א בעובדוי) כָּל הַאי, וְאִינּוּן מִתְאַבְּדִין (מטפה) מֵעָפָר דְּבֵירָא, בְּמָּה אַתְיָין לְשַׁאֲבָא מִנֵיהּ. וּבָחַר בָּעֶלְיוֹנִים, וּבָחַר בְּיִשְׂרָאֵל, לָעֶלְיוֹנִים לא קָרָא בָּנִים, לַתַּחְתּוֹנִים קָרָא בָּנִים. הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַה' אֱלהֵיכֶם. הוּא קָרָא לָהֶם בָּנִים, וְהֵם קָרְאוּ לוֹ אָב, דִּכְתִּיב, (ישעיהו ס״ג:ט״ז) כִּי אַתָּה אָבִינוּ. וּכְתִיב דּוֹדִי לִי וַאֲנִי לוֹ. הוא בָּחַר בִּי, וַאֲנִי בָּחַרְתִּי בּוֹ.</p>\n<p>הָרוֹעֶה בַּשּׁוֹשַׁנִּים, הוּא רוֹעֶה בַּשּׁוֹשַׁנִּים, אַף עַל פִּי שֶׁהַקּוֹצִים סָבִיב לָהֶם, וְאֵין אַחֵר יָכוֹל לִרְעוֹת בַּשּׁוֹשַׁנִּים כְּמוֹתוֹ. דָּבָר אַחֵר הָרוֹעֶה בַּשּׁוֹשַׁנִּים, מַה שׁוּשָן זֶה הוּא אָדוֹם, וּמֵימָיו לְבָנִים, כַּךְ הַקָדוֹשׁ בָּרוּךְ הוּא, מַנְהִיג עוֹלָמוֹ, מִמִדַּת הַדִּין לְמִדַּת הָרַחֲמִים. וּכְתִיב (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ.</p>\n<p>רִבִּי אַבָּא הֲוָה אָזִיל בְּאוֹרְחָא, וַהֲוָה עִמֵּיהּ רִבִּי יִצְחָק. אַדְהֲווֹ אַזְלֵי, פָּגַע בְּאִינוּן וְרָדִים, נָטַל חַד רִבִּי אַבָּא בִּידוֹי וַהֲוָה אָזִיל. פָּגַע בְּהוּ רִבִּי יוֹסֵי, אָמַר וַדַּאי שְׁכִינְתָּא הָכָא, וַאֲנָא חֲמֵינָא בִּידוֹי דְּרִבִּי אַבָּא, לְמֵילָף חָכְמְתָא סַגִּיאָה, דְּהָא יָדַעְנָא, דְּרִבִּי אַבָּא לָא נָטַל הַאי, אֶלָּא לְאַחֲזָאָה חָכְמְתָא.</p>\n<p>אָמַר רִבִּי אַבָּא, תִּיב בְּרִי תִּיב. יָתְבוּ. אָרַח רִבִּי אַבָּא בְּהַהוּא וַרְדָא, אָמַר, וַדַּאי אֵין הָעוֹלָם מִתְקַיֵּים אֶלָּא עַל הָרֵיחַ. דְּהָא חָזֵינָא דְּלֵית נַפְשָׁא מִתְקַיְּימָא אֶלָּא עַל רֵיחָא. וְעַל דָּא, הֲדַס בְּמוֹצָאֵי שַׁבָּת.</p>\n<p>פָּתַח וְאָמַר דּוֹדִי לִי וַאֲנִי לוֹ הָרוֹעֶה בַּשּׁוֹשַׁנִּים. מִי גָּרַם לִי, שֶׁאֲנִי לְדוֹדִי וְדוֹדִי לִי, מִפְּנֵי שֶׁהוּא מַנְהִיג עוֹלָמוֹ בַּשּׁוֹשַׁנִּים. מַה שׁוֹשָׁן יֵשׁ בּוֹ רֵיחַ, וְהוּא אָדוֹם, מוֹצְקִין אוֹתוֹ, וְהוּא מִתְהַפֵּךְ לַלָבָן, וּלְעוֹלָם רֵיחוֹ לֹא זָז. כַּךְ הַקָדוֹשׁ בָּרוּךְ הוּא, מַנְהִיג עוֹלָמוֹ בְּדֶרֶך זֶה, שֶׁאִלְמָלֵא כֵּן לֹא יִתְקַיֵּים הָעוֹלָם בִּשְׁבִיל הָאָדָם הַחוֹטֵא. וְהַחוֹטֵא נִקְרָא אָדוֹם, כְּמָה דְּאַתְּ אָמַר, אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג <Nonei></i>יַלְבִּינוּ, מַקְרִיב קָרְבָּנוֹ לָאֵשׁ שֶׁהוּא אָדוֹם. זוֹרֵק הַדָּם, סָבִיב לַמִּזְבֵּחַ שֶׁהוּא אָדוֹם. מִדַּת הַדִּין אָדוֹם, מוֹצְקִין אוֹתוֹ, (הריח) וְעוֹלֶה הֶעָשָׁן כֻּלּוֹ לָבָן, וְאָז הָאָדוֹם נֶהְפַּךְ לְלָבָן, נֶהְפַּךְ מִדַּת הַדִּין לְמִדַּת הָרַחֲמִים.</p>\n<p>וְתָא חֲזֵי, כָּל מִדַּת הַדִּין, אֵין צָרִיךְ הָרֵיחַ שֶׁלּוֹ, אֶלָּא מִצַּד אוֹדֶם. וְהַיְינוּ דְּאָמַר רִבִּי יְהוּדָה, מַה דִּכְתִּיב, (מלכים א י״ח:כ״ח) וַיִּתְגּוֹדְדוּ כְּמִשְׁפָּטָם וְגוֹ' עַד שְׁפָךְ דָּם עֲלֵיהֶם. אֶלָּא הָיוּ יוֹדְעִים, שֶׁלּא יַשִּׂיגוּ מִמִּדַּת הַדִּין כִּרְצוֹנָם, זוּלָתִי בָּאוֹדֶם.</p>\n<p>אָמַר רִבִּי יִצְחָק, וְעוֹד, אוֹדֶם וְלָבָן נִקְרַב לְעוֹלָם, וְהָרֵיחַ עוֹלֶה מִשְּׁתֵּיהֶן. מַה הַשׁוֹשָׁן אָדוֹם וְלָבָן, כַּךְ רֵיחַ הַקָּרְבָּן. וְהַקָּרְבָּן, מֵאָדוֹם וְלָבָן. בֹּא וּרְאֵה מֵרֵיחַ הַקְּטוֹרֶת, שֶׁהַשְׁמָנִים, מֵהֶם אֲדוּמִים, וּמֵהֶם לְבָנִים, כְּגוֹן הַלְּבוֹנָה, שֶׁהוּא לָבָן, מָר דְּרוֹר אָדוֹם, וְהָרֵיחַ עוֹלֶה מֵאָדוֹם וְלָבָן. וְעַל כֵּן מַנְהִיג עוֹלָמוֹ בַּשּׁוֹשַׁנִּים, שֶׁהוּא אָדוֹם וְלָבָן. וּכְתִיב (יחזקאל מ״ד:ט״ו) לְהַקְרִיב לִי חֵלֶב וָדָם.</p>\n<p>כְּנֶגֶד זֶה, אָדָם מַקְרִיב חֶלְבּוֹ וְדָמוֹ, וּמִתְכַּפֵּר לוֹ, זֶה אָדוֹם, וְזֶה לָבָן. מַה הַשּׁוֹשָׁן שֶׁהוּא אָדוֹם וְהוּא לָבָן, אֵין מוֹצְקִין אוֹתוֹ לַחֲזוֹר כֻּלּוֹ לָבָן, אֶלָּא בָּאֵשׁ. כַּךְ הַקָּרְבָּן אֵין מוֹצְקִין אוֹתוֹ לַחֲזוֹר כֻּלּוֹ לָבָן, אֶלָּא בָּאֵשׁ. עַכְשָׁיו, מִי שֶׁיּוֹשֵׁב בְּתַעֲנִיתוֹ, וּמַקְרִיב חֶלְבּוֹ וְדָמוֹ, אֵינוֹ נִצְמַק לַחֲזוֹר כֻּלּוֹ לָבָן, אֶלָּא בָּאֵשׁ. דאר\"י, מִתּוֹךְ תַּעֲנִיתוֹ שֶׁל אָדָם, מַחֲלִישִׁין אֵבָרָיו, וְגוֹבֵר עָלָיו הָאֵשׁ, וּבְאוֹתָהּ שָׁעָה, צָרִיךְ לְהַקְרִיב חֶלְבּוֹ וְדָמוֹ בְּאוֹתוֹ הָאֵשׁ, וְהוּא הַנִּקְרָא מִזְבַּח כַּפָּרָה.</p>\n<p>וְהַיְינוּ דְּרִבִּי אֶלְעָזָר, כַּד הֲוָה יָתִיב בְּתַעֲנִיתָא, הֲוָה מְצַלֵּי וְאָמַר, גָּלוּי וְיָדוּעַ לְפָנְיךָ ה' אֱלהַי וִאלהֵי אֲבוֹתַי, שֶׁהִקְרַבְתִּי לְפָנֶיךָ חֶלְבִּי וְדָמִי, וְהִרְתַּחְתִּי אוֹתָם בַּחֲמִימוּת חוּלְשַׁת גּוּפִי, יְהִי רָצוֹן מִלְּפָנֶיךָ, שֶׁיְּהֵא הָרֵיחַ הָעוֹלָה מִפִּי בְּשָׁעָה זוֹ, כְּרִיחַ הָעוֹלֶה מֵהַקָּרְבָּן בָּאֵשׁ הַמִּזְבֵּחַ, וְתִרְצֵנִי.</p>\n<p>נִמְצָא, שֶׁאָדָם הוּא מַקְרִיב בְּתַעֲנִיתוֹ הַחֵלֶב וְהַדָּם, וְהָרֵיחַ שֶׁעוֹלֶה מִפִּיו, הוּא מִזְבַּח כַּפָּרָה, וּלְפִיכָךְ תִּקְנוּ הַתְּפִלָּה בַּמָּקוֹם הַקָּרְבָּן, וּבִלְבַד שֶׁיִּתְכַּוֵין לְמָה דְּאַמָרָן. אָמַר רִבִּי יִצְחָק, מִכָּאן וּלְהָלְאָה כְּתִיב, (במדבר ל״א:כ״ג) כָּל דָּבָר אֲשֶׁר יָבוֹא בָּאֵשׁ תַּעֲבִירוּ בָּאֵשׁ וְטָהֵר. אָמַר רִבִּי יוֹסֵי, כְּשֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּים, אָדָם מַקְרִיב קָרְבָּנוֹ בְּעִנְיָן זֶה, וּמִתְכַּפֵּר לוֹ. עַכְשָׁיו, תְּפִלָּתוֹ שֶׁל אָדָם מְכַפֵּר לוֹ בִּמְקוֹם הַקָּרְבָּן, כִּי הַאי גַּוְונָא.</p>\n<p>דָּבָר אַחֵר, דּוֹדִי לִי וַאֲנִי לוֹ הָרוֹעֶה בַּשּׁוֹשַׁנִּים. מַה הַשׁוֹשַׁנִּים קוֹצִין מְצוּיִין בְּתוֹכָם, אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, מַנְהִיג עוֹלָמוֹ בְּצַדִּיקִים וּרְשָׁעִים. מַה הַשׁוֹשַׁנִּים, אִלְמָלֵא הַקּוֹצִים, אֵין הַשׁוֹשַׁנִּים מִתְקַיְּימִין. כַּךְ אִלְמָלֵא הָרְשָׁעִים, אֵין הַצַּדִּיקִים נִיכָּרִים. דְּאָמַר רִבִּי יְהוּדָה, בְּמָּה הַצַּדִּיקִים נִיכָּרִים, מִתּוֹךְ שֶׁיֵּשׁ רְשָׁעִים, דְּאִלְמָלֵא רְשָׁעִים אֵין הַצַּדִּיקִים נִיכָּרִים. דָּבָר אַחֵר הָרוֹעֶה בַּשּׁוֹשַׁנִּים, הַמַּנְהִיג עוֹלָמוֹ בְּשֵׁשׁ שָׁנִים, וְהַשְּׁבִיעִית שַׁבָּת לַה'. דָּבָר אַחֵר בַּשּׁוֹשַׁנִּים, בְּאוֹתָם שֶׁשּׁוֹנִים בַּתּוֹרָה.</p>"],[9520011559,"<p>וּמֹשֶׁה הָיָה רוֹעֶה אֶת צֹאן יִתְרוֹ חוֹתְנוֹ כֹּהֵן מִדְיָן. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים כ״ג:א׳) מִזְמוֹר לְדָוִד יְיָ' רוֹעִי לא אֶחְסָר. כְּלוֹמַר, יְיָ' רוֹעִי: יְיָ' הָרוֹעֶה שֶׁלִּי. מַה הָרוֹעֶה מַנְהִיג אֶת הַצֹּאן, וּמוֹלִיכָם לְמִרְעֶה טוֹב, לְמִרְעֶה שָׁמֶן, בִּמְקוֹם נַחֲלֵי מָיִם, מְיַשֵּׁר הֲלִיכָתָן בְּצֶדֶק וּבְמִשְׁפָּט. אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּתִיב בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנוּחוֹת יְנַהֲלֵנִי נַפְשִׁי יְשׁוֹבֵב.</p>\n<p>אָמַר רִבִּי יוֹסֵי, דֶּרֶךְ הָרוֹעֶה, לִנְהוֹג בְּצֶדֶק אֶת צֹאנוֹ, לְהַרְחִיקָם מִן הַגָּזֵל, לְהַנְהִיגָם בְּמִישׁוֹר, וְהַשֵּׁבֶט בְּיָדוֹ שֶּׁלּא יַטּוּ יָמִין וּשְׂמֹאל. כַּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא רוֹעֶה אֶת יִשְׂרָאֵל לְהַנְהִיגָם בְּמִישׁוֹר, וּבְכָל עֵת הַשֵּׁבֶט בְּיָדוֹ שֶׁלּא יַטּוּ יָמִין וּשְׂמֹאל.</p>\n<p>דָּבָר אַחֵר וּמֹשֶׁה הָיָה רוֹעֶה, אָמַר רִבִּי יוֹסֵי, תֵּדַע לְךָ, שֶׁכָּל זְמָן שֶׁהָרוֹעֶה חָכָם לְנַהֵל אֶת צֹאנוֹ, הוּא מוּכָן לְקַבֵּל עוֹל מַלְכוּת שָׁמַיִם. אִם הָרוֹעֶה שׁוֹטֶה, עָלָיו נִקְרָא (משלי כ״ו:י״ב) תִּקוָה לִכְסִיל מִמֶּנּוּ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, מֹשֶׁה חָכָם הָיָה, וּבָקִי לִנְהוֹג אֶת צֹאנוֹ. בֹּא וּרְאֵה, מִדָּוִד, שֶׁנֶּאֱמַר (שמואל א ט״ז:י״א) וְהִנֵּה רוֹעֶה בַּצֹּאן. לְלַמֶּדְךָ שֶׁדָּוִד <Nonei></i>חָכָם גָּדוֹל הָיָה, וְהָיָה רוֹעֶה צֹאנוֹ כַּדִּין וְכַשּׁוּרָה. לְפִיכָךְ, עֲשָׂהוּ הַקָדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ עַל כָּל יִשְׂרָאֵל. וְלָמָּה צֹאן וְלֹא בָּקָר. אָמַר רִבִּי יְהוּדָה, יִשְׂרָאֵל נִקְרָאִים צֹאן. שֶׁנֶּאֱמַר, (יחזקאל ל״ד:ל״א) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וּכְתִיב, (יחזקאל ל״ו:ל״ח) כְּצֹאן קֳדָשִׁים כְּצֹאן יְרוּשָׁלַיִם.</p>\n<p>מַה הַצֹּאן, כְּשֶׁיִּקָּרְבוּ עַל הַמִּזְבֵּחַ, בִּשְׁבִילָם זוֹכֶה לְחַיֵּי הָעוֹלָם הַבָּא. כַּךְ הַמַּנְהִיג לְיִשְׂרָאֵל כַּדִּין וְכַשּׁוּרָה, בִּשְׁבִילָם זוֹכֶה לְחַיֵּי הָעוֹלָם הַבָּא. וְעוֹד, הָרוֹעֶה אֶת הַצֹּאן, כְּשֶׁהַצֹּאן יוֹלְדֹת, הָרוֹעֶה נוֹטֵל אוֹתָם טְלָאִים בְּחֵיקוֹ, כְּדֵי שֶׁלּא יִלְּאוּ וְיִגָּעוּ, וּמוֹלִיכָם אַחֲרֵי אִמּוֹתָם, וּמְרַחֵם עֲלֵיהֶם. כַּךְ הַמַּנְהִיג לְיִשְׂרָאֵל, צָרִיךְ לְהַנְהִילָם בְּרַחֲמִים, וְלֹא בְּאַכְזָרִיּוֹת. וְכֵן אָמַר מֹשֶׁה, (במדבר י״א:י״ב) כִּי תֹאמַר אֵלַי, שָׂאֵהוּ בְחֵיקֶךָ וְגוֹ'.</p>\n<p>מַה הָרוֹעֶה אֶת הַצֹּאן, כְּשֶׁהוּא רוֹעֶה טוֹב, מַצִּיל אֶת הַצֹּאן מִן הַזְּאֵבִים, וּמִן הָאֲרָיוֹת. כַּךְ הַמַּנְהִיג לְיִשְׂרָאֵל, אִם הוּא טוֹב, מַצִּילָן מִן הַעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּמִדִּין שֶׁל מַטָּה, וּמִדִּין שֶׁל מַעְלָה, וּמַדְרִיכָן לְחַיֵּי הָעוֹלָם הַבָּא. כַּךְ מֹשֶׁה, רוֹעֶה נֶאֱמָן הָיָה, וְרָאָה הַקָדוֹשׁ בָּרוּךְ הוּא, שֶׁכְּדַאי הוּא לִרְעוֹת אֶת יִשְׂרָאֵל, בְּאוֹתוֹ הַדִּין מַמָּשׁ, שֶׁהָיָה רוֹעֶה אֶת הַצֹּאן, לַכְּשָׂבִים, כְּפִי הָרָאוּי לָהֶן. וְהַנְּקֵבוֹת כְּפִי הָרָאוּי לָהֶן</p>\n<p>וּלְפִיכָךָ כְּתִיב, וּמֹשֶׁה הָיָה רוֹעֶה אֶת צֹאן יִתְרוֹ חוֹתְנוֹ, וְלא שֶׁלּוֹ, דְּאָמַר רִבִּי יוֹסֵי, וְכִי מַה שֶׁנָּתַן אֶת צִפוֹרָה בִּתּוֹ לְמֹשֶׁה, לֹא נָתַן לוֹ צֹאן וּבָקָר, וַהֲלֹא יִתְרוֹ עָשִׁיר הָיָה. אֶלָּא מֹשֶׁה לֹא הָיָה רוֹעֶה אֶת צֹאנוֹ, כְּדֵי שֶׁלֹּא יֹאמְרוּ בִּשְׁבִיל שֶׁהָיָה צֹאנוֹ עִמּוֹ, הָיָה רוֹעֶה אוֹתָן בְּטוֹב. וְלָכֵן כְּתִיב אֶת צֹאן יִתְרוֹ חוֹתְנוֹ, וְלא אֶת שֶׁלּוֹ. כֹּהֵן מִדְיָן, רִבִּי תַּנְחוּם אָמַר, אַף עַל גַּב שֶׁהָיָה עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת, בִּשְׁבִיל שֶׁעָשָׂה עִמּוֹ חֶסֶד, הָיָה רוֹעֶה צֹאנוֹ כַּדִּין וְכַשּׁוּרָה, בְּמִרְעֶה טוֹב שָׁמֵן וְדָשֵׁן.</p>\n<p>(שמות ג׳:א׳) וַיּנְהַג אֶת הַצֹּאן אַחַר הַמִּדְבָּר. רִבִּי יוֹסֵי אָמַר, מֹשֶׁה, מִיּוֹם שֶׁנּוֹלַד, לא זָזָה מִמֶּנּוּ רוּחַ הַקּוֹדֶשׁ. רָאָה בְּרוּחַ הַקּוֹדֶשׁ, שֶׁאוֹתוֹ מִדְבָּר הָיָה קָדוֹשׁ, וּמוּכָן לְקַבֵּל עוֹל מַלְכוּת שָׁמַיִם עָלָיו. מַה עָשָׂה, הִנְהִיג אֶת הַצֹּאן אַחַר הַמִּדְבָּר. רִבִּי יִצְחָק אָמַר, אַחַר הַמִּדְבָּר עַל כָּל פָּנִים, וְלֹא בַּמִּדְבָּר, שֶׁלֹּא רָצָה שֶׁיִּכָּנְסוּ בְּתוֹכוֹ, אֶלָּא הִרְחִיקָם אַחַר הַמִּדְבָּר.</p>\n<p>(שמות ג׳:א׳) וַיָּבֹא אֶל הַר הָאֱלֹהִים חֹרֵבָה, הוּא לְבַדּוֹ בְּלא צֹאן. אר\"י, הַאי אַבְנָא, דִּמְקַבְּלָא פַּרְזְלָא, כַּד חָמֵי לֵיהּ, (מחטא) מְדַלְגָא עִילוֵי. כַּךְ מֹשֶׁה וְהַר סִינַי, כְּשְׁנִרְאוּ זֶה עִם זֶה, דִּלֵּג עָלָיו. הֲדָא הוּא דִכְתִיב, וַיָּבֹא אֶל הַר הָאֱלהִים חֹרֵבָה.</p>\n<p>אָמַר רִבִּי אַבָּא, מוּכָנִים הָיוּ מִשֵׁשֶׁת יְמֵי בְּרֵאשִׁית, זֶה עִם זֶה. וְאוֹתוֹ הַיּוֹם, נִתְרַגֵּשׁ הָהָר לְמוּל מֹשֶׁה. וְכֵיוָן שֶׁרָאָהוּ שֶׁנִּכְנָס לְתוֹכוֹ, וְדִלֵּג בּוֹ, עָמָד הָהָר. מְלַמֵּד, שֶׁשְׂמֵחִים הָיוּ זֶה עִם זֶה.</p>\n<p>אָמַר רִבִּי יַנָּאי, (נ\"א רבי יוסי) יוֹדֵעַ הָיָה מֹשֶׁה, שֶׁאוֹתוֹ הַר, הַר הָאֱלֹהִים הוּא. דִּכְתִּיב וַיָּבֹא אֶל הַר הָאֱלֹהִים. דְּתְנָן, מָה רָאָה מֹשֶׁה בְּאוֹתוֹ הַר, רָאָה עוֹפוֹת שֶׁהָיוּ פּוֹרְחִים, וּפוֹרְשִׂים כַּנְפֵיהֶם וְלא הָיוּ נִכְנָסִים בּוֹ.</p>\n<p>רִבִּי יִצְחָק (נ\"א אמר ר' יצחק) אוֹמֵר, רָאָה הָעוֹפוֹת פּוֹרְחִים וְטָסִים מִשָּׁם, וְנוֹפְלִים לְרַגְלָיו שֶׁל מֹשֶׁה, מִיַּד הִרְגִּישׁ בָּעִנְיָן, וְהֶעֱמִיד אֶת הַצֹּאן אַחַר הַמִּדְבָּר, וְהוּא נִכְנַס לְבַדּוֹ.</p>\n<p>(שמות ג׳:ב׳) וַיֵּרָא (קנ\"ט ע\"ב, קס\"ז ע\"א) מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. רִבִּי תַּנְחוּם אוֹמֵר, שְׁעֵת הַמִּנְחָה הָיְתָה, שֶׁמִּדַּת הַדִּין שׁוֹלֶטֶת בּוֹ. רִבִּי יוֹחָנָן אָמַר, וְהָא כְּתִּיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ. מִדַּת חֶסֶד קָאָמַר, וְלֹא מִדַּת הַדִּין. אָמַר רִבִּי יִצְחָק, מִשֶּׁיּוֹצֵא הָאוֹר, עַד שֶׁנּוֹטֶה לָרֶדֶת, נִקְרָא יוֹם, וְהוּא מִדַּת חֶסֶד. מִשֶּׁנּוֹטֶה לָרֶדֶת, נִקְרָא עֶרֶב, וְהוּא מִדַּת הַדִּין. וְהַיְינוּ דִּכְתִּיב, (בראשית א׳:ה׳) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם.</p>\n<p>אָמַר רִבִּי יוֹחָנָן, שְׁעַת הַמִּנְחָה הוּא, מו' שָׁעוֹת וּלְמַטָה. דְּתַנְיָא ר' יִצְחָק אוֹמֵר, מַהוּ דִּכְתִּיב, (שמות ט״ז:י״ב) בֵּין הָעַרְבַּיִם תֹאכְלוּ בָּשָׂר וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם. בֵּין הָעַרְבַּיִם, דְּהוּא שַׁעֲתָא <Nonei></i>דְּדִינָא תֹאכְלוּ בָּשָׂר. וּכְתִיב, (במדבר י״א:ל״ג) הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם וְאַף יְיָ' חָרָה בָעָם. מִשּׁוּם, דְּבֵין הָעַרְבַּיִם, דִּינָא דְּמַלְכוּתָא שָׁלִיט. וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם, מִשּׁוּם דְּאִקְרֵי חֶסֶד הַהוּא שַׁעֲתָא, וּכְתִיב, (תהילים נ״ב:ג׳) חֶסֶד אֵל כָּל הַיּוֹם. וּכְתִיב, (בראשית א׳:ה׳) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. דְּאִיהוּ מִצַּפְרָא.</p>\n<p>רִבִּי תַּנְחוּם אוֹמֵר, דָּא סוּמָק, וְדָא חִוָּור. סוּמָק: בֵּין הָעַרְבַּיִם. דִּכְתִּיב, (שמות ט״ז:י״ב) בֵּין הָעַרְבַּיִם תֹאכְלוּ בָּשָׂר. וְחִוְורָא: בְּצַפְרָא. דִּכְתִּיב, וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם. רִבִּי יִצְחָק אָמַר, כְּתִיב, (שמות י״ב:ו׳) וְשָׁחֲטוּ אוֹתוֹ כָּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבַּיִם וְגוֹ'. דְּהוּא שַׁעֲתָא לְמֶעְבַּד דִּינָא. רִבִּי יְהוּדָה אָמַר, יַלְפִינָן מִשְּׁנֵי כְּבָשִׂים שֶׁבְּכָל יוֹם, הָאֶחָד מִתְקָרֵב כְּנֶגֶד מִדַּת הַחֶסֶד, וְהב' כְּנֶגֶד מִדַּת הַדִּין.</p>\n<p>וְאָמַר רִבִּי יְהוּדָה, מַהוּ דִּכְתִּיב, (במדבר כ״ח:ד׳) אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר, וְלָא כְּתִיב אֶת הַכֶּבֶשׂ הָרִאשׁוֹן, אֶלָּא אֶת הַכֶּבֶשׂ הָאֶחָד, מְיוּחָד, כְּנֶגֶד מִדַּת הַחֶסֶד. דִּבְכָל מָקוֹם, שֵׁנִי, לא נֶאֱמַר בּוֹ כִּי טוֹב.</p>\n<p>רִבִּי תַּנְחוּם אָמַר, לְפִיכָךְ, יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה, שֶׁהוּא כְּנֶגֶד מִדַּת הַדִּין. אָמַר רִבִּי יִצְחָק, מִכָּאן, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָּנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. כִּי פָּנָה הַיּוֹם: זֶה מִדַּת הַחֶסֶד. כִּי יִנָּטוּ צִלְלֵי עָרֶב: שֶׁכְּבָר גָּבַר מִדַּת הַדִּין. אַבְרָהָם תִּקֵּן תְּפִלַּת שַׁחֲרִית, כְּנֶגֶד מִדַּת הַחֶסֶד.</p>\n<p>תָּנוּ רַבָּנָן, בְּהַהִיא שַׁעֲתָא דְּעָאל מֹשֶׁה לְטוּרָא דְּסִינַי, מַאי טַעְמָא אִתְגְּלֵי לֵיהּ בְּשַׁלְהוֹבֵי אֶשָּׁתָא, דְּהוּא דִּינָא. אָמַר רִבִּי יַעֲקֹב (נ\"א כעין) כְּעָן שַׁעֲתָא הֲוָה (שעתא) גָּרִים. ר' יוֹסֵי אָמַר, כֹּלָּא לְחָד גִּזְעָא אִשְׁתָּרְשָׁא. כְּתִיב, וַיָּבֹא אֶל הַר הָאֱלהִים חֹרֵבָה. וּכְתִיב, (דברים ט׳:ח׳) וּבְחֹרֵב הִקְצַפְתֶּם אֶת יְיָ'. וּכְתִיב, וַיַּרְא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. מִתּוֹךְ שֶׁהֵם עֲתִידִים לִהְיוֹת כַּסְּנֶה, כְּהַאי דִּכְתִּיב, (ישעיהו ל״ג:י״ב) קוֹצִים כְּסוּחִים בָּאֵשׁ יִצַּתּוּ.</p>"],[9520011560,"<p>אָמַר ר' יְהוּדָה, מִכָּאן לָמַדְנוּ, רַחֲמָנוּתוֹ שֶׁל מָקוֹם עַל הָרְשָׁעִים, דִּכְתִּיב, וְהִנֵּה הַסְּנֶה בּוֹעֵר בָּאֵשׁ, לַעֲשׂוֹת בָּהֶם דִּין בָּרְשָׁעִים, וְהַסְּנֶה אֵינֶנּוּ אוּכָּל, (לעשות) אֵין בָּהֶם כְּלָיָה. בּוֹעֵר בָּאֵשׁ, עַל כָּל פָּנִים רֶמֶז, לָאֵשׁ שֶׁל גֵּיהִנָּם. אֲבָל הַסְּנֶה אֵינְנּוּ אוּכָּל, לִהְיוֹת בָּהֶם כְּלָיָה.</p>\n<p>דָּבָר אַחֵר וַיֵּרָא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ. מַאי טַעְמָא לְמֹשֶׁה בְּלַבַּת אֵשׁ, וְלִשְׁאַר נְבִיאִים לָא. אָמַר רִבִּי יְהוּדָה, לָאו מֹשֶׁה כִּשְׁאַר נְבִיאִים. דִּתְנָן, מַאן דְּקָרִיב לְאֶשָּׁא בֵּיהּ אִתּוֹקַד, וּמֹשֶׁה קָרִיב לְאֶשָּׁא וְלָא אִתּוֹקַד. דִּכְתִּיב, (שמות כ׳:י״ח) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלהִים. וּכְתִיב, וַיַּרְא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה.</p>\n<p>רִבִּי אַבָּא אָמַר, הַאי דְּמֹשֶׁה, אִית לְאִסְתַּכְּלָא בֵּיהּ בְּחָכְמְתָא עִלָּאָה, עַל מַה כְּתִיב, כִּי מִן הַמַּיִם מְשִׁיתִיהוּ. מַאן דְּאִתְמְשָׁךְ מִן מַיָּא, (דינא עילאה) לָא דָּחִיל מִנּוּרָא. דְּתַנְיָא אָמַר רִבִּי יְהוּדָה, מֵאֲתָר דְּאִתְגְּזַר מֹשֶׁה, לָא אִתְגְּזַר בַּר נָשׁ אָחֲרָא. אָמַר רִבִּי יוֹחָנָן, בַּעֲשָׂרָה דַּרְגִּין (ויקרא רפ\"ב) אִשְׁתָּכְלָל. דִּכְתִּיב, (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נְאֱמָן הוּא. וְלֹא נְאֱמָן בֵּיתִי. זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ, דְּמָרֵיהּ אַסְהִיד כְּדֵין עֲלוֹי.</p>\n<p>אָמַר רַב דִּימִי, וְהָא כְּתִיב (דברים ל״ד:י׳) וְלא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. וְאָמַר רִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, בְּיִשְׂרָאֵל לֹא קָם, אֲבָל בְּאוּמוֹת הָעוֹלָם קָם, וּמַנוֹ בִּלְעָם. אֲמַר לֵיהּ, וַדַּאי שַׁפִּיר קָאַמָרְת, אִשְׁתִּיק. כַּד אָתָא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, אָתוּ, שָׁאִילּוּ קָמֵיהּ הַאי מִלָּה.</p>\n<p>פָּתַח וְאָמַר, קוּטִיפָא דְּקַרְנָטֵי, אִתְעָרְבָא בַּאֲפַרְסְמוֹנָא טָבָא חַס וְשָׁלוֹם. אֶלָּא, וַדַּאי כַּךְ הוּא, בְּאוּמוֹת הָעוֹלָם קָם, וּמַנוֹ בִּלְעָם. מֹשֶׁה עוֹבָדוֹי לְעֵילָּא, וּבִלְעָם לְתַתָּא. מֹשֶׁה, אִשְׁתַּמַּשׁ בְּכִתְרָא קַדִּישָׁא דְּמַלְכָּא עִלָּאָה לְעֵילָּא. וּבִלְעָם, אִשְׁתַּמַּשׁ בְּכִתְרִין תַּתָּאִין דְּלָא קַדִּישִׁין לְתַתָּא. וּבְהַהוּא גַּוְונָא מַמָּשׁ כְּתִיב, (יהושע י״ג:כ״ב) וְאֶת בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם הָרְגוּ בְּנֵי יִשְׂרָאֵל בַּחֶרֶב. וְאִי סַלְּקָא דַּעְתָּךְ יַתִּיר, זִיל שָׁאִיל לְאַתְנֵיהּ. אָתָא רִבִּי יוֹסֵי, וְנָשַׁק יְדוֹי, אָמַר, הָא חֲמִידָא (נ\"א חמרא) דְּלִבָּאי נָפַק לְבַר.</p>\n<p>דְּהָכָא מַשְׁמַע, דְּאִית עִלָּאִין וְתַתָּאִין, יְמִינָא וּשְׂמָאלָא, רַחֲמֵי וְדִינָא, יִשְׂרָאֵל ועֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. יִשְׂרָאֵל, מִשְׁתַּמְּשִׁין בְּכִתְרִין עִלָּאִין קַדִּישִׁין. עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, בְּכִתְרִין תַּתָּאִין דְּלָא קַדִּישִׁין. אִלֵּין דִּימִינָא, וְאִלֵּין דִּשְׂמָאלָא, וְעַל כָּל פָּנִים, מִתְפָּרְשִׁין נְבִיאֵי עִלָּאֵי מִנְּבִיאֵי תַּתָּאֵי. נְבִיאֵי דְּקוּדְשָׁא, מִנְּבִיאֵי דְּלָאו דְּקוּדְשָׁא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כְּגַוונָא דְּהֲוָה <Nonei></i>מֹשֶׁה, פָּרִישׁ מִכָּל נְבִיאֵי, בִּנְּבוּאָה קַדִּישָׁא עִלָּאָה. כַּךְ הֲוָה בִּלְעָם, פָּרִישׁ מִשְּׁאָר נְבִיאֵי וָחֳרָשֵׁי, בִּנְּבוּאָה דְּלָאו קַדִּישָׁא לְתַתָּא. וְעַל כָּל פָּנִים מֹשֶׁה הֲוָה לְעֵילָּא, וּבִלְעָם לְתַתָּא, וְכַמָּה דַּרְגִּין וְדַרְגִּין מִתְפָּרְשִׁין בֵּינַיְיהוּ.</p>\n<p>אָמַר רִבִּי יוֹחָנָן אָמַר רִבִּי יִצְחָק, מֹשֶׁה הֲוָה מְהַרְהֵר וְאוֹמֵר, שֶׁמָּא חַס וְשָׁלוֹם יִשְׂרָאֵל יִכְלוּ בְּהַאי עֲבוֹדָה קָשָׁה, הֲדָא הוּא דִּכְתִּיב, וַיַּרְא בְּסִבְלוֹתָם. לְפִיכָךְ, וַיֵּרָא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ וְגוֹ', וַיַּרְא וְהִנֵּה הַסְּנֶה בּוֹעֵר בָּאֵשׁ וְגוֹ'. כְּלוֹמַר, מְשׁוּעֲבָּדִים הֵם בַּעֲבוֹדָה קָשָׁה, אֲבָל וְהַסְּנֶה אֵינֶנּוּ אוּכָּל. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא פָּרִישׁ לוֹן מִכָּל עַמִּין, וְקָרָא לוֹן בְּנִין, דִּכְתִיב (דברים י״ד:א׳) בָּנִים אַתֶּם לַה' אֱלהֵיכֶם.</p>"],[9520011561,"<p>(שמות ו׳:ב׳-ג׳) וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה וַיֹּאמֶר אֵלָיו אֲנִי יְיָ' ואֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וְגוֹ'. רִבִּי אַבָּא פָּתַח, (ישעיהו כ״ו:ד׳) בִּטְחוּ בַיְיָ' עֲדֵי עַד כִּי בְּיָהּ יְיָ' צוּר עוֹלָמִים. בִּטְחוּ בַיְיָ', כָּל בְּנֵי עָלְמָא בַּעְיָין לְאִתַּתְקְפָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְמֶהֱוֵי רָחְצַנוּ דִּלְהוֹן בֵּיהּ.</p>\n<p>אִי הָכִי מַהוּ עֲדֵי עַד. אֶלָּא, בְּגִין דִּיהֵא תֻּקְפָּא דְּבַר נָשׁ, בַּאֲתַר דְּאִיהוּ קִיּוּמָא וְקִשּׁוּרָא דְּכֹלָּא, וְאִקְרֵי עַד, וְהָא אוּקְמוּהָ, כְּמָה דְּאַתְּ אָמֵר, (בראשית מ״ט:כ״ז) בַּבֹּקֶר יֹאכַל עַד. וְהַאי עַד, אֲתָר דְּאָחִיד לְכָל סִטְרִין, לְסִטְרָא דָּא, וּלְסִטְרָא דָּא, לְאִתְקַיְּימָא, וּלְאִתְקַשְּׁרָא קִשְׁרָא, דִּי לָא תַּעְדֵי.</p>\n<p>וְהַאי עַד, תִּיאוּבְתָּא דְּכֹלָּא בֵּיהּ, כְּמָה דְּאַתְּ אָמֵר, (בראשית מ\"ט, בראשית נ' ע\"א רמ\"ז ע\"ב) עַד תַּאֲוַת גִּבְעוֹת עוֹלָם. מַאן אִינּוּן גִּבְעוֹת עוֹלָם. אִלֵּין אִינּוּן תְּרֵין אִמָּהָן נוּקְבֵי, יוֹבֵל, וּשְׁמִטָּה, דְּאִקְרוּן גִּבְעוֹת עוֹלָם. עוֹלָם: כְּמָה דְּאַתְּ אָמֵר, (תהילים ק״ו:מ״ח) מִן הָעוֹלָם וְעַד הָעוֹלָם. (יובל ושמיטה כל חד מנהון אקרי עולם ואלין אקרון גבעות עולם)</p>\n<p>וְתִיאוּבְתָּא דִּילְהוֹן בְּהַאי עַד, דְּאִיהוּ קִיּוּמָא דְּכָל סִטְרִין. (מאי טעמא) תִּיאוּבְתָּא דְּיוֹבְלָא לְגַבֵּי דְּעַד, לְאַעְטְּרָא לֵיהּ, וּלְנַגְדָּא עָלֵיהּ בִּרְכָּאן, וּלְאַרְקָא עָלֵיהּ מַבּוּעִין מְתִיקִין, הֲדָא הוּא דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ. תִּיאוּבְתָּא דִּשְׁמִטָּה, לְאִתְבָּרְכָא מִנֵּיהּ, וּלְאַתְנַהֲרָא מִנֵּיהּ. וַדַּאי הַאי עַד תַּאֲוַת גִּבְעוֹת עוֹלָם אִיהוּ.</p>\n<p>בְּגִין כַּךְ, בִּטְחוּ בַיְיָ' עֲדֵי עַד, דְּהָא מִתַּמָּן וּלְעֵילָּא, אֲתָר טָמִיר (הוא) וְגָנִיז אִיהוּ, דְּלָא יָכִיל לְאִתְדַּבְּקָא. אֲתָר הוּא, דְּמִנֵּיהּ נָפְקוּ וְאִצְטָיְּירוּ עָלְמִין, הֲדָא הוּא דִּכְתִּיב, כִּי בְּיָהּ יְיָ' צוּר עוֹלָמִים וְהוּא אֲתָר גָּנִיז וְסָתִים, וְעַל דָּא בִּטְחוּ בַיְיָ' עֲדֵי עַד, עַד הָכָא אִית רְשׁוּ לְכָל בַּר נָשׁ לְאִסְתַּכְּלָא בֵּיהּ, מִכָּאן וּלְהָלְאָה, לֵית לֵיהּ רְשׁוּ לְבַּר נָשׁ לְאִסְתַּכְּלָא בֵּיהּ, דְּהָא אִיהוּ גָּנִיז מִכֹּלָּא, וּמַאן אִיהוּ יָהּ יְדוָֹד. דִּמִתַּמָּן אִצְטְיָּירוּ עָלְמִין כֻּלְּהוּ, וְלֵית מַאן דְּקָאִים עַל הַהוּא אֲתָר.</p>\n<p>אָמַר רִבִּי יְהוּדָה, קְרָא אוֹכַח עָלֵיהּ, דִּכְתִּיב, (דברים ד׳:ל״ב) כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגוֹ'. עַד הָכָא אִית רְשׁוּ לְבַּר נָשׁ לְאִסְתַּכְּלָא, מִכָּאן וּלְהָלְאָה לֵית מַאן דְּיָכִיל לְמֵיקָם עָלֵיהּ.</p>\n<p>דָּבָר אַחֵר בִּטְחוּ בַיְיָ' עֲדֵי עַד, כָּל יוֹמוֹי דְּבַר נָשׁ, בָּעֵי לְאִתַּתְקְפָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, (דהכי אמר דוד (תהילים כ״ה:ב׳) אלהי בך בטחתי אל אבושה אל יעלצו אויבי לי) וּמַאן דְּשַׁוֵּי בֵּיהּ, בִּטְחוֹנֵיהּ וְתוּקְפֵּיהּ כְּדְקָא יֵאוֹת, לָא יַכְלִין לְאַבְאָשָׁא לֵיהּ, כָּל בְּנֵי עָלְמָא. (דהכי אמר דוד (תהילים כ״ה:ב׳) אלהי בך בטחתי אל אבושה אל יעלצו אויבי לי) דְּכָל מַאן דְּשַׁוֵּי תּוּקְפֵּיהּ בִּשְׁמָא קַדִּישָׁא, אִתְקַיַּים בְּעָלְמָא.</p>\n<p>מַאי טַעֲמָא, בְּגִין דְּעָלְמָא, בִּשְׁמֵיהּ קַדִּישָׁא אִתְקַיַּים. הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:ד׳) כִּי בְּיָהּ יְיָ' <Nonei></i>צוּר עוֹלָמִים: צַיָּיר עָלְמִין. דְּהָא בִּתְרֵין אַתְוָון, אִתְבְּרוּן עָלְמִין, עָלְמָא דֵּין, וְעָלְמָא דְּאָתֵי. עָלְמָא דָּא, בְּדִינָא אִתְבְּרִי, וְעַל דִּינָא קַיְּימָא, הֲדָא הוּא דִכְתִיב, (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלהִים. מַאי טַעְמָא, בְּגִין דְּיִתְנַהֲגוּן בְּנִי נָשָׁא בְּדִינָא, וְלָא יִפְקוּן מֵאוֹרְחָא לְבַר.</p>\n<p>תָּא חֲזֵי כְּתִיב וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה, גִּזְירַת דִּינָא דְּקַיְּימָא עָלֵיהּ, מַה כְּתִיב לְעֵילָּא, (שמות ה׳:כ״ב) וַיָּשָׁב מֹשֶׁה אֶל ה', וַיֹּאמַר אֲדֹנָ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. חָמֵי תּוּקְפָּא דְּמֹשֶׁה, בְּשֵׁירוּתָא דִּנְבִיאוּתֵיהּ, לָא נָח רוּחֵיהּ בְּהַאי אֲתָר, אָמַר, אֲדֹנָי לָמָה הֲרֵעֹתָה לָעָם הַזֶּה וְגוֹ', וּמֵאָז בָּאתִי אֶל פַּרְעֹה לְדַבֵּר בִּשְׁמֶךָ הֵרַע לָעָם הַזֶּה וְהַצֵּל לא הִצַּלְתָּ אֶת עַמֶּךָ. מַאן הוּא דְּיֵימָא כְּדֵין, אֶלָּא מֹשֶׁה, דְּיָדַע, דְּהָא דַּרְגָּא אָחֳרָא עִלָּאָה זַמִּין לֵיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, בְּשֵׁירוּתָא דְּאִתְיְהִיב לֵיהּ בֵּיתָא, פָּקִיד לָהּ, כְּבַר נָשׁ דְּפָקִיד לְבֵיתֵיהּ, וְאָמַר כָּל מַאן דְּבָעֵי בְּלָא דְּחִילוּ. אוּף הָכִי מֹשֶׁה, לְבֵיתֵיהּ קָאָמַר, וְלָא דָּחִיל.</p>\n<p>דָּבָר אַחֵר וַיְדַבֵּר אֱלֹהִים, גִּזְרַת דִּינָא, (בגין כך) וַיֹּאמֶר אֵלָיו אֲנִי יְיָ', דַּרְגָּא אָחֳרָא דְּרַחֲמֵי. וְהָכָא אִתְקַשַּׁר כּוֹלָּא כַּחֲדָא, דִּינָא וְרַחֲמֵי. הֲדָא הוּא דִּכְתִּיב, וַיֹּאמֶר אֵלָיו אֲנִי יְיָ'. אָמַר רִבִּי שִׁמְעוֹן (נ\"א רבייוסי) אִי כְּתִיב וַיְדַבֵּר אֱלהִים אֶל מֹשֶׁה אֲנִי ה', הֲוֵינָא אָמַר הָכִי. אֶלָּא לָא כְּתִיב, אֶלָּא וַיְדַבֵּר אֱלהִים אֶל מֹשֶׁה בְּקַדְמִיתָא, וּלְבָתַר וַיֹּאמֶר אֵלָיו אֲנִי ה', דְּמַשְׁמַע דַּרְגָּא בָּתַר דַּרְגָּא.</p>\n<p>וְאָמַר רִבִּי יוֹסֵי, מֹשֶׁה, אִלְמָלֵא דְּהֲוָה מָארֵיהּ דְּבֵיתָא, אִישׁ הָאֱלֹהִים, אִתְעַנָּשׁ עַל מַה דְּאָמַר, אֲבָל בְּגִינִי הַאי, לָא אִתְעַנָּשׁ. לְבַר נָשׁ דְּנָפַל לֵיהּ קְטָטָה בִּדְבִיתְהוּ, וְאָמַר לָהּ מִלִּין, שָׁרַאת הִיא לְאִתְרַעֲמָא, כֵּיוָן דְּשָׁארִית מִלָּה, הֲוָה תַּמָּן מַלְכָּא, נָטַל מַלְכָּא מִלָּה, וְהִיא שַׁתְקַת וּפַסְקַת לְמַלְּלָא. אָמַר לֵיהּ מַלְכָּא, וְכִי לָא יָדַעְתְּ דַּאֲנָא הוּא מַלְכָּא, וּמִקָּמָאי מַלִּילַת מִלִּין אִלֵּין, כִּבְיָכוֹל אוּף הָכִי מֹשֶׁה, וַיָּשָׁב מֹשֶׁה אֶל יְיָ' וַיֹּאמַר אֲדֹנָי לָמָה הֲרֵעוֹתָה וְגוֹ'. מִיָּד, וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה, שָׁארֵי לְאִתְרָעֲמָא, מִיָּד נָטַל מַלְכָּא מִלָּה וַיֹּאמֶר אֵלָיו אֲנִי יְיָ' וְלָא יָדַעְתּ דַּאֲנָא הוּא מַלְכָּא, וּמִקָּמַאי מַלִּילַת מִלִּין אִלֵּין.</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. אֲמַאי שָׁנֵּי שְׁמָא הָכָא מֵאִלֵּין דִּלְעֵילָּא. אֶלָּא לְמַלְכָּא, דְּהֲוָה לֵיהּ בְּרַתָּא, דְּלָא אִתְנְסִיבַת, וַהֲוָה לֵיהּ רְחִימָא. כַּד בָּעֵי מַלְכָּא לְמַלְּלָא בְּהַהוּא רְחִימָא, מְשַׁדֵּר לִבְרַתֵּיהּ לְמַלְּלָא עִמֵּיהּ, וַהֲוָה מַלְכָּא עַל יְדָא דִּבְרַתֵּיהּ, מְמַלֵּיל עִמֵּיהּ. אָתָא זִמְנָא דִּבְרַתֵּיהּ לְאִתְנַסְּבָא, הַהוּא יוֹמָא דְּאִתְנְסִיבַת, אָמַר מַלְכָּא, קָרוּן לָהּ לִבְרַתָּא, קְרוּסְפוּנְיָא מַטְרוֹנִיתָא. וְאֲמַר לָהּ, עַד הָכָא, מַלִּילְנָא עַל יְדָךְ, לְמַאן דְּמַלִּילְנָא מִכָּאן וּלְהָלְאָה אֲנָא אֵימָא לְבַעְלִיךְ, וְהוּא יֵימָא לְמַאן דְּאִצְטְרִיךְ. לְיוֹמִין, אָמַר לָהּ בַּעְלָהּ מִלִּין קָמֵי מַלְכָּא, עַד דְּהִיא שָׁרָאת לְמַלְּלָא, נָטַל מַלְכָּא מִלָּה, אָמַר לֵיהּ, וְלָאו אֲנָא מַלְכָּא, דְּעַד יוֹמָא דָּא לָא מַלִּיל אֵינָשׁ עִמִּי, אֶלָּא עַל יְדָא דִּבְרַתִּי, (עד לא נסיבת) וַאֲנָא יָהִיבְנָא לָךְ בְּרַתִּי, וּמַלִּילְנָא עִמָּךְ בְּאִתְגַּלְיָא, מַה דְּלָא עֲבִידְנָא לְאָחֳרָא.</p>\n<p>כַּךָ, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי, כַּד אִיהִי בְּבֵיתִי וְלָא אִתְנְסִיבַת, וְלָא מַלִּילוּ עִמִּי אַנְפִּין בְּאַנְפִּין, כְּמָה דְּעַבִידְנָא לָךְ. וְאַתְּ, בְּשֵׁירוּתָא דְּמִלּוּלָךְ, מַלִּילַת לִבְרַתִּי קָמָאי מִלִּין אִלֵּין, אֶלָּא בְּגִינִי כַּךְ, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וּשְׁמִי יְיָ' לא נוֹדַעְתִּי לָהֶם, לְמַלְּלָא עִמְּהוֹן בְּדַרְגָּא דָּא דְּעִמָּךְ מַלִּילְנָא.</p>\n<p>רִבִּי יוֹסֵי (נ\"א רבי ייסא) פָּתַח, (תהילים כ״ד:א׳) לְדָוִד (נ' ע\"א) מִזְמוֹר לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיוֹשְׁבֵי בָּהּ. הָאָרֶץ: דָּא אַרְעָא קַדִּישָׁא דְּיִשְׂרָאֵל, דְּאִיהִי קַיְּימָא לְאִתְשַׁקְיָיא מִנֵּיהּ, וּלְאִתְבָּרְכָא מִנֵּיהּ בְּקַדְמִיתָא, וּלְבָתַר מִנָּהּ אִתְשַׁקְיָיא עָלְמָא כֹּלָּא. תֵּבֵל וְיוֹשְׁבֵי בָּהּ: דָּא שְׁאַר אַרְעָאן, דְּשַׁתְאָן מִינָהּ, מְנָא לָן. דִּכְתִּיב, (תהילים ט׳:ט׳) וְהוּא יִשְׁפּוֹט תֵּבֵל בְּצֶדֶק.</p>\n<p>כִּי הוּא עַל יַמִּים יְסָדָהּ, אִלֵּין <Nonei></i>שִׁבְעָה עַמּוּדִים, דְּאַרְעָא סְמִיכָא עָלַיְיהוּ. וְאִינּוּן שִׁבְעָה יַמִּים. וְיַם כִנֶּרֶת שַׁלְטָא עָלַיְיהוּ. אָמַר רִבִּי יְהוּדָה, לָא תֵּימָא דְּשַׁלְטָא עָלַיְיהוּ, אֶלָּא דְּאִתְמַלְיָיא מִנַּיְיהוּ. וְעַל נְהָרוֹת יְכוֹנְנֶהָ, מַאן אִינּוּן נְהָרוֹת. אֶלָּא, כְּמָה דְאַתְּ אָמֵר, (תהילים צ״ג:ג׳) נָשְׂאוּ נְהָרוֹת קוֹלָם יִשְּׂאוּ נְהָרוֹת דָּכְיָם, אִינּוּן נְהָרוֹת, כְּמָה דְאַתְּ אָמֵר, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וּבְגִין כַּךְ, וְעַל נְהָרוֹת יְכוֹנְנְהָ.</p>\n<p>תָּא חֲזֵי, הַאי אֶרֶץ, אִקְרֵי אֶרֶץ יִשְׂרָאֵל. יַעֲקֹב דְּאִיהוּ יִשְׂרָאֵל, אֲמַאי לָא שָׁלִיט עַל דָּא כְּמֹּשֶׁה, דְּהָא כְּתִיב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וְלָא יַתִּיר.</p>\n<p>אֶלָּא, יַעֲקֹב הָא אוֹקִימְנָא, נָטַל בֵּיתָא דִּלְתַתָּא, וְאִשְׁתְּבִיק מִנֵּיהּ בֵּיתָא דִּלְעֵילָּא. וְעִם בֵּיתָא דִּלְתַתָּא, אַתְקִין בֵּיתָא דִּלְעֵילָּא, בִּתְרֵיסָר שְׁבָטִין, בְּשִׁבְעִין עֲנָפִין, וְהָא אוּקְמוּהָ. מֹשֶׁה, נָטַל בֵּיתָא דִּלְעֵילָּא, וְשָׁבִיק בֵּיתָא דִּלְתַתָּא. וְעַל דָּא, כְּתִיב בְּיַעֲקֹב בְּאֵל שַׁדָּי. בְּאֵל שַׁדָּי מַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְלָא יַתִּיר. וּשְׁמִי יְיָ' לֹא נוֹדַעְתִּי לָהֶם, לְמַלְּלָא עִמְּהוֹן בְּדַרְגָּא דָּא דְּאִיהוּ עִלָּאָה.</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב. אָמַר רִבִּי חִיָּיא, תּוּשְׁבְּחָן דַּאֲבָהָן יַעֲקֹב הֲוָה, דְּהוּא שְׁלִימוּ דְּכֹלָּא. בְּכֻלְּהוּ כְּתִיב, אֶל אַבְרָהָם, אֶל יִצְחָק, וּבֵיהּ אִתּוֹסָף אָת חַד, דִּכְתִּיב, וְאֶל יַעֲקֹב. אִתּוֹסָף בֵּיהּ ו', לְאַחֲזָאָה דְּאִיהוּ שְׁלֵימָא יַתִּיר מִכֻּלְּהוּ. וְעִם כָּל דָּא, לָא זָכָה לְאִשְׁתַּמְּשָׁא בֵּיהּ כְּמֹּשֶׁה.</p>\n<p>(שמות ו׳:ד׳) וְגַם הֲקִימוֹתִי אֶת בְּרִיתִי אִתָּם לָתֵת לָהֶם אֶת אֶרֶץ כְּנָעַן, בְּגִין דְּאִתְגְּזָרוּ. דְּכָל מַאן דְּאִתְגְּזַר, יָרִית אַרְעָא, דְּהָא לָא יָרִית אַרְעָא, אֶלָּא צַדִּיק, וְכָל מַאן דְּאִתְגְּזַר, אִקְרֵי צַדִּיק. דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, כָּל מַאן דְּאִתְגְּזַר, וְנָטִיר הַאי אָת קַיָּימָא, אִקְרֵי צַדִּיק, תָּא חֲזֵי מִן יוֹסֵף, דְּכָל יוֹמוֹי לָא אִקְרֵי צַדִּיק, עַד דְּנָטִיר הַהוּא בְּרִית, אָת קַיָּימָא קַדִּישָׁא. כֵּיוָן דְּנָטַר לֵיהּ, אִקְרֵי צַדִּיק, יוֹסֵף הַצַּדִּיק.</p>"],[9520011562,"<p>רִבִּי שִׁמְעוֹן הֲוָה יָתִיב יוֹמָא, חַד, וְרִבִּי אֶלְעָזָר בְּרֵיהּ, (עמיה) וְרִבִּי אַבָּא עִמֵּיהּ. אָמַר רִבִּי אֶלְעָזָר, הַאי קְרָא דִּכְתִּיב, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב וְגוֹ'. מַהוּ וָאֵרָא, וַאֲדַבֵּר מִבָּעֵי לֵיהּ. אָמַר לֵיהּ, אֶלְעָזָר בְּרִי, רָזָא עִלָּאָה אִיהוּ.</p>\n<p>תָּא חֲזֵי, אִית גַּוְונִין דְּמִתְחַזְיָין, וְאִית גַּוְונִין דְּלָא מִתְחַזְיָין. וְאִלֵּין וְאִלֵּין, אִינּוּן רָזָא עִלָּאָה דִּמְהֵימְנוּתָא, וּבְנֵי נָשָׁא לָא יַדְעִין לֵיהּ, וְלָא מִסְתַּכְּלִין בֵּיהּ וְאִלֵּין דְּמִתְחַזְיָין, לָא זָכָה בְּהוּ בַּר נָשׁ, עַד דְּאָתוּ אֲבָהָן, וְקָיְימוּ עָלַיְיהוּ. וְעַל דָּא כְּתִיב וָאֵרָא, דְּחָמוּ, אִינּוּן גַּוְונִין דְּאִתְגַּלְּיָין.</p>\n<p>וּמַאן גַּוְונִין דְּאִתְגַּלְּיָין. אִינּוּן דְּאֵל שַׁדָּי, דְּאִינּוּן גווָֹנִין דְחֵיזוּ עִילָאָה (נ\"א חיזו דגוונין עלאין') וְאִלֵּין אִתְחַזְיָין. וּגְוָונִין דִּלְעֵילָּא, סְתִימִין דְּלָא אִתְחַזְּיָין, לָא קָאִים אִינִישׁ עָלַיְיהוּ, בַּר מְמֹשֶׁה. וְעַל דָּא כְּתִיב, וּשְׁמִי יְיָ' לא נוֹדַעְתִּי לָהֶם, לָא אִתְגַּלֵּיתִי לוֹן בִּגְוָונִין עִלָּאִין. וְאִי תֵּימָא, דַּאֲבָהָן לָא הֲווֹ יַדְעֵי בְּהוּ. אֶלָּא הֲווֹ יַדְעֵי, מִגּוֹ אִינּוּן דְּאִתְגַּלְּיָין.</p>\n<p>כְּתִיב (דניאל י״ב:ג׳) וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. וְהַמַּשְׂכִּילִים יַזְהִירוּ, מַאן אִינּוּן מַשְׂכִּילִים. אֶלָּא דָּא הוּא, הַהוּא חָכָם דְּיִסְתַּכַּל מִגַּרְמֵיהּ מִלִּין, דְּלָא יָכְילִין בְּנֵי נָשָׁא לְמַלְּלָא בְּפוּמָא, וְאִלֵּין אִקְרוּן מַשְׂכִּילִים. יַזְהִירוּ כְּזֹהַר הָרָקִיעַ, מַאן (זהר) הוּא הָרָקִיעַ. דָּא הוּא רְקִיעַ דְּמֹשֶׁה, דְּקַיְּימָא בְּאֶמְצָעִיתָא, וְהַאי זֹהַר דִּילֵיהּ, אִיהוּ סָתִים, וְלָא אִתְגַּלְּיָיא מִגָּוֶן דִּילֵּיהּ קַיְּימָא עַל הַהִיא רְקִיעָא דְּלָא נָהִיר, דְּאִתְחַזְיָין בֵּיהּ גַּוְונִין, וְאִינּוּן גַּוְונִין אַף עַל גַּב דְּאִתְחַזְיָין בֵּיהּ, לָא זַהֲרֵי כְּזִהֲרָא בְּגִין דְּאִינּוּן גַּוְונִין סְתִימִין.</p>\n<p>תָּא חֲזֵי, אַרְבַּע נְהוֹרִין אִינּוּן. תְּלַת מִנַּיְיהוּ סְתִימִין, וְחַד דְּאִתְגַּלְיָיא: נְהוֹרָא דְּנָהִיר. נְהוֹרָא דְּזִהֲרָא. (ואינון) וְאִיהוּ נָהִיר כִּזְהִירוּ דִּשְׁמַיָּא בְּדַכְיוּ. נְהוֹרָא דְּאַרְגְּוָונָא, דְּנָטִיל כָּל נְהוֹרִין. נְהוֹרָא דְּלָא נָהִיר אִסְתַּכַּל לְגַבֵּי אִלֵּין, וְנָטִיל לוֹן. וְאִתְחַזְּיָין אִינּוּן נְהוֹרִין בֵּיהּ, כַּעֲשָׁשִׁיתָא, לָקֳבֵל שִׁמְשָׁא.</p>\n<p>וְאִלֵּין תְּלָת דְּקַאמְרָן, סְתִימִין וְקַיְּימִין עַל הַאי <Nonei></i>דְּאִתְגַּלְיָיא. וְרָזָא דָּא (ויחי רכ\"ו ע\"א) עֵינָא תָּא חֲזֵי, בְּעֵינָא אִית תְּלַת גַּוְונִין, דְּאִתְגַּלְּיָין רְשִׁימִין בֵּיהּ, וְכֻלְּהוּ לָא מִזְדַּהֲרֵי, בְּגִין דְּקַיְימֵי בִּנְהוֹרָא דְּלָא נָהִיר. וְאִלֵּין אִינּוּן כְּגַוְונָא דְּאִינּוּן סְתִימִין דְּקַיְימֵי עָלַיְיהוּ וְאִלֵּין אִינּוּן דְּאִתְחַזְּיָין לַאֲבָהָן, לְמִנְדַּע אִינּוּן סְתִימִין דְּמִזְדַּהֲרִין, מִגּוֹ אִלֵּין דְּלָא מִזְדַּהֲרֵי. וְאִינּוּן דְּמִזְדַּהֲרֵי וְאִינּוּן סְתִימִין, אִתְגַּלְּיָין לְמֹשֶׁה, בְּהַהוּא רְקִיעָא דִּילֵיהּ. וְאִלֵּין קַיְימֵי, עַל אִינּוּן גַּוְונִין דְּאִתְחַזְּיָין בֵּיהּ בְּעֵינָא.</p>\n<p>וְרָזָא דָּא סָתִים עֵינָךְ, וְאַסְחַר גַּלְגַּלָּךְ, וְיִתְגַּלְּיָין אִינּוּן גַּוְונִין דְּנַהֲרִין, דְּמִזְדַּהֲרֵי, וְלָא אִתְיְיהִיב רְשׁוּ לְמֶיחמֵי, אֶלָּא בְּעַיְינִין סְתִימִין, בְּגִין דְּאִינּוּן סְתִימִין עִלָּאִין, קַיְּימֵי עַל אִינּוּן גַּוְונִין דְּאִתְחַזְּיָין, דְּלָא מִזְדַּהֲרֵי.</p>\n<p>וְעַל דָּא קָרֵינָן, מֹשֶׁה זָכָה בְּאַסְפָּקָלַרְיָא דְּנַהֲרָא דְּקַיְּימָא עַל הַהוּא דְּלָא נַהֲרָא. שְׁאַר בְּנֵי עָלְמָא, בְּהַהוּא אַסְפָּקָלַרְיָא דְּלָא נָהֲרָא. וַאֲבָהָן הֲווֹ חָמָאן מִגּוֹ אִלֵּין גַּוְונִין דְּאִתְגַּלְּיָין, אִינּוּן סְתִימִין, דְּקַיְימֵי עָלַיְיהוּ דְּאִינּוּן דְּלָא נָהֲרִין, וְעַל דָּא כְּתִיב, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי, בְּאִינּוּן גַּוְונִין דְּאִתְחַזְּיָין.</p>\n<p>וּשְׁמִי יְיָ' לֹא נוֹדַעְתִּי לָהֶם, אִלֵּין גַּוְונִין עִלָּאִין סְתִימִין דְּזָהֲרִין, דְּזָכָה בְּהוּ מֹשֶׁה לְאִסְתַּכְּלָא בְּהוֹן. וְרָזָא דָּא, דְּעֵינָא סָתִים וְגַלְיָא. סָתִים, חָמֵי אַסְפָּקָלַרְיָא דְּנָהֲרָא, אִתְגַּלְּיָיא, חָמֵי אַסְפָּקָלַרְיָא דְּלָא נַהֲרָא. וְעַל דָּא, וָאֵרָא, בְּאַסְפָּקָלַרְיָא דְּלָא נָהֲרָא, דְּאִיהוּ בְּאִתְגַּלְּיָיא, בֵּיהּ כְּתִיב רְאִיָּה. בְּאַסְפָּקָלַרְיָא דְּנָהֲרָא דְּאִיהוּ בִּסְתִימוּ, כְּתִיב בֵּיהּ יְדִיעָה, דִּכְתִּיב לֹא נוֹדַעְתִּי. אָתוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וְנָשְׁקוּ יְדוֹי. בָּכָה רִבִּי אַבָּא, וְאָמַר, וַוי כַּד תִּסְתַּלַּק מֵעָלְמָא, וְיִשְׁתְּאַר עָלְמָא יָתוֹם מִינָךְ, מַאן יָכִיל לְאַנְהָרָא מִלִּין דְּאוֹרַיְיתָא.</p>\n<p>פָּתַח רִבִּי אַבָּא וְאָמַר, (שמואל א כ״ה:ו׳) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךָ שָׁלוֹם וְכֹל אֲשֶׁר לְךָ שָׁלוֹם. וַאֲמַרְתֶּם כֹּה לֶחָי, וְכִי דָּוִד לָא הֲוָה יָדַע בֵּיהּ בְּנָבָל, דְּאִיהוּ אָמַר בְּגִינֵיהּ, וַאֲמַרְתֶּם כֹּה לֶחָי, אֶלָּא, הַהוּא יוֹמָא, יוֹמָא טָבָא דְרֹאשׁ הַשָּׁנָה הֲוָה, וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עָלְמָא, וּבְגִין קוּדְשָׁא בְּרִיךְ הוּא קָאָמַר, וַאֲמַרְתֶּם כֹּה, לֶחָי, לְקַשְּׁרָא כֹּה, לֶחָי, דְּכָל חַיִּין בֵּיהּ תַּלְיָין. וְאַתָּה שָׁלוֹם, מַאי וְאַתָּה אַתָּה מִבָּעֵי לֵיהּ. אֶלָּא, וְאַתָּה כֹּלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא קָאָמַר, בְּגִין לְקַשְּׁרָא קִשְׁרָא דִּמְהֵימָנוּתָא וְכַדְקָא יֵאוֹת.</p>\n<p>מִכָּאן אוֹלִיפְנָא, דְּהָא לְבַר נָשׁ (בראשית קע\"א ע\"ב) חַיָּיבָא, אָסוּר לְאַקְדְּמָא לֵיהּ שְׁלָם, וְאִי אִצְטְרִיךְ, יַקְדִּים לֵיהּ כְּדָוִד, דְּבָרִיךְ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְחַזֵּי דִּבְגִינֵיהּ קָאָמַר. וְאִי תֵּימָא דְּרַמָּאוּת הֲוָה. לָאו. דְּהָא כָּל מַאן דְּסָלִיק לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְחַזֵּי דִּבְגִינֵיהּ קָאָמַר, לָאו רַמָּאוּת הוּא. וּמַאן דְּאַקְדִּים שְׁלָם לְזַכָּאָה, כְּאִילּוּ אַקְדִּים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כָּל שֶׁכֵּן מַר, דְּאִיהוּ שְׁלָמָא לְעֵילָּא וְתַתָּא.</p>"],[9520011563,"<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וּשְׁמִי יְיָ' לא נוֹדַעְתִּי לָהֶם. רִבִּי חִזְקִיָּה פָּתַח, (תהילים ל״ב:ב׳) אַשְׁרֵי אָדָם לא יַחְשֹׁב ה' לוֹ עֲוֹן וְגוֹ'. כַּמָּה אִינּוּן בְּנֵי נָשָׁא אֲטִימִין, דְּלָא יָדְעִין, וְלָא מִסְתַּכְּלָן, עַל מַה קַיָּימִין בְּעָלְמָא. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, עָבֵד לֵיהּ לְבַר נָשׁ בְּדִיּוּקְנָא דִּילֵיהּ, וְאַתְקִין לֵיהּ בְּתִקּוּנוֹי, בְּגִין דְּיִשְׁתַּדַּל בְּאוֹרַיְיתָא, וְיֵהַךְ בְּאוֹרְחוֹי.</p>\n<p>דְּהָא כַּד אִתְבְּרֵי אָדָם, מֵעַפְרָא דְּמַקְדְּשָׁא דִּלְתַתָּא אִתְתַּקַּן וְאַרְבַּע סִטְרֵי דְּעָלְמָא, אִתְחַבְּרוּ בְּהַהוּא אֲתָר דְּאִקְרֵי בֵּי מַקְדְּשָׁא. וְאִינּוּן אַרְבַּע סִטְרִין דְּעָלְמָא, אִתְחַבְּרוּ בְּאַרְבַּע סִטְרִין, דְּאִינּוּן יְסוֹדִין דְּעָלְמָא, אֵ\"ש רוּ\"חַ וְמַיִ\"ם וְעָפָ\"ר, וְאִתְחַבְּרוּ אַרְבַּע סִטְרִין (נ\"א יסודין) אִלֵּין, בְּד' יְסוֹדִין דְּעָלְמָא, וְאַתְקִין מִנַּיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא חַד גּוּפָא בְּתִקּוּנָא עִלָּאָה. וְהַאי גּוּפָא, אִתְחַבַּר מִתְּרֵין עָלְמִין, מֵעָלְמָא דָּא תַּתָּאָה, וּמֵעָלְמָא דִּלְעֵילָּא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, תָּא חֲזֵי, ד' קַדְמָאֵי אִינּוּן רָזָא דִּמְהֵימָנוּתָא. וְאִינּוּן אֲבָהָן דְּכֻלְּהוּ עָלְמִין. וְרָזָא דִּרְתִיכָא עִלָּאָה קַדִּישָׁא. וְאִינּוּן ד' יְסוֹדִין: אֵ\"ש רוּ\"חַ וְמַיִ\"ם וְעָפָ\"ר. אִלֵּין אִינּוּן רָזָא עִלָּאָה. (ואילין אינון אבהן דכולהו עלמין אבהן דכלא) וּמֵאִינּוּן נָפְקִין, זָהָ\"ב וָכֶסֶ\"ף וּנְחֹשֶׁ\"ת וּבַרְזֶ\"ל. וּתְחוֹת <Nonei></i>אִלֵּין מַתָּכָאן אַחֲרָנִין, דְּדַמְיָין לוֹן.</p>\n<p>(כגונא דאלין) תָּא חֲזֵי. אֵ\"ש רוּ\"חַ וְמַיִ\"ם וְעָפָ\"ר, אִלֵּין אִינּוּן קַדְמָאֵי וְשָׁרָשִׁין דִּלְעֵילָּא וְתַתָּא, וְתַתָּאִין וְעִלָּאִין עָלַיְיהוּ קַיְּימִין. וְאִלֵּין אִינּוּן אַרְבַּע, לְאַרְבַּע סִטְרֵי עָלְמָא, וְקַיְּימִין בְּאַרְבַּע אִלֵּין: צָפוֹ\"ן, וְדָרוֹ\"ם, וּמִזְרָ\"ח, וּמַעֲרָ\"ב. אִלֵּין אִינּוּן אַרְבַּע סִטְרִין דְּעָלְמָא, וְקַיְּימִין בְּאַרְבַּע אִלֵּין. אֵ\"ש לִסְטַר צָפוֹ\"ן. רוּ\"חַ לִסְטַר מִזְרָ\"ח. מַיִ\"ם לִסְטַר דָּרוֹ\"ם. בְּגִין דְדָרוֹם חָם וְיָבֵשׁ מָיִם קָרִים וְלַחִים עָפָ\"ר לִסְטַר מַעֲרָ\"ב. וְאַרְבַּע אִלֵּין, בְּאַרְבַּע אִלֵּין קְטִירִין, וְכֻלְּהוּ חַד, וְאִלֵּין עַבְדֵי אַרְבַּע מַתָּכָאן, דְּאִינּוּן זָהָ\"ב וָכֶסֶ\"ף וּנְחֹשֶׁ\"ת וּבַרְזֶ\"ל הָא אִינּוּן תְּרֵיסָר, וְכֻלְּהוּ חַד.</p>\n<p>תָּא חֲזֵי, אֵשׁ הוּא בִּשְׂמָאלָא, לִסְטַר צָפוֹן, דְּהָא אֵשׁ, תּוּקְפָּא דַּחֲמִימוּתָא בֵּיהּ, וְיָבִישׁוּ דִּילֵיהּ (עיין בתיקונים ס\"א ע\"א) תַּקִּיף. וְצָפוֹן בְּהִפּוּכָא דִּילֵיהּ הוּא, וְאִתְמְזִיג חַד בְּחַד וְאִיהוּ חַד. מַיִם לִימִינָא, וְהוּא לִסְטַר דָּרוֹם. וְקוּדְשָׁא בְּרִיךְ הוּא, לְחַבְּרָא (לאחזרא) לוֹן כַּחֲדָא, עָבִיד מִזְגָּא דָּא כְּמִזְגָּא דָּא.</p>\n<p>צָפוֹן אִיהוּ קַר וְלַח, אֶשָּׁא חַם וְיָבֵשׁ. אַחְלַף לוֹן לִסְטַר דָּרוֹם. דָּרוֹם, אִיהוּ חַם וְיָבֵשׁ. מַיִם קָרִים וְלַחִים. וְקוּדְשָׁא בְּרִיךְ הוּא מָזִיג לוֹן כְּחַד דְּנַפְקֵי מַיָּא מִדָּרוֹם, וְעָאלִין בְּגוֹ צָפוֹן. וּמִצָּפוֹן נַגְדֵּי מַיָּא. נָפִיק אֶשָּׁא מִצָּפוֹן, וְעָאל בְּתּוּקְפָא דְּדָרוֹם, וּמִדָּרוֹם נָפִיק תּוּקְפָּא דַּחֲמִימוּתָא לְעָלְמָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אוֹזִיף דָּא בְּדָא, וְכָל חַד וְחַד אוֹזִיף לְחַבְרֵיהּ מִדִּילֵיהּ כַּדְקָא חֲזֵי לֵיהּ. כְּגַוְונָא דָּא רוּחַ וּמִזְרָח, בְּגִין דְּיוֹזִיף כָּל חַד לְחַבְרֵיהּ, וְאִתְכְּלִיל דָּא בְּדָא, לְאִתְחַבְּרָא כְּחַד.</p>\n<p>תָּא חֲזֵי, אֶשָּׁא מִסִּטְרָא דָּא, מַיִם מִסִּטְרָא דָּא. וְאִינּוּן מַחֲלוֹקֶת. עָאל רוּחַ בֵּינַיְיהוּ, וְאָחִיד לִתְרֵין סִטְרִין. הֲדָא הוּא דִּכְתִּיב, (בראשית א׳:ב׳) וְרוּחַ אֱלהִים מְרַחֶפֶת עַל פְּנִי הַמָּיִם. דְּהָא אֶשָּׁא קָאִים לְעֵילָּא בְּסִטְרָא דָּא. וּמַיִם קַיְימֵי עַל אַפֵּי אֲרְעָא. רוּחָא אָעִיל בֵּינַיְיהוּ, וְאָחִיד לִתְרֵין סִטְרִין, וְאַפְרִישׁ מַחֲלוֹקֶת. עָפָר, מַיָּא קַיְּימֵי עָלֵיהּ וְרוּחָא וְאֶשָּׁא וּמְקַבְּלָא מִכֻּלְּהוּ, בְּחֵילָא דִּתְלָתָא אִלֵּין דְּקַיְּימֵי עָלָהּ.</p>\n<p>תָּא חֲזֵי, רוּחַ וּמִזְרָח. מִזְרָח, חַם וְלַח, רוּחַ, (קר ויבש סטרא דאיהו יבישא) חַם וְלַח אִיהוּ, וּבְגִינִי כַּךְ, אָחִיד לִתְרֵין סִטְרִין, דְּהָא אֵשׁ חַם וְיָבֵשׁ, וּמַיִם קָרִים וְלַחִים, רוּחַ אִיהוּ חַם וְלַח, סִטְרָא דְּאִיהוּ חַם, אָחִיד בְּאֶשָּׁא. סִטְרָא דְּאִיהוּ לַח, אָחִיד בְּמַיָּא. וְעַל דָּא אַסְכִּים בֵּינַיְיהוּ, וְאַפְרִישׁ מַחֲלוֹקֶת דְּאֶשָׁא וּמַיָּא.</p>\n<p>עָפָר אִיהוּ קַר וְיָבֵשׁ, וְעַל דָּא מְקַבֵּל עָלֵיהּ כֻּלְּהוּ, וְכֻלְּהוּ עַבְדֵי בֵּיהּ עֲבִידְתַּיְיהוּ, וּמְקַבְּלָא מִכֻּלְּהוּ, לְאַפָּקָא בְּחֵילֵיהוֹן מְזוֹנָא לְעָלְמָא. בְּגִין דְּבְמַעֲרָב אִתְאֲחִיד עַפְרָא, דְּאִיהוּ קַר וְיָבֵשׁ. וְסִטְרָא דְּאִיהוּ קַר, אָחִיד בַּצָּפוֹן דְּאִיהוּ קַר וְלַח, דְּהָא קְרִירָא אִתְאֲחִיד בִּקְרִירָא. בְּגִין כָּךְ צָפוֹן אִתְאֲחִיד בַּמַּעֲרָב בְּסִטְרָא דָּא. דָּרוֹם דְּאִיהוּ חַם וְיָבֵשׁ, בְּהַהוּא יְבֵישׁוּתָא דִּילֵיהּ, אָחִיד לִיבֵשׁוּתָא דְּמַעֲרָב בְּסִטְרָא אָחֳרָא, וְאִתְאֲחִיד מַעֲרָב בִּתְרֵין סִטְרִין.</p>\n<p>וְכֵן אִתְאֲחִיד דָּרוֹם בְּמִזְרָח, דְּהָא חֲמִימוּתָא דְּדָרוֹם, אִתְאֲחִיד בֵּיהּ בַּחֲמִימוּתָא דְּמִזְרָח. וּמִזְרָח אִתְאֲחִיד בַּצָּפוֹן דְּהָא לָחוּתָא דִּילֵיהּ אִתְאֲחִיד בְּלָחוּתָא דְּצָפוֹן. הַשְּׁתָּא אִשְׁתְּכַח דְּרוֹמִי\"ת מִזְרָחִי\"ת. מִזְרָחִי\"ת צְפוֹנִי\"ת. צְפוֹנִי\"ת מַעֲרָבִי\"ת. מַעֲרָבִי\"ת דְּרוֹמִי\"ת וְכֻלְּהוּ כְּלִילָן דָּא בְּדָא, לְאִשְׁתַּלְשְׁלָא חַד בְּחַד.</p>\n<p>כְּגַוְונָא דָּא, צָפוֹן עָבִיד דַּהֲבָא. דְּמִסְטְרָא דְּתּוּקְפָּא דְּאֶשָּׁא, אִתְעָבִיד דַּהֲבָא. וְהַיְינוּ דִּכְתִּיב, (איוב ל״ז:כ״ב) מִצָּפוֹן זָהָב יֶאֱתֶה. דְּאֵשׁ אִתְאֲחִיד בֶּעָפָר, וְאִתְעָבִיד דַּהֲבָא. וְהַיְינוּ דִּכְתִּיב, (איוב כ״ח:ו׳) וְעַפְרוֹת זָהָב לוֹ. וְרָזָא דָּא, שְׁנַיִם כְּרוּבִים זָהָב.</p>\n<p>מַיִם אִתְאֲחִיד בֶּעָפָר, וּקְרִירוּתָא בְּלָחוּתָא עָבִיד כֶּסֶף, הַשְׁתָּא הָא עָפָר אִתְאֲחִיד בִּתְרֵין סִטְרִין, בַּזָּהָב וּבַכֶּסֶף, וְאִתְיְיהִיב בֵּינַיְיהוּ. רוּחָא אָחִיד לְמַיִם, וְאָחִיד (הגהה תמיהה במה דאמר רוח קר ויבש שאם כן עפר ורוח שוים בטבעם אבל יש אומרים כי רוח חם ולח (עמ\"ש בתיקונים ל\"ה ב') ואם כן נוכל לומר דאחיד רוח לתרין סטרין אש חם ויבש ורוח חם ולח סטרא דאיהו חם אחיד באש וסטרא דאיהו לח אחיד במיא ואפריש מחלוקת דאשא ומיא. עפר איהו קר ויבש ומים קרים ולחים וסטרא דקר אחיד בעפר בסטרא דקר אשתכח דעפר מקבל עליה כלהו בגין כך אחיד לתרין סטרין דהא אש חם ויבש מים קר ולח ע\"כ) <Nonei></i>לְאֵשׁ, וְאַפִּיק תְּרֵין כְּחַד, דְּאִיהוּ (יחזקאל א׳:ז׳) עֵין נְחֹשֶׁת קָלָל. וְעָפָר דְּקַאמְרָן, כַּד אִיהוּ בִּלְחוֹדוֹי, בִּיבִישׁוּ וּקְרִירוּ דִּילֵיהּ, נָפִיק בַּרְזֶל, וְסִימָנִיךְ, (קהלת י׳:י׳) אִם קֵהָה הַבַּרְזֶל וְגוֹ'</p>\n<p>וְהַאי עָפָר, אִתְאֲחִיד בְּכֻלְּהוּ, וְכֻלְּהוּ עַבְדִין בֵּיהּ כְּגַוְונָא דִּלְהוֹן. תָּא חֲזֵי, בְּלָא עָפָר, לֵית זָהָב וָכָסֶף וּנְחֹשֶׁת, דְּהָא כָּל חַד וְחַד אוֹזִיף לְחַבְרֵיהּ מִדִּילֵיהּ, לְאִתְקַשְּׁרָא דָּא בְּדָא. וְאִתְאֲחִיד עָפָר בְּכֻלְּהוּ, בְּגִין דִּתְרֵין סִטְרִין אֲחִידָן לֵיהּ, אֶשָּׁא וּמַיָּא. וְרוּחָא אִתְקְרִיב בֵּיהּ, בְּגִין אִלֵּין תְּרֵין וְעָבִיד בֵּיהּ עֲבִידְתָּא.</p>\n<p>אִשְׁתְּכַח, דְּכַד אִתְחַבַּר עַפְרָא בַּהֲדַיְיהוּ, עָבִיד וְאוֹלִיד עַפְרָא אַחֲרָנִין, כְּגַוְונָא דִּלְהוֹן. כְּגַוְונָא דְּזָהָב, אוֹלִיד עַפְרָא (רל\"ו ע\"ב) סוּסְפִיתָא יְרוֹקָא, דְּאִיהוּ כְּגַוְונָא דְּדַהֲבָא מַמָּשׁ. כְּגַוְונָא דְּכֶסֶף, אוֹלִיד עוֹפֶרֶת. כְּגַוְונָא דִּנְחֹשֶׁת עִילָּאָה, אוֹלִיד קְסִיטְרָא דְּאִיהוּ נְחֹשֶׁת זוּטָא. כְּגַוְונָא דְּבַרְזֶל, אוֹלִיד בַּרְזֶל, וְסִימָנִךְ (משלי כ״ז:י״ז) בַּרְזֶל בְּבַרְזֶל יָחַד.</p>\n<p>תָּא חֲזֵי, אֵשׁ רוּחַ מַיִם וְעָפָר, כֻּלְּהוּ אֲחִידָן דָּא בְּדָא, וְאִתְקַשְּׁרָן דָּא בְּדָא. וְלָא הֲוֵי בְּהוּ פִּרוּדָא. וְעָפָר דָּא, כַּד אִיהוּ אוֹלִיד לְבָתַר, לָא מִתְקַשְּׁרָן דָּא בְּדָא בְּאִינּוּן עִלָּאֵי, כְּמָה דְּאַתְּ אָמֵר, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, בְּאִלֵּין הֲוֵי פִּרוּדָא.</p>\n<p>בְּגִין דְּהָא עָפָר, כַּד אִיהוּ אוֹלִיד בְּחֵילָא דִּתְלַת עִלָּאֵי, אַפִּיק אַרְבְּעָה נַהֲרִין, דְּתַמָּן מִשְׁתַּכְּחֵי אַבְנֵי יְקָר, וּבַאֲתַר חַד אִינּוּן, דִּכְתִּיב שָׁם הַבְּדֹלַח וְאֶבֶן הַשֹּׁהַם. וְאִלֵּין אַבְנֵי יָקָר אִינּוּן תְּרֵיסַר, וְאִינּוּן לְאַרְבַּע סִטְרֵי עָלְמָא, לָקֳבֵיל תְּרֵיסַר שְׁבָטִין, דִּכְתִּיב, (שמות כ״ח:כ״א) וְהָאֲבָנִים תִּהְיֶיןָ עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל שְׁתֵּים עֶשְׂרֵה עַל שְׁמוֹתָם. וְאִלֵּין תְּרֵיסַר בָּקָר, דְּאִינּוּן תְּחוֹת יַמָּא.</p>\n<p>תָּא חֲזֵי, כָּל אַרְבְּעָה סִטְרִין עִלָּאִין דְּקַאמְרָן, אַף עַל גַּב דְּמִתְקַשְּׁרָן דָּא בְּדָא, וְאִינּוּן קִיּוּמָא דִּלְעֵילָּא וְתַתָּא, קִיּוּמָא דְּעָלְמָא יַתִּיר רוּחַ, בְּגִין דְּכֹלָּא קַיְּימָא בְּגִינֵיהּ, וְנַפְשָׁא לָא קַיְּימָא אֶלָּא בְּרוּחָא, דְּאִי גָּרַע רוּחָא אֲפִילּוּ רִגְעָא חֲדָא, נַפְשָׁא לָא יָכִילַת לְאִתְקַיְּימָא, וְרָזָא דָּא כְּתִיב, (משלי י״ט:ב׳) גַּם בְּלֹא דַעַת נְפֶשׁ לֹא טוֹב. נַפְשָׁא בְּלֹא רוּחָא לָאו אִיהוּ טוֹב, וְלָא יַכְלָא לְאִתְקַיְּימָא.</p>\n<p>וְתָא חֲזֵי, אִינּוּן תְּרֵיסָר דְּקַאמְרָן, דְּאִינּוּן תְּרֵיסַר אַבָנִין, אִינּוּן תְּרֵיסַר בָּקָר, דִּתְחוֹת יַמָּא. בְּגִין כַּךְ, נָטְלוּ אִינּוּן תְּרֵיסָר נְשִׂיאִים, (במדבר ז׳:פ״ז) כָּל הַבָּקָר לָעֹלָה שְׁנֵים עָשָׂר פָרִים וְגוֹ'. וְכֹלָּא רָזָא עִלָּאָה הוּא, וּמַאן דְּיַשְׁגַּח בְּמִלִּין אִלֵּין, יַשְׁגַּח בְּרָזָא דְּחָכְמְתָא עִלָּאָה, דְּעִקָר דְּכֹלָּא בֵּיהּ.</p>\n<p>אָמַר ר' שִׁמְעוֹן, הָא דְּאָמַר ר' חִזְקִיָּה, דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם, מֵעַפְרָא דְּמַקְדְּשָׁא דִּלְתַתָּא אִתְבְּרֵי, מֵעַפְרָא דְּמַקְדְּשָׁא דִּלְעֵילָּא אִתְיְיהִיב בֵּיהּ נִשְׁמְתָא. כְּמָה דְּכַד אִתְבְּרֵי מֵעַפְרָא דִּלְתַתָּא, אִתְחַבְּרוּ בֵּיהּ תְּלַת סִטְרָא יְסוֹדֵי עָלְמָא. הָכִי נָמֵי כַּד אִתְבְּרֵי מֵעַפְרָא דִּלְעֵילָּא, אִתְחַבְּרוּ בֵּיהּ תְּלַת סִטְרֵי יְסוֹדֵי עָלְמָא, וְאִשְׁתְּלִים אָדָם. וְהַיְינוּ דִּכְתִּיב, (תהילים ל״ב:ב׳) אַשְׁרֵי אָדָם לא יַחְשֹׁב יְיָ' לוֹ עָוֹן וְאֵין בְּרוּחוֹ רְמִיָּה. אֵימָתַי לֹא יַחְשֹׂב יְיָ' לוֹ עָוֹן, בִּזְמַן דְּאֵין בְּרוּחוֹ רְמִיָּה.</p>\n<p>תָּא חֲזֵי, מֹשֶׁה אִשְׁתְּלִים יַתִּיר מֵאֲבָהָן, בְּגִין דְּמַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, מִדַּרְגָּא עִלָּאָה יַתִּיר מִכֻּלְּהוּ, וּמֹשֶׁה פְּנִימָאָה דְּבֵי מַלְכָּא עִלָּאָה הֲוָה, וְעַל דָּא כְּתִיב, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב וְגוֹ', וְהָא אוֹקִימְנָא מִלֵּי.</p>"],[9520011564,"<p>(שמות ו׳:ו׳) לָכֵן אֱמֹר לִבְנִי יִשְׂרָאֵל אֲנִי יְיָ' וְהוֹצֵאתִי אֶתְכֶם. רִבִּי יְהוּדָה אָמַר, הַאי קְרָא אִפְּכָא הוּא, דִּכְתִּיב וְהוֹצֵאתִי אֶתְכֶם מִתַּחַת סִבְלוֹת מִצְרַיִם בְּקַדְמִיתָא, וּלְבָתַר וְהִצַּלְתִּי אֶתְכֶם מֵעֲבוֹדָתָם, וּלְבָתַר וְגָאַלְתִּי אֶתְכֶם, הֲוָה לֵיהּ לְמֵימָר מֵעִיקָּרָא וְגָאַלְתִּי אֶתְכֶם, וּלְבָתַר וְהוֹצֵאתִי אֶתְכֶם. אֶלָּא, עִקָּרָא דְּכֹלָּא בְּקַדְמִיתָא, דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְבַשְּׂרָא לוֹן בִּשְׁבָחָא דְּכֹלָּא בְּקַדְמִיתָא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, וְהָא שְׁבָחָא דְּכֹלָּא, וְלָקַחְתִּי אֶתְכֶם לִי לְעָם וְהָיִיתִי <Nonei></i>לָכֶם לֵאלֹהִים, וְאָמַר לֵיהּ לְבָתַר. אֲמַר לֵיהּ, בְּהַהוּא זִמְנָא, לֵית לְהוּ שְׁבָחָא אֶלָּא יְצִיאָה. דְּחָשִׁיבִי דְּלָא יִפְקוּן מֵעַבְדוּתְהוֹן לְעָלְמִין, בְּגִין דַּהֲווֹ חָמָאן תַּמָּן דְּכָל אֲסִירֵי דַּהֲווֹ בֵּינַיְיהוּ מְקַשְׁרוּ לוֹן בְּקִשְׁרָא דְּחָרָשֵׁי, וְלָא יַכְלִין לְנָפְקָא מִבֵּינַיְיהוּ לְעָלְמִין. וּבְגִין כַּךְ, מַה דְּחָבִיב עָלַיְיהוּ מִכֹּלָּא, אִתְבַּשָּׂרוּ בֵּיהּ.</p>\n<p>וְאִי תֵּימָא אַף עַל גַּב דְּנָפְקוּ, הָא דִּילְמָא יִזְּלוּן (חיליהו) בַּתְרַיְיהוּ לְאַבְאָשָׁא לוֹן, כְּתִיב וְהִצַּלְתִּי אֶתְכֶם מֵעֲבוֹדָתָם. וְאִי תֵּימָא הָא יִפְקוּן וְיִשְׁתֵּזְבוּן, וְלָא יְהֵא לוֹן פְרִיקָא, תַּלְמוּד לוֹמַר וְגָאַלְתִּי אֶתְכֶם בִּזְרוֹעַ נְטוּיָה. וְאִי תֵּימָא לֹא יְקַבְּלֵם, הָא כְּתִיב וְלָקַחְתִּי. וְאִי תֵּימָא כְּשֶׁיְּקַבְּלֵם לֹא יְבִיאֵם לָאָרֶץ, הָא כְּתִיב וְהֵבֵאתִי אֶתְכֶם וְגוֹ'.</p>"],[9520011565,"<p><Noneb>רעיא מהימנא</b> (שמות ו׳:ז׳) וְלָקַחְתִּי אֶתְכֶם לִי לְעָם וְהָיִיתִי לָכֶם לֵאלֹהִים וִידַעְתֶּם כִּי אֲנִי יְיָ' אֱלֹהֵיכֶם וְגוֹ' פִּקּוּדָא דָּא קַדְמָאָה דְּכָל פִּקּוּדִין. רֵאשִׁיתָא קַדְמָאָה דְּכָל פִּקּוּדִין, לְמִנְדַּע לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא בִּכְלָלָא. מַאי בִּכְלָלָא. לְמִנְדַּע דְּאִית שַׁלִּיטָא עִלָּאָה, דְּאִיהוּ רִבּוֹן עָלְמָא, וּבָרָא עָלְמִין כֻּלְּהוּ, שְׁמַיָּא וְאַרְעָא וְכָל חֵילֵיהוֹן. וְדָא אִיהוּ בִּכְלָלָא. וְסוֹפָא דְּכֹלָּא בִּפְרָט, לְמִנְדַּע לֵיהּ בִּפְרָט.</p>\n<p>וּכְלָל וּפְרָט אִיהוּ רֵישָׁא וְסוֹפָא רָזָא דְּכָר וְנוּקְבָּא כַּחֲדָא, וְאִשְׁתְּכַח בַּר נָשׁ בְּהַאי עָלְמָא, דְּאִתְעַסָּק בִּכְלָל וּפְרָט, בַּר נָשׁ בְּהַאי עָלְמָא אִיהוּ כְּלָל וּפְרָט. תִּקּוּנָא דְּהַאי עָלְמָא, אִיהוּ כְּלָל וּפְרָט. בְּגִין כָּךְ, רִאשִׁיתָא דְּכֹלָּא, לְמִנְדַּע דְּאִית שַׁלִּיט וְדַיָּין עַל עָלְמָא, וְאִיהוּ רִבּוֹן כָּל עָלְמִין. וּבָרָא לֵיהּ לְבַר נָשׁ מֵעַפְרָא, וְנָפַח בְּאַפּוֹי נִשְׁמְתָא דְּחַיֵּי, וְדָא אִיהוּ בְּאוֹרַח כְּלָל.</p>\n<p>כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲווֹ יַדְעֵי לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא כֵּיוָן דְּאָתָא מֹשֶׁה לְגַבַּיְיהוּ, פִּקּוּדָא קַדְמָאָה דָּא אוֹלִיף לוֹן, דִּכְתִּיב, וִידַעְתֶּם כִּי אֲנִי יְיָ' אֱלהֵיכֶם הַמּוֹצִיא אֶתְכֶם וְגוֹ'. וְאִלְמָלֵא פִּקּוּדָא דָּא, לָא הֲווֹ יִשְׂרָאֵל מֵהֵימְנִין, בְּכָל אִינּוּן נִיסִּין וּגְבוּרָן דְּעָבַד לוֹן בְּמִצְרַיִם. כֵּיוָן דְּיָדְעוּ פִּקּוּדָא דָּא בְּאוֹרַח כְּלָל, אִתְעָבִידוּ לְהוֹן נִסִּין וּגְבוּרָן.</p>\n<p>וּלְסוֹף מ' שְׁנִין, דְּקָא אִשְׁתְּדָלוּ בְּכָל אִינּוּן פִּקּוּדִין דְּאוֹרַיְיתָא, דְּאוֹלִיף לוֹן מֹשֶׁה, בֵּין אִינּוּן דְּמִתְנָהֲגֵי בְּאַרְעָא בֵּין אִינּוּן דְּמִתְנָהֲגֵי לְבַר מֵאַרְעָא כְּדֵין, אוֹלִיף לוֹן בְּאוֹרַח פְּרָט, הֲדָא הוּא דִכְתִיב, (דבהם ד') וְיָדַעְתָּ הַיּוֹם וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ, הַיּוֹם דַּיְיקָא, מַה דְּלָא הֲוָה רְשׁוּ מִקַּדְמַת דְּנָא. כִּי יְיָ' הוּא הָאֱלהִים, דָּא בְּאוֹרַח פְּרָט, בְּמִלָּה דָּא, כַּמָּה רָזִין וְסִתְרִין אִית בָּהּ. וְדָא, וְהַהוּא דְּקַדְמֵיתָא, כֹּלָּא מִלָּה חֲדָא, דָּא בִּכְלָל, וְדָא בִּפְרָט.</p>\n<p>וְאִי תֵּימָא, הָא כְּתִיב, (משלי א׳:ז׳) יִרְאַת יְיָ' רֵאשִׁית דָּעַת. תִּירוּצָא, דָּא בְּאוֹרַח פְּרָט, לְמִנְדַּע מַאן אִיהוּ יִרְאַת יְיָ'. וְאַף עַל גַּב דְּאִית לֵיהּ לְבַר נָשׁ לְדַחֲלָא מִנֵּיהּ, עַד לָא יִנְדַּע, אֲבָל הָכָא כְּתִיב רֵאשִׁית דַּעַת, לְמִנְדַּע לֵיהּ דְּהָא אִיהוּ רֵאשִׁיתָא, לְמִנְדַּע לֵיהּ בְּאוֹרַח פְּרָט.</p>\n<p>בְּגִין כַּךְ, פִּקּוּדָא קַדְמָאָה לְמִנְדַּע לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא בִּכְלָל וּפְרָט, בְּרֵישָׁא וּבְסוֹפָא. וְרָזָא דָּא (ישעיהו מ״ד:ו׳) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן. אֲנִי רִאשׁוֹן בִּכְלָל, וַאֲנִי אַחֲרוֹן בִּפְרָט. וְכֹלָּא בִּכְלָלָא חֲדָא, וְרָזָא חֲדָא. כֵּיוָן דְּיִנְדַּע דָּא בִּכְלָל, יַשְׁלִים כָּל שַׁיְיפוֹי. וּמַאן אִינּוּן. רמ\"ח פִּקּוּדִין, דְּאִינּוּן רמ\"ח שַׁיְיפִין דְּבַר נָשׁ. כֵּיוָן דְּאִשְׁתְּלִים בְּהוּ עַל הַאי בִּכְלָל, כְּדֵין יִנְדַּע בְּאוֹרַח פְּרָט, דְּדָא אִיהוּ אַסְוָותָא לְכֻלְּהוּ, וְיִנְדַּע כָּל יוֹמֵי שַׁתָּא, דְּמִתְחַבְּרָן לְמֵיהַב אַסְוָותָא לְכָל שַׁיְיפִין.</p>\n<p>וְאִי תֵּימָא, כָּל יוֹמֵי שַׁתָּא, הֵיךְ יַהֲבִין אַסְוָותָא לְכָל שַׁיְיפִין. וַדַּאי הָכִי הוּא עֵילָּא וְתַתָּא, שַׁתָּא וְיוֹמֵי דִּילֵיהּ, יַהֲבִין אַסְוָותָא לְכָל שַׁיְיפִין עֵילָּא וְתַתָּא, (בזמנא) דְּשַׁיְיפִין אֲרִיקוּ בִּרְכָּאן לְיוֹמֵי שַׁתָּא כְּדֵין אַסְוָותָא וְחַיִּין תַּלְיָין עֲלָן מִלְּעֵילָּא, וְאִתְמַלְיָין מִכֹּלָּא. מַאן גָּרִים לוֹן. יוֹמֵי שַׁתָּא.</p>\n<p>אוּף הָכִי נָמֵי לְתַתָּא, כַּד בַּר נָשׁ יַשְׁלִים גּוּפֵיהּ בְּאִינּוּן פִּקּוּדִין דְּאוֹרַיְיתָא לֵית לָךְ כָּל יוֹמָא דְּלָא אַתְיָיא לְאִתְבָּרְכָא מִנֵּיהּ, וְכַד אִינּוּן אִתְבָּרְכָאן מִנֵּיהּ, כְּדֵין חַיִּין וְאַסְוָותָא תַּלְיָין עָלֵיהּ מִלְּעֵילָּא. מַאן גָּרִים לֵיהּ. אִינּוּן יוֹמֵי שַׁתָּא. יוֹמֵי שַׁתָּא, כְּמָה דְּאִתְבָּרְכָאן מִלְּעֵילָּא מֵרָזָא <Nonei></i>דְּאָדָם. הָכִי נָמֵי אִתְבָּרְכָאן מִתַּתָּא מֵרָזָא דְּאָדָם.</p>\n<p>זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּהַאי עָלְמָא, בְּאִלֵּין פִּקּוּדִין דְּאוֹרַיְיתָא, דְּאִקְרוּן אָדָם, דִּכְתִּיב. (יחזקאל ל\"ד) אָדָם אַתֶּם. אַתֶּם קְרוּיִים אָדָם, וְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לָא אִקְרוּן אָדָם. וּבְגִין דְּיִשְׂרָאֵל אִקְרֵי אָדָם, אִית לוֹן לְאִשְׁתַּדְּלָא בְּאִינּוּן פִּקּוּדִין דְּאוֹרַיְיתָא, לְמֶהֱוֵי כֹּלָּא חַד, בְּרָזָא דְּאָדָם.</p>\n<p>כַּד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל עַל טוּרָא דְּסִינַי, מִלָּה קַדְמָאָה אִיהוּ אָנֹכִי, אָנֹכִי סַלְּקָא לְרָזִין (עלמין) סַגִּיאִין. וְהָכָא אִיהוּ רָזָא דְּפִקּוּדָא קַדְמָאָה, לְמִנְדַּע לֵיהּ בִּכְלָלָא. בְּגִין דִּכְתִּיב אָנֹכִי, הָא קָא רָמִיז, דְּאִית אֱלָהָא שַׁלִּיטָא עִלָּאָה (דאיהו) עַל עָלְמָא, כְּמָה דְאַתְּ אָמֵר (דברים ד׳:כ״ד) כִּי יְיָ' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא, פִּקּוּדָא קַדְמָאָה בִּכְלָל. בִּפְרָט: בְּגִין דִּכְתִּיב, ה' אֱלֹהֶיךָ דָּא פְּרָט, וְדָא כְּלָל וּפְרָט, פִּקּוּדָא קַדְמָאָה, דְּאִצְטְרִיךְ לְמִנְדַּע בְּרִישָׁא וּבְסוֹפָא, כְּמָה דְּאוֹקִימְנָא. (ע\"כ רעיא מהימנא).</p>"],[9520011566,"<p>(שמות ו׳:ט׳) וַיְדַבֵּר מֹשֶׁה כֵּן אֶל בְּנֵי יִשְׂרָאֵל וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקּוֹצֶר רוּחַ. מַאי מִקּוֹצֶר רוּחַ. אָמַר רִבִּי יְהוּדָה, דְּלָא הֲווֹ נְפִישֵׁי, וְלָא הֲווֹ לְקִיטֵי רוּחָא. אָמַר רִבִּי שִׁמְעוֹן, מִקּוֹצֶר רוּחַ: דְּעַד לָא נָפַק יוֹבְלָא, לְמֵיהַב לוֹן נְפִישׁוּ. וְרוּחַ בַּתְרָאָה, עַד לָא שַׁלְטָא לְמֶעְבַּד נִימוּסֵי, וּכְדֵין הֲוָה עָאקוּ דְּרוּחָא. מַאן אִיהוּ. רוּחַ בַּתְרָאָה דְּקַאמְרָן. (נ\"א דעד לא יהב ליה יובלא ברכה על האי רוחא לאתקיימא נפש תתאה ולא שלטא האי רוח על נפש אלא כד אתברכא מיובלא כדין יהא רוחא ומאן איהו רוח)</p>"],[9520011567,"<p>תָּא חֲזֵי, כְּתִיב (שמות ו׳:י״ב) הֵן בְּנֵי יִשְׂרָאֵל לֹא שָׁמְעוּ אֵלַי וְאֵיךְ יִשְׁמָעֵנִי פַרְעֹה וַאֲנִי עֲרַל שְׂפָתָיִם, מַאי וַאֲנִי עֲרַל שְׂפָתָיִם. וְהָא בְּקַדְמִיתָא כְּתִיב (שמות ד׳:י׳) לֹא אִישׁ דְּבָרִים אָנֹכִי וְגוֹ' כִּי כְבַד פֶּה וּכְבַד לָשׁוֹן אָנֹכִי, וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה אוֹתִיב לֵיהּ, (שמותד') מִי שָׂם פֶּה לָאָדָם וְגו', וְהוּא אָמַר (שמות ד׳:י״ב) וְאָנֹכִי אֶהְיֶה עִם פִּיךָ, סַלְּקָא דַּעְתָּךְ דְּלָא הֲוָה כֵּן, וְהַשְּׁתָּא אָמַר וַאֲנִי עֲרַל שְׂפָתָיִם, אִי הָכִי, אָן הוּא מִלָּה דְּאַבְטַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא.</p>\n<p>אֶלָּא רָזָא אִיהוּ, מֹשֶׁה קָלָא, וְדִבּוּר דְּאִיהוּ מִלָּה דִּילֵיהּ, הֲוָה בְּגָלוּתָא, וַהֲוָה אִיהוּ אָטִים לְפָרְשָׁא מִלִּין, וּבְגִין דָּא אָמַר, וְאֵיךְ יִשְׁמָעֵנִי פַרְעֹה, בְּעוֹד דְּמִלָּה דִּילִי אִיהִי בְּגָלוּתָא דִּילֵּיהּ, דְּהָא לֵית לִי מִלָּה. הָא אֲנָא קָלָא מִלָּה גָּרַע, דְּאִיהִי בְּגָלוּתָא, וְעַל דָּא, שָׁתַּף קוּדְשָׁא בְּרִיךְ הוּא לְאַהֲרֹן בַּהֲדֵיהּ.</p>\n<p>תָּא חֲזֵי, כָּל זִמְנָא דְּדִבּוּר הֲוָה בְּגָלוּתָא, קָלָא אִסְתְּלַק מִנֵּיהּ, וּמִלָּה הֲוָה אָטִים בְּלֹא קוֹל, כַּד אָתָא מֹשֶׁה, אָתָא קוֹל. וּמֹשֶׁה הֲוָה קוֹל בְּלא מִלָּה, בְּגִין דְּהֲוָה בְּגָלוּתָא, וְכָל זִמְנָא דְּדִבּוּר הֲוָה בְּגָלוּתָא, מֹשֶׁה אָזִיל קָלָא בְּלָא דִּבּוּר, וְהָכִי אָזִיל עַד דְּקָרִיבוּ לְטוּרָא דְּסִינַי, וְאִתְיְהִיבַת אוֹרַיְיתָא, וּבְהַהוּא זִמְנָא, אִתְחַבָּר קָלָא בְּדִבּוּר, וּכְדֵין מִלָּה מַלִּיל, הֲדָא הוּא דִכְתִיב, (שמות כ׳:א׳) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה. וּכְדֵין, מֹשֶׁה אִשְׁתְּכַח שְׁלִים בְּמִלָּה כְּדְקָא יֵאוֹת, קוֹל וְדִבּוּר כַּחֲדָא בִּשְׁלִימוּ.</p>\n<p>וְעַל דָּא מֹשֶׁה אִתְרְעִים, דְּמִלָּה גָּרַע מִנֵּיהּ, בַּר הַהוּא זִמְנָא דְּמַלִּילַת לְאִתְרַעֲמָא עֲלוֹי, בְּזִמְנָא דִּכְתִּיב, (שמות ו') וּמֵאָז בָּאתִי אֶל פַּרְעֹה לְדַבֵּר בִּשְׁמֶךָ, מִיַּד (שמות ו׳:ב׳) וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה. תָּא חֲזֵי דְּהָכִי הוּא דְּשָׁרָא מִלָּה לְמַלְּלָא וּפָסַק לָהּ, בְּגִין דְּעַד לָא מָטָא זִמְנָא דִּכְתִּיב וַיְדַבֵּר אֱלֹהִים וְגוֹ'. וּפָסַק וְאַשְׁלִים קָלָא, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אֵלָיו אֲנִי ה'. בְּגִין דְּדִבּוּר הֲוָה בְּגָלוּתָא, וְלָא מָטָא זִמְנָא לְמַלְּלָא. (ותא חזי)</p>\n<p>בְּגִינֵי כַּךְ, מֹשֶׁה לָא הֲוָה שְׁלִים מִלָּה בְּקַדְמִיתָא, (דהכי אתחזי) דְּאִיהוּ קוֹל, וְאָתֵי בְּגִין דִּבּוּר, לְאַפָּקָא לֵיהּ מִן גָּלוּתָא. כֵּיוָן דְּנָפַק מִן גָּלוּתָא, וְאִתְחֲבָּרוּ קוֹל וְדִבּוּר כַּחֲדָא בְּטוּרָא דְּסִינַי, אִשְׁתְּלִים מֹשֶׁה וְאִתְסֵי, וְאִשְׁתְּכַח כְּדֵין קוֹל וְדִבּוּר כַּחֲדָא בִּשְׁלִימוּ.</p>\n<p>תָּא חֲזֵי, כָּל יוֹמִין דְּהֲוָה מֹשֶׁה בְּמִצְרַיִם, דְּבָעָא לְאַפָּקָא מִלָּה מִן גָּלוּתָא, לָא מַלִּיל מִלָּה, דְּאִיהוּ דִּבּוּר. כֵּיוָן דְּנָפַק מִן גָּלוּתָא, וְאִתְחֲבָּר קוֹל בְּדִבּוּר, הַהוּא מִלָּה דְּאִיהוּ דִּבּוּר, אַנְהִיג וְדָבַּר לוֹן לְיִשְׂרָאֵל, אֲבָל לָא מַלִּיל, עַד דְּקָרִיבוּ לְטוּרָא דְּסִינַי, וּפָתַח בְּאוֹרַיְיתָא, דְּהָכִי אִתְחָזֵי. וְאִי תֵּימָא, (שמות י״ג:י״ז) כִּי אָמַר אֱלֹקִים פֶּן יִנָּחֵם הָעָם, לָא כְּתִיב כִּי דִּבֵּר, אֶלָּא כִּי אָמַר, דְּאִיהוּ רְעוּתָא דְּלִבָּא בַּחֲשָׁאי, וְהָא (ויחי רל\"ד ע\"ב) אוֹקִימְנָא.</p>\n<p><Nonei></i>וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה וַיֹּאמֶר אֵלָיו אֲנִי ה'. ר' יְהוּדָה פָּתַח, (שיר השירים ה׳:ו׳) קַמְתִּי אֲנִי לִפְתּוֹחַ לְדוֹדִי וְדוֹדִי חָמַק עָבָר וְגוֹ'. קַמְתִּי אֲנִי לִפְתּוֹחַ לְדוֹדִי, דָּא קָלָא. תָּא חֲזֵי, כְּנֶסֶת יִשְׂרָאֵל כַּד אִיהִי בְּגָלוּתָא, קָלָּא אִסְתְּלַק מִינָהּ, וּמִלָּה אִשְׁתְּכַךְ מִינָהּ, כְּמָה דְּאַתְּ אָמַר (תהילים ל״ט:ג׳) נְאֱלַמְתַּי דּוּמִיָּה. וְאִי אִתְּעַר מִלְּתָא, מַה כְּתִיב, וְדוֹדִי חָמַק עָבָר, דְּהָא קָלָא אִסְתְּלַק מִינָהּ, וּפָסְקָא מִלָּה. (כמה דאת אמר) וְעַל דָּא וַיְדַבֵּר אֱלהִים אֶל מֹשֶׁה, שָׁרִיאַת לְמַלְּלָא, וּפָסַק וְשָׁתִיק. לְבָתַר אַשְׁלִים קָלָא וְאָמַר וַיֹּאמֶר אֵלָיו אֲנִי ה'.</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב, בְּיַעֲקֹב תּוֹסֶפֶת וָא\"ו, דְּאִיהוּ שְׁלִימוּ דַּאֲבָהָן, כְּמָה דְּאַתְּ אָמַר, אֱלהֵי אַבְרָהָם אֱלהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב, בְּיַעֲקֹב תּוֹסֶפֶת וָא\"ו. אָמַר רִבִּי יוֹסֵי, אִי הָכִי, הָא כְּתִיב (בראשית כ״ח:י״ג) אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךָ וִאלהֵי יִצְחָק, הָא בְּיִצְחָק תּוֹסֶפֶת וָא\"ו.</p>\n<p>אָמַר לֵיהּ, שַׁפִּיר הֲוָה, בְּגִין דְּיַעֲקֹב הֲוָה קַיָּים, וְאַכְלִיל לֵיהּ לְיַעֲקֹב בְּיִצְחָק, (דהוה מית) דְּאִתְחַשְּׁכוּ עֵינוֹי, וַהֲוָה כַּמֵּת, דְּהָא בְּעוֹד דְּבַּר נָשׁ אִיהוּ קַיָּים בְּהַאי עָלְמָא, לָא אִדְכַּר עֲלוֹי שְׁמָא קַדִּישָׁא, וְעַל דָּא אַכְלִיל לֵיהּ בְּיִצְחָק. הַשְׁתָּא דְּמִית יַעֲקֹב, אָתָא מִלָּה בְּאַתְרֵיהּ. הֲדָא הוּא דִכְתִיב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב, בְּתוֹסֶפֶת ו'.</p>\n<p>בְּאֵל שַׁדָּי (בראשית קפ\"ג ע\"א): אִתְחָזֵינָא לְהוּ, מִגּוֹ אַסְפָּקָלַרְיָא דְּלָא נָהֲרָא. וְלָא אִתְחָזֵינָא מִגּוֹ אַסְפָּקָלַרְיָא דְּנָהֲרָא. וְאִי תֵּימָא דְּהָא אִשְׁתַּמְּשׁוּ בְּנוּקְבָא בִּלְחוֹד וְלָא יַתִּיר. תָּא חֲזֵי, דְּלָא אִתְפָּרְשָׁן לְעָלְמִין, הֲדָא הוּא דִכְתִיב וְגַם הֲקִימוֹתִי אֶת בְּרִיתִי אִתָּם, דְּהָא בְּרִית אִתְחַבַּר עִמָּהּ.</p>\n<p>מִּקוּדְשָׁא בְּרִיךְ הוּא אִית לֵיהּ לְבַר נָשׁ לְמֵילָף, דְּהָא אִיהוּ קָאָמַר דְּלָא פָּרִישׁ לוֹן, דִּכְתִּיב בְּאֵל שַׁדָּי, וּכְתִיב וְגַם הֲקִימוֹתִי אֶת בְּרִיתִי אִתָּם, בְּגִין לְקַיְּימָא קִיּוּמָא בְּיִחוּדָא חַד, וְגַם הֲקִימוֹתִי אֶת בְּרִיתִי אִתָּם וְגוֹ'. הָא אִתְּמַר, מַאן דְּזַכֵּי לִבְרִית, יָרִית לְאַרְעָא.</p>"],[9520011568,"<p>רִבִּי חִיָּיא וְרִבִּי יוֹסִי, הֲווֹ שְׁכִיחֵי יוֹמָא חַד קָמֵיהּ דְּרִבִּי שִׁמְעוֹן, פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (איוב י״ט:כ״ט) גּוּרוּ (ויקרא נ\"ב ע\"ב) לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲוֹנוֹת חֶרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן. שַׁדִּין כְּתִיב. גּוּרוּ לָכֶם מִפְּנִי חֶרֶב, מַאן חֶרֶב. דָּא (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, דְּהָא הַאי חֶרֶב קָאִים לְאִסְתַּכְּלָא מַאן דִּמְשַׁקֵּר בִּבְרִית, דְּכָל מַאן דִּמְשַׁקֵּר בִּבְרִית, נוּקְמָא (ויחי ר\"ג ע\"ב) דְּנַקְמִין מִנֵּיהּ, הַאי חֶרֶב הוּא.</p>\n<p>הֲדָא הוּא דִּכְתִּיב, (איוב י״ט:כ״ט) כִּי חֵמָה עֲוֹנוֹת חָרֶב. מַאי טַעֲמָא. בְּגִין דְּמַאן דִּמְשַׁקֵּר בִּבְרִית, פָּרִישׁ תִּיאוּבְתָּא, וְלָא נָטִיל מַאן דְּנָטִיל, וְלָא יָהִיב לְאַתְרֵיהּ, דְּהָא לָא אִתְּעַר לְגַבֵּיהּ אַתְרֵיהּ. וְכָל מַאן דְּנָטִיר לֵיהּ לְהַאי בְּרִית, אִיהוּ גָּרִים לְאִתְּעֲרָא לְהַאי בְּרִית לְאַתְרֵיהּ. וְאִתְבָּרְכָאן עִלָּאִין וְתַתָּאִין.</p>\n<p>מַאן אִתְּעַר הַאי בְּרִית לְאַתְרֵיהּ. כַּד אִשְׁתְּכָחוּ זַכָּאִין בְּעָלְמָא. מְנָא לָן, מֵהָכָא, דִּכְתִּיב, (שמות ו׳:ד׳) וְגַם הֲקִימוֹתִי אֶת בְּרִיתִי אִתָּם לָתֵת לָהֶם אֶת אֶרֶץ כְּנָעַן אֶת אֶרֶץ מְגוּרֵיהֶם. מַאי מְגוּרֵיהֶם. כְּמָה דְּאַתְּ אָמֵר גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב. בְּגִין דְּאִיהוּ אֲתָר, דְּאַשְׁדֵי מָגוֹר בְּעָלְמָא, וְעַל דָּא גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב.</p>\n<p>אֲשֶׁר גָּרוּ בָהּ, מִיּוֹמָא דְּאִתְקְרִיבוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּחִילוּ בָּהּ דְּחִילוּ, וּדְחִילוּ (נ\"א ודחילו דחילו) עִלָּאָה בָּהּ לְמִיטַר פִּקוּדוֹי. דְּאִי בְּהַאי לָא יִשְׁדֵי (נ\"א דהא לא אשדי) דְּחִילוּ עַל רֵישֵׁיהּ דְּבַר נָשׁ, לָא דָּחִיל לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין בִּשְׁאַר פִּקוּדוֹי.</p>\n<p>תָּא חֲזֵי, בְּאִתְעָרוּתָא דִּלְתַתָּא, כַּד אִתְּעָרוּ יִשְׂרָאֵל לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְצָוְוחוּ לָקֳבְלֵיהּ, מַה כְּתִיב, וָאֶזְכּוֹר אֶת בְּרִיתִי, דְּהָא בִּבְרִית הֲוֵי זָכוֹר. וּכְדֵין אִתְּעַר תִּיאוּבְתָּא, לְאִתְקַשְּׁרָא כֹּלָּא בְּקִשּׁוּרָא חַד. כֵּיוָן דְּהַאי בְּרִית אִתְּעַר, הָא קִשּׁוּרָא דְּכֹלָּא אִתְּעַר. וָאֶזְכּוֹר אֶת בְּרִיתִי, לְאִזְדַּוְּוגָא לֵיהּ בְּאַתְרֵיהּ. וְעַל דָּא, לָכֵן אֱמוֹר לִבְנֵי יִשְׂרָאֵל אֲנִי ה'.</p>"],[9520011569,"<p>(שמות ו׳:י״ג) וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן וַיְצַוֵּם אֶל בְּנִי יִשְׂרָאֵל וְאֶל פַּרְעֹה מֶלֶךְ מִצְרָיִם. ר' יוֹסֵי אָמַר, אֶל בְּנֵי יִשְׂרָאֵל לְדַבְּרָא לוֹן בְּנַחַת כַּדְקָא חֲזֵי, <Nonei></i>וְאֶל פַּרְעֹה: לְאַנְהָגָא בֵּיהּ יְקָר, וְאוּקְמוּהָ.</p>\n<p>אָמַר רִבִּי יֵיסָא, אֲמַאי סָמִיךְ הָכָא (שמות ו׳:י״ד) אֵלֶּה רָאשֵׁי בֵית אֲבוֹתָם. אֶלָּא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דַּבְּרוּ לוֹן לִבְנֵי יִשְׂרָאֵל בְּנַחַת, דְאַף עַל גַּב דְּאִינּוּן יַתְבֵי בְּפוּלְחָנָא קַשְׁיָא, מַלְכִין בְּנִי מַלְכִין אִינּוּן. וּבְגִין כָּךְ, כְּתִיב, אֵלֶּה רָאשֵׁי בֵית אֲבוֹתָם אִלֵּין דְּאַתְּ חָמֵי, רֵישֵׁי בֵּית אֲבָהָן אִינּוּן.</p>\n<p>אָמַר רִבִּי חִיָּיא, דְּכֻלְּהוּ לָא שַׁקְּרוּ נִימוּסֵיהוֹן, וְלָא אִתְעָרְבוּ בְּעַמָּא אַחֲרָא אִלֵּין אִינּוּן דְּקַיְימוּ בְּדוּכְתַּיְיהוּ קַדִּישָׁא, וְלָא שָׁקְרוּ לְאִתְעָרְבָא בְּהוּ בְּמִצְרָאֵי. אָמַר רִבִּי אֲחָא, בְּגִין לְאַיְיתָאָה לְמֹשֶׁה וּלְאַהֲרֹן, דְּאִינּוּן אִתְחָזוּן לְאַפָּקָא לְהוּ לְיִשְׂרָאֵל, וּלְמַלְּלָא לְפַרְעֹה, וּלְרַדָּאָה לֵיהּ בְּחוּטְרָא, בְּגִין דִּבְכָל רֵישֵׁיהוֹן דְּיִשְׂרָאֵל, לָא אִשְׁתְּכַח כְּוָותַיְיהוּ.</p>\n<p>תָּא חֲזֵי, (שמות ו׳:כ״ה) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם. וְכִי אֵלֶּה רָאשֵׁי, וְהָא הוּא בִּלְחוֹדוֹי הֲוָה. אֶלָּא, בְּגִין דְּפִינְחָס קִיֵּים כַּמָּה אַלְפִין וְרִבְוָון מִיִּשְׂרָאֵל, וְהוּא קִיֵּים לְרָאשֵׁי אֲבָהָן, (ליואי) כְּתִיב בֵּיהּ אֵלֶּה.</p>\n<p>תּוּ, וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי, אוֹבְדָא דְּרֵישֵׁי דְּלֵיוָאֵי אִשְׁתְּכַח בֵּיהּ, וּמַה דְּאִינּוּן (ויקרא נ\"ו ע\"ב) גָּרְעוּ וְאִתּוּקָדוּ, הוּא אַשְׁלִים, וְרָוַוח כְּהוּנָתָא דִּילְהוֹן, וְשַׁרְיָא בֵּיהּ טַסְטוּקָא דְּתַרְוַויְיהוּ. אוֹבְדָא דְּרֵישֵׁי דְּלֵיוָאֵי אִשְׁתְּכַח בֵּיהּ, וּמַאן נִינְהוּ. נָדָב וַאֲבִיהוּא. אִינּוּן פְּרִישׁוּ אָת קַיְּימָא מֵאַתְרֵיהּ, וְהוּא אָתָא וְחָבַר לוֹן. בְּגִין כַּךְ, אִתְיְיהִיב לֵיהּ יָרוּתָא, וְרוּחָא דְּתַרְוַויְיהוּ. וְאַדְכַּר הָכָא עַל מַה דְּלֶהוֵי לְבָתַר.</p>\n<p>וְאִי תֵּימָא, אֲמַאי אַדְכַּר הָכָא פִּינְחָס. אֶלָּא חָמָא קוּדְשָׁא בְּרִיךְ הוּא לְאַהֲרֹן, בְּשַׁעֲתָא דְּאָמַר וָאֶזְכּוֹר אֶת בְּרִיתִי, דִּזְמִינִין תְּרֵין בְּנוֹהִי דְּאַהֲרֹן לְאַפְגָּמָא לֵיהּ לְהַאי בְּרִית, וְהַשְׁתָּא דְּקָא מְשַׁדֵּר לֵיהּ לְמִצְרַיִם, בָּעָא לְאַעְבְּרָא לֵיהּ לְאַהֲרֹן, דְּלָא לְמֵיהַךְ בִּשְׁלִיחוּתָא דָּא. כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא, דְּקָאִים פִּינְחָס וְקִיֵּים לֵיהּ לְהַאי בְּרִית בְּאַתְרֵיהּ, וְאַתְקִין עֲקִימָא דִּילְהוֹן, מִיָּד הוּא אַהֲרֹן וּמֹשֶׁה. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, הַשְׁתָּא הוּא אַהֲרֹן, אִיהוּ אַהֲרֹן דְּקַדְמֵיתָא.</p>\n<p>(שמות ו׳:כ״ו) הוּא אַהֲרֹן וּמֹשֶׁה אֲשֶׁר אָמַר ה' לָהֶם הוֹצִיאוּ אֶת בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם וְגוֹ'. הוּא אַהֲרֹן וּמֹשֶׁה. הֵם אַהֲרֹן וּמֹשֶׁה מִבָּעֵי לֵיהּ. אֶלָּא, לְאַכְלָלָא דָּא בְּדָא, רוּחָא בְּמַיָּא. הוּא מֹשֶׁה וְאַהֲרֹן: לְאַכְלָלָא מַיָּא בְּרוּחָא, וְעַל דָּא כְּתִיב הוּא, וְלא הֵם.</p>"],[9520011570,"<p>רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא, הֲווֹ שְׁכִיחֵי לֵילְיָא חַד בְּבֵי אוֹשְׁפִּיזַיְיהוּ בְּלוּד, קָמוּ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי ה' הוּא הָאֱלֹהִים. הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ. וְיָדַעְתָּ הַיּוֹם כִּי ה' הוּא הָאֱלהִים וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ. (אלא זכאה הוא מאן דאשתדל באורייתא) תּוּ, (תא חזי) וְהֲשֵׁבוֹתָ אֶל לִבֶּךָ מִבָּעֵי לֵיהּ.</p>\n<p>אֶלָּא, אָמַר מֹשֶׁה, אִי אַתְּ בָּעֵי לְמֵיקָם עַל דָּא, וּלְמִנְדַּע כִּי ה' הוּא הָאֱלהִים, וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ וּכְדֵין תִּנְדַּע לֵיהּ. לְבָבֶךָ: יֵצֶר טוֹב וְיֵצֶר רָע, דְּאִתְכְּלִיל דָּא בְּדָא, וְאִיהוּ חַד, כְּדֵין תִּשְׁכַּח כִּי ה' הוּא הָאֱלהִים, דְּהָא אִתְכְּלִיל דָּא בְּדָא, וְאִיהוּ חַד. וְעַל דָּא וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ, לְמִנְדַּע מִלָּה.</p>\n<p>תּוּ אָמַר רִבִּי אֶלְעָזָר, חַיָּיבִין, עַבְדִּין פְּגִימוּתָא לְעֵילָּא, מַאי פְּגִימוּתָא. דִּשְׂמָאלָא לָא אִתְכְּלִיל בִּימִינָא. דְּיֵצֶר רָע לָא אִתְכְּלִיל בְּיֵצֶר טוֹב, בְּגִין חוֹבַיְיהוּ דִּבְנֵי נָשָׁא. וּפְגִימוּ לָא עַבְדֵי, אֶלָּא לוֹן מַמָּשׁ, הֲדָא הוּא דִּכְתִּיב, (דברים ל״ב:ה׳) שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. כִּבְיָכוֹל עַבְדֵי וְלָא עַבְדֵי. עַבְדֵי: דְּלָא יִתְמָשֵּׁךְ עָלַיְיהוּ בִּרְכָּאן דִּלְעֵילָּא, כְּמָה דְּאַתְּ אָמַר (דברים י״א:י״ז) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר. וְלָא עַבְדֵי: דְּהָא שְׁמַיָּא נַטְלֵי לוֹן לְגַרְמַיְיהוּ בִּרְכָּאן מַאי דְּאִצְטְרִיךְ. וְלָא נַטְלֵי לְאַמְשָׁכָא לְתַתָּא וַדַּאי מוּמָם דְּאִינּוּן חַיָּיבִין אִיהוּ.</p>\n<p>תּוּ, לוֹ בְּו', דְּלָא אִתְכְּלִיל יְמִינָא בִּשְׂמָאלָא, בְּגִין דְּלָא יִתְמַשְּׁכוּן בִּרְכָּאן לְתַתָּא. לֹא בְּאָלֶ\"ף, דְּהָא לָא נַטְלֵי לְאִתְמַשְּׁכָא לְתַתָּאֵי. מַאן גָּרִים דָּא. בְּגִין דְּחַיָּיבִין מַפְרִישִׁין יֵצֶר רָע מִיֵּצֶר טוֹב, וּמִתְדַּבְּקִין בְּיֵצֶר רָע.</p>\n<p>תָּא חֲזֵי יְהוּדָה אָתֵי <Nonei></i>מִסִּטְרָא דִּשְׂמָאלָא, וְאִתְדְּבַק בִּימִינָא, בְּגִין לְנַצְּחָא עַמִין, (ויחי רמ\"ג ע\"א) וּלְתַבְרָא חֵילֵיהוֹן. דְּאִי לָא אִתְדְּבָק בִּימִינָא, לָא יִתְבַּר חֵילֵיהוֹן. וְאִי תֵּימָא אַמַאי בִּימִינָא. וְהָא שְׂמָאלָא אִתְעַר דִּינִין בְּעָלְמָא.</p>\n<p>אֶלָּא רָזָא דָּא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דָּן לְהוּ לְיִשְׂרָאֵל, לָא דָּן לְהוּ אֶלָּא מִסִּטְרָא דִּשְׂמָאלָא, בְּגִין דִּיְהֵא דָּחֵי לוֹן בִּשְׂמָאלָא, וּמְקָרֵב בִּימִינָא. אֲבָל לִשְׁאַר עַמִּין, דָּחֵי לוֹן בִּימִינָא, וּמְקָרֵב לוֹן בִּשְׂמָאלָא. וְסִימָנִיךְ (שלח לך קפ\"ח ע\"א) גֵּר צֶדֶק, דָּחֵי לוֹן בִּימִינָא, כְּמָה דִּכְתִּיב, (שמות ט״ו:ו׳) יְמִינְךָ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ ה' תִּרְעַץ אוֹיֵב. מְקָרֵב לוֹן בִּשְׂמָאלָא כְּמָה דְּאַמָרָן.</p>\n<p>בְּגִינֵי כַּךְ, יְהוּדָה דְּאִיהוּ מִסְטַר שְׂמָאלָא, אִתְדָּבַּק בִּימִינָא, וּמְטַלְנוֹי לִימִינָא. וְאִינּוּן דְּעִמֵּיהּ אִתְחַבְּרוּ כֻּלְּהוּ לִימִינָא. יִשּׂשׂכָר דְּלָעֵי בְּאוֹרַיְיתָא, דְּאִיהִי יְמִינָא, דִּכְתִּיב, (דברים ל\"ג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. זְבוּלוּן דְּאִיהוּ תָּמִיךְ אוֹרַיְיתָא יְמִינָא, (קע\"ד ע\"ב וישלח קע\"ב) כְּמָה דְאַתְּ אָמֵר שׁוֹק הַיָּמִין. וְעַל דָּא יְהוּדָה אִתְקְשָׁר מִסִּטְרָא דָּא וְדָא. צָפוֹן בַּמַּיִם, שְׂמָאלָא בִּימִינָא.</p>\n<p>רְאוּבֵן דְּחָטָא לְגַבֵּי אֲבוֹי, (פקודי רכ\"ג ע\"א) שָׁרָא בִּימִינָא, וְאִתְקַשַּׁר בִּשְׂמָאלָא, וְאִתְדָבַּק בֵּיהּ. וְעַל דָּא, אִינּוּן דְּאִשְׁתְּכָחוּ עִמֵּיהּ, אִינּוּן שְׂמָאלָא. שִׁמְעוֹן דְּאִיהוּ שְׂמָאלָא מִסִּטְרָא דְּשׁוֹר, דִּכְתִּיב, (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. גָּד שׁוֹקָא שְׂמָאלָא, כְּתִיב (בראשית מ״ט:י״ט) גָּד גְּדוּד יְגוּדֶנּוּ וְהוּא יָגוּד עָקֵב. הָכָא, אִתְדַּבַּק דָּרוֹם בְּאֶשָּׁא, יְמִינָא בִּשְׂמָאלָא.</p>"],[9520011571,"<p>וְעַל דָּא הָא דְּאַמָרָן וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ, (תרומה קס\"ב ע\"ב) לְאַכְלְלָא לוֹן כַּחֲדָא, שְׂמָאלָא בִּימִינָא. כְּדֵין תֵּדַע (דברים ד׳:ל״ה) כִּי ה' הוּא הָאֱלֹהִים. אָמַר רִבִּי אַבָּא וַדַּאי הָכִי הוּא, וְהַשְׁתָּא יְדִיעָא, הוּא אַהֲרֹן וּמֹשֶׁה, הוּא מֹשֶׁה וְאַהֲרֹן, רוּחָא בְּמַיָּא, וּמַיָּא בְּרוּחָא, לְמֶהֱוֵי חַד. וְעַל דָּא כְּתִיב הוּא.</p>\n<p>ר' אַבָּא פָּתַח וְאָמַר, (דבהם ו') וְאָהַבְתָּ אֶת ה' אֱלֹהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ. כְּהַאי גַּוְונָא הָכָא אִתְרְמִיז יִחוּדָא קַדִּישָׁא, וְאַזְהָרָה הוּא לְבַר נָשׁ, לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, בִּרְחִימוּ עִלָּאָה. בְּכָל לְבָבְךָ: דָּא יְמִינָא וּשְׂמָאלָא (נ\"א קדישא) דְּאִקְרֵי יֵצֶר טוֹב וְיֵצֶר רָע. וּבְכָל נַפְשְׁךָ: דָּא נֶפֶשׁ דָּוִד, דְּאִתְיְהִיבַת בֵּינַיְיהוּ. וּבְכָל מְאֹדֶךָ לְאַכְלְלָא לוֹן לְעֵילָּא בַּאֲתָר דְּלֵית בֵּיהּ שִׁעוּרָא. הָכָא הוּא יִחוּדָא שְׁלִים לְמִרְחַם לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יֵאוֹת.</p>\n<p>תּוּ, וּבְכָל מְאֹדֶךָ: דָּא יַעֲקֹב, דְּאִיהוּ אָחִיד לְכָל סִטְרִין, וְכֹלָּא הוּא יִחוּדָא שְׁלִים כְּדְקָא יֵאוֹת, בְּגִינֵי כַּךְ, הוּא אַהֲרֹן וּמֹשֶׁה הוּא מֹשֶׁה וְאַהֲרֹן, כֹּלָּא הוּא חַד בְּלָא פִּרוּדָא.</p>"],[9520011572,"<p>(שמות ז׳:ט׳) כִּי יְדַבֵּר אֲלֵיכֶם פַּרְעֹה לֵאמֹר. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים קי״ט:צ״ז) מָה אָהַבְתִּי תוֹרָתֶךָ כָּל הַיּוֹם הִיא שִׂיחָתִי. וּכְתִיב, (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךָ. תָּא חֲזֵי, דָּוִד אִיהוּ מַלְכָּא דְּיִשְׂרָאֵל, וְאִצְטְרִיךְ לְמֵידָן עַמָּא, לְדַבְּרָא לוֹן לְיִשְׂרָאֵל, כְּרַעְיָא דִּמַדְבַּר עָאנֵיהּ דְּלָא יִסְטוּן מֵאוֹרְחָא דִּקְשׁוֹט. הָא בַּלַּיְלָה כְּתִיב, חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךָ. וְאִיהוּ אִתְעֲסַק בְּאוֹרַיְיתָא וּבְתוּשְׁבְּחָן דְּקוּדְשָׁא בְּרִיךְ הוּא, עַד דְּאָתֵי צַפְרָא.</p>\n<p>וְאִיהוּ אִתְּעַר צַפְרָא, כְּמָה דִּכְתִּיב, (תהילים נ״ז:ט׳) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָׁחָר. כַּד אָתֵי יְמָמָא, אָמַר הַאי קְרָא, מָה אָהַבְתִּי תוֹרָתֶךָ כָּל הַיּוֹם הִיא שִׂיחָתִי. מַאי כָּל הַיּוֹם הִיא שִׂיחָתִי. אֶלָּא, מִכָּאן אוֹלִיפְנָא, דְּכָל מַאן דְּיִשְׁתְּדַל בְּאוֹרַיְיתָא, לְאַשְׁלְמָא דִּינָא עַל בּוּרְיֵיהּ, כְּאִילּוּ קִיֵּים אוֹרַיְיתָא כֹּלָּא. בְּגִין כָּךְ, כָּל הַיּוֹם הִיא שִׂיחָתִי.</p>\n<p>תָּא חֲזֵי, בְּיוֹמָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא, לְאַשְׁלְמָא דִּינִין. בְּלֵילְיָא, אִשְׁתַּדַּל בְּשִׁירִין וְתוּשְׁבְּחָן, עַד דְּאָתֵי יְמָמָא. מַאי טַעְמָא. כָּל יוֹמָא אִתְעֲסַק לְאַשְׁלָמָא דִּינִין, בְּגִין לְאַכְלָלָא שְׂמָאלָא בִּימִינָא. בְּלֵילְיָא, בְּגִין לְאַכְלְלָא דַּרְגָּא דְּלֵילְיָא בִּימָמָא.</p>\n<p>וְתָא חֲזֵי, (תרומה קמ\"ה ע\"א) בְּיוֹמֵי דְּדָוִד מַלְכָּא, הֲוָה מְקָרֵב כָּל אִינּוּן (תהילים ק״ד:י״א) חַיְתוֹ שָׂדָי, לְגַבֵּי יַמָּא. כֵּיוָן דְּאָתָא שְׁלֹמֹה, נָפַק יַמָּא וְאִתְמְלֵי, וְאַשְׁקֵי לְהוּ. הֵי מִנַּיְיהוּ אִתְשַׁקְיָין בְּקַדְמִיתָא. הָא אוּקְמוּהָ. אִלֵּין תַּנִּינַיָיא רַבְרְבִין עִלָּאִין, דִּכְתִּיב בְּהוּ, (בראשית א׳:כ״ב) וּמִלְאוּ אֶת הַמַּיִם בַּיַּמִּים</p>"],[9520011573,"<p>אָמַר רִבִּי <Nonei></i>אֶלְעָזָר, בְּסִטְרָא יְמִינָא עִלָּאָה, נָפְקִין תְּלֵיסָר מַבּוּעִין עִלָּאִין, נָהֲרִין עֲמִיקִין, אִלֵּין סַלְּקִין, וְאִלֵּין נַחְתִּין, עָיִיִל כָּל חַד בְּחַבְרֵיהּ. חַד אַפִּיק רֵישֵׁיהּ, וְאָעִיל לֵיהּ בִּתְרֵין גּוּפִין, חַד גּוּפָא דְּנַהֲרָא נָטִיל מִיָּמִין לְעֵילָּא, אַפְרִישׁ לְתַתָּא אֶלֶף יְאוֹרִין, נָפְקִין לְאַרְבַּע סִטְרִין.</p>\n<p>מֵאִינּוּן נַהֲרִין מַבּוּעִין תְּלֵיסָר, מִתְפָּרְשָׁן תְּלֵיסַר יְאוֹרִין, עָאלִין וְנַטְלֵי מַיָּא, אַרְבַּע מֵאָה וְתִשְׁעִין וְתִשְׁעָה יְאוֹרִין וּפַלְגָּא, מִסִּטְרָא דָּא. וְאַרְבַּע מְאָה וְתִשְׁעִין וְתִשְׁעָה יְאוֹרִין וּפַלְגָּא, מִסִּטְרָא דָּא בִּשְׂמָאלָא. אִשְׁתְּאַר פַּלְגָּא מִכָּאן, וּפַלְגָּא מִכָּאן, וְאִתְעָבִיד חַד. דָּא אָעִיל בֵּין יְאוֹרִין, וְאִתְעָבִיד חִוְיָא.</p>\n<p>רֵישָׁא: סוּמָקָא כְּוַרְדָּא. קַשְׁקַשׁוֹי: תַּקִּיפִין כְּפַרְזְלָא. גַּדְפּוֹי: גַּדְפִּין שָׁטָאן וְאִתְפָּרְשָׁן לְכָל אִינּוּן יְאוֹרִין. כַּד סָלִיק זַנְבֵּיהּ, (נ\"א לגביה) מָחֵי וּבָטַשׁ לִשְׁאַר נוּנִין, לֵית מַאן דְּיֵקוּם קָמֵיהּ.</p>\n<p>פּוּמֵיהּ: מְלַהֲטָא אֶשָּׁא. כַּד נָטִיל בְּכָל אִינּוּן יְאוֹרִין, מִזְדַּעְזְעָן שְׁאַר תַּנִּינַיָיא, וְעַרְקִין וְעָאלִין בְּיַמָּא. חַד לְשִׁבְעִין שְׁנִין רָבִיץ לְסִטְרָא דָּא. וְחַד לְשִׁבְעִין שְׁנִין רָבִיץ לְסִטְרָא דָּא. אֶלֶף יְאוֹרִין חָסֵר חַד אִתְמַלְיָין מִנֵּיהּ. דָּא תַּנִּינָא, רָבִיץ בֵּין אִינּוּן יְאוֹרִין.</p>\n<p>כַּד נָטִיל נָפִק חַד פָּסוּתָא דְּאֶשָּׁא בִּקְלִיפִין, כֻּלְּהוּ קַיְימִין וְזַעְפִּין בְּזַעְפּוֹי, (נ\"א וזקפין בענפוי) מִתְעָרְבִין אִינּוּן יְאוֹרִין לְעֵין (נ\"א העין) תִּכְלָא אוּכָמָא. וְגַלְגְּלִין נַטְלִין לְאַרְבַּע סִטְרֵי דְּעָלְמָא. זָקִיף זַנְבֵּיהּ, מָחֵי לְעֵילָּא, מָחֵי לְתַתָּא, כֹּלָּא עַרְקִין קָמֵיהּ.</p>\n<p>עַד דְּלִסְטַר צָפוֹן, קָם חַד שַׁלְהוֹבָא דְּאֶשָּׁא, וְכָרוֹזָא קָרֵי, אִזְדָּקָפוּ סַבְתִּין אִתְבְּדָרוּ לְד' זָוְיָין, הָא אִתְּעַר מַאן דְּשַׁוֵּי קֳדְלַא, עַל אַנְפּוֹי דְּתַנִּינָא, כְּמָה דְּאִתְּמַר, (יחזקאל כ״ט:ד׳) וְנָתַתִּי חַחִים בִּלְחָיֶּיךָ וְגוֹ'. כְּדֵין כֻּלְּהוּ אִתְבַּדְּרוּן. וְנַקְטִין לֵיהּ לְתַנִינָא, וְנָקְבֵי אַנְפּוֹי בִּסְטַר עִלְעוֹי, וְעָאלִין לֵיהּ לְנוּקְבָּא דִּתְהוֹמָא רַבָּא, עַד דְּאִתְבַּר חֵילֵיהּ, כְּדֵין אֲהַדְרוּ לֵיהּ לְנַהֲרוֹי. (נ\"א לנחרוי)</p>\n<p>חַד לְשִׁבְעִין שְׁנִין עַבְדִין לֵיהּ כְּדֵין, בְּגִין דְּלָא יְטַשְׁטֵשׁ אַתְרִין דִּרְקִיעִין וּסְמָכַיְיהוּ. וְעָלַיְיהוּ כֹּלָּא אוֹדָן, וּמְבָרְכָאן וְאַמְרִין, (תהילים צ״ה:ו׳) בּוֹאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה נִבְרְכָה לִפְנֵי ה' עוֹשֵׂנוּ.</p>\n<p>תַּנִּינַיָיא עִלָּאִין אִילֵין (ס\"א לעילא) קַיְימִין אִינּוּן דְּמִתְבָּרְכָאן, כְּמָה דְאַתְּ אָמֵר (בראשית א׳:כ״ב) וַיְבָרֶךְ אוֹתָם אֱלהִים. אִלֵּין שַׁלְטִין עַל כָּל שְׁאַר נוּנִין, דִּכְתִּיב וּמִלְאוּ אֶת הַמַּיִם בַּיַּמִּים. וְעַל דָּא כְּתִיב, (תהילים ק״ד:כ״ד) מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9520011574,"<p><Noneb>תוספתא</b> (שיר השירים א׳:י״ד) אֶשְׁכּוֹל הַכּוֹפֶר דּוֹדִי לִי. אֶשְׁכּוֹל: דָּא אִימָּא עִלָּאָה. מַה אֶשְׁכּוֹל מִתְקַשֵּׁט בְּכַמָּה עָלִין בְּכַמָּה זְמוֹרוֹת לְיִשְׂרָאֵל דְּאַכְלִין לֵיהּ, הָכִי שְׁכִינְתָּא עִלָּאָה, מִתְקַשֶּׁטֶת בְּכַמָּה קִשּׁוּטִין דִּשְׁמֹנָה כֵּלִים, מִכַּמָּה קָרְבָּנִין, מִכַּמָּה מִינֵי תַּכְשִׁיטִין דְּכַפְּרָה לִבְנָהָא, וְאִיהִי קָמַת בְּהוֹן קָמֵי מַלְכָּא, וּמִיַּד (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. וִיהִיבַת (ס\"א לון שאלתין דלהון) לָן שְׁאֶילְתִּין דִּילָהּ, בְּאִלֵּין בִּרְכָּאן דְּתָקִינוּ רַבָּנָן בִּצְלוֹתָא, לְמִשְׁאַל קַמֵי מַלְכָּא.</p>\n<p>בְּהַהוּא זִמְנָא, כָּל דִּינִין דִּשְׁכִינְתָּא תַּתָּאָה, דְּאִיהִי הוה\"י אֲדֹנָ\"י, מִתְהַפְּכָן לְרַחֲמֵי, כְּגַוְונָא דָּא ידו\"ד, לְקַיֵּים (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ, ידו\"ד. אִם יַאְדִּימוּ כַתּוֹלָע. דוד\"י. כַּצֶּמֶר יִהְיוּ, ידו\"ד. כָּל דִּינִין (נ\"א כל דינין דדא') מִתְלַבְּנִין מִשְׁכִינְתָּא עִלָּאָה.</p>\n<p>וְאִיהִי שְׁכִינְתָּא דוד\"י, (בראשית ג׳:כ״ד) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. וְאוּקְמוּהָ רַבָּנָן, דִּמְהַפְּכָא זִמְנִין רַחֲמֵי, זִמְנִין דִּינָא פְּעָמִים אֲנָשִׁים, פְּעָמִים נָשִׁים. זִמְנִין דִּינָא, כְּגַוְונָא דָּא דוד\"י. זִמְנִין רַחֲמֵי, כְּגַוְונָא דָּא ידו\"ד. דְּהָא אִיהוּ מִסִּטְרָא דְּאִילָנָא דְּחַיֵּי, כָּל דִּינִין מִתְהַפְּכִין לְרַחֲמֵי. וּמִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע, כָּל רַחֲמֵי מִתְהַפְּכָן לְדִינָא, לְמֵידָן בְּהוּ לְאִינוּן דְּעַבְרֵי עַל פִּתְגָּמֵי אוֹרַיְיתָא.</p>\n<p>וְעֵץ דָּא בְּעָלְמָא דְּאָתֵי, דְּאִיהוּ בִּינָה, כָּל שְׁמָהָן דְּדִינָא מִתְהַפְּכִין בָּהּ (לדינא) רַחֲמֵי, בְּגִין דָּא אוּקְמוּהָ רַבָּנָן, לא כְּהָעוֹלָם הַזֶּה הָעוֹלָם הַבָּא. וּבְגִין דָּא, בִּינָה, אִיהִי לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, דְּמִתְהַפֶּכֶת מִדִּינָא לְרַחֲמֵי לַצַדִּיקִים, לְמֵיהַב לוֹן אַגְרָא בְּעָלְמָא דְּאָתֵי. מַלְכוּת, לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מֵרַחֲמֵי לְדִינָא, לְמֵידָן בָּהּ לְרַשִׁיעַיָּיא <Nonei></i>בְּעָלְמָא דֵּין.</p>\n<p>אֲבָל מֵעֵץ הַדַּעַת טוֹב וָרָע, דְּאִיהוּ כְּגַוְונָא דְּמַטֶּה, זִמְנִין דְּמִתְהַפְּכִין הַנָּשִׁים לְשֵׁדוֹת, אֲנָשִׁים לְשֵׁדִים. וּבְגִין דָּא, (בראשית כ״ט:י״ב) וַיַּגֵּד יַעֲקֹב לְרָחֵל. וּבְגִין דָּא, אוּקְמוּהָ רַבָּנָן, דְּלֵית לֵיהּ לְבַר נָשׁ לְשַׁמְּשָׁא עִם אִתְּתֵיהּ, עַד דִּמְסַפֵּר עִמָּהּ, שֶׁמָּא נִתְחַלְּפָה לוֹ בְּשֵׁידָה. בְּגִין דְּלַהַט בְּעֵץ הַדַּעַת טוֹב וָרָע, מִתְהַפֶּכֶת מִטּוֹב לָרָע, וְאִי תֵּימָא דִּמְכַשְּׁפֵי פַּרְעֹה, דִּכְתִּיב וַיַּעֲשׂוּ כֵן הַחַרְטוּמִּים בְּלָטֵיהֶם. הֲווֹ מְהַפְּכִין אִינּוּן מַטוֹת דִּלְהוֹן לִנְחָשִׁין. וּמִסִּטְרָא דְּאִלֵּין הִפּוּכָן יַכְלִין לְאִתְהַפְּכָא. (ע\"כ תוספתא).</p>"],[9520011575,"<p>(שמות ז׳:ט׳) וְאָמַרְתָּ אֶל אַהֲרֹן קַח אֶת מַטְּךָ. מַאי טַעֲמָא מַטֵּה אַהֲרֹן, וְלא מַטֵּה מֹשֶׁה. אֶלָּא, הַהוּא דְּמֹשֶׁה אִיהוּ קַדִּישָׁא יַתִּיר, דְּאִתְגְּלִיף בְּגִנְתָּא עִלָּאָה בִּשְׁמָא קַדִּישָׁא, וְלָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְסָאֳבָא לֵיהּ בְּאִינּוּן חוּטְרִין דְּחַרְשַׁיָּא. וְלֹא עוֹד, אֶלָּא לְאַכְפְּיָיא לוֹן לְכָל אִינּוּן דְּאַתְיָין מִסִּטְרָא דִּשְׂמָאלָא, בְּגִין דְּאַהֲרֹן אָתָא מִימִינָא, וּשְׂמָאלָא אִתְכַּפְיָיא בִּימִינָא.</p>\n<p>רִבִּי חִיָּיא שָׁאִיל לְרִבִּי יוֹסֵי, הָא גַּלֵּי קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּאִינּוּן חֲרָשִׁין יַעַבְדוּן תַּנִּינַיָיא, מַאי גְּבוּרְתָּא אִיהוּ לְמֶעְבַּד קָמֵי פַּרְעֹה תַּנִּינַיָיא. אֲמַר לֵיהּ, בְּגִין דְּמִתַּמָּן הוּא שֵׁירוּתָא לְאַלְקָאָה, וּמִשֵּׁירוּתָא דְּתַנִּינָא שָׁאַרִי שׁוּלְטָנֵיהּ, (נ\"א לשולניה ומשירותא דשולטניה שרי לאלקאה) כְּדֵין, חֲדוּ כּוּלְּהוּ חֲרָשֵׁי, דְּהָא רֵישׁ חָכְמְתָא דְּנָחָשׁ דִּילְהוֹן הָכִי הֲוָה. מִיָּד אִתְהַדַּר הַהוּא תַּנִּינָא דְּאַהֲרֹן לְאָעָא יְבֵישָׁא, וּבָלַע לוֹן.</p>\n<p>וְעַל דָּא תַּוְוהוּ, וְיָדְעוּ דְּשׁוּלְטָנָא עִלָּאָה אִית בְּאַרְעָא, דְּאִינּוּן חֲשִׁיבוּ, דְּהָא לְתַתָּא, (נ\"א לעילא) בַּר מִנַּיְיהוּ לָא אִית שֻׁלְטָנָא לְמֶעְבַּד מִידִי, כְּדֵין, וַיִּבְלַע מַטֵּה אַהֲרֹן, מַטֵּה אַהֲרֹן דַּיְיקָא, דְּאִתְהַדַּר לְאָעָא וּבָלַע לוֹן.</p>\n<p>וְעַל דָּא עָבֵד אַהֲרֹן תְּרֵין אָתִין, חַד לְעֵילָּא, וְחַד לְתַתָּא. חַד לְעֵילָּא, תַּנִּינָא עִלָּאָה דְּשַׁלְטָא עַל אִינּוּן דִּלְהוֹן. חַד לְתַתָּא, דְּשָׁלִיט אָעָא עַל תַּנִּינָא דִּילְהוֹן. וּפַרְעֹה חַכִּים הֲוָה מִכָּל חֲרָשׁוֹי, וְאִסְתַּכַּל דְּשֻׁלְטָנָא עִלָּאָה שָׁלִיט עַל אַרְעָא, שָׁלִיט לְעֵילָּא שָׁלִיט לְתַתָּא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, אִי תֵּימָא, חָרָשַׁיָּא כָּל מַה דְּעַבְדִין לָאו אִיהוּ אֶלָּא בְּחֵיזוּ דְּעֵינָא, דְּהָכִי אִתְחָזֵי, וְלָא יַתִּיר, קָא מַשְׁמַע לָן וַיִּהְיוּ דַּיְיקָא, דִּכְתִּיב וַיִּהְיוּ לְתַנִּינִים. וְאָמַר רִבִּי יוֹסֵי, אֲפִילּוּ אִינּוּן תַּנִּינַיָא דִּילְהוֹן אֲהַדְרוּ לְמֶהוֵי אָעִין, וְאָעָא דְּאַהֲרֹן בָּלַע לוֹן.</p>\n<p>כְּתִיב, (יחזקאל כ״ט:ג׳) הִנְנִי עָלֶיךָ פַּרְעֹה מֶלֶךְ מִצְרַיִם הַתַּנִּים הַגָּדוֹל הָרוֹבֵץ בְּתוֹךְ יְאוֹרָיו. מִתַּמָּן שֵׁרוּתָא לְתַתָּא בְּשׁוּלְטָנָא דִּילְהוֹן. אֲבָל חָכְמְתָא דִּילְהוֹן, לְתַתָּא מִכֻּלְּהוּ דַּרְגִּין אִיהוּ. (אינון)</p>\n<p>תָּא חֲזֵי, חָכְמְתָא דִּילְהוֹן בְּדַרְגִּין תַּתָּאִין, לְאַכְפְיָין לוֹן לְאִלֵּין דַּרְגִּין בְּדַרְגִּין עִלָּאִין, רֵישֵׁי שׁוּלְטָנוּתְהוֹן וְעִקָרָא דִּילְהוֹן, לְתַתָּא מֵהַהוּא תַּנִּינָא, וּמִשְׁתַּלְשְׁלָן בְּתַנִּינָא, דְּהָא מִתַּמָּן נָטִיל חֵילָא דַּרְגָּא עִלָּאָה דִּילְהוֹן. מַשְׁמַע דִּכְתִּיב, (שמות י\"א) אֲשֶׁר אַחַר הָרֵחָיִם.</p>\n<p>רִבִּי חִיָּיא, הֲוָה יָתִיב יוֹמָא חֲדָא, אֲבָבָא דְּתַרְעָא דְּאוּשָׁא. חָמָא לֵיהּ לְרִבִּי אֶלְעָזָר חָד קַטְפִירָא טָאסָא גַּבֵּיהּ, אָמַר לֵיהּ לְרִבִּי אֶלְעָזָר, מַשְׁמַע, דְּאֲפִילּוּ בְּאוֹרְחָךְ כֹּלָּא תְּאִיבִין לִמֵהַךְ אֲבַתְרָךְ. אַהְדָּר רֵישָׁא וְחָמָא לֵיהּ. אָמַר, וַדַּאי שְׁלִיחוּתָא אִית גַּבֵּיהּ. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בְּכֹלָּא עָבִיד שְׁלִיחוּתֵיהּ, וְכַמָה שְׁלִיחִין אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא תֵּימָא מִלִּין דְּאִית בְּהוּ רוּחָא בִּלְחוֹדַיְיהוּ, אֶלָּא אֲפִילּוּ אִינּוּן מִלִּין דְּלֵית בְּהוּ רוּחָא.</p>\n<p>פָּתַח וְאָמַר, (חבקוק ב׳:י״א) כִּי אֶבֶן מִקִּיר תִּזְעָק וְכָפִיס מֵעֵץ יַעֲנֶנָּה. כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מֵחוֹבוֹי, דְּלָא יֶחטָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְאִי יֵימָא מַאן יַסְהִיד בֵּיהּ. הָא אַבְנִי בֵּיתֵיהּ וְאָעֵי בֵּיתֵיהּ יַסְהִידוּ בֵּיהּ. וּלְזִמְנִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד בְּהוּ שְׁלִיחוּתָא. תָּא חֲזֵי חוּטְרָא דְּאַהֲרֹן, דְּאִיהוּ אָעָא יְבֵישָׁא, קוּדְשָׁא בְּרִיךְ הוּא שֵׁירוּתָא דְּנִסִּין עָבֵד בֵּיהּ, וּתְרֵי שְׁלִיחוּתֵי בֵּיהּ אִתְעָבִידוּ. חַד דְּאִיהוּ אָעָא יְבֵישָׁא וּבָלַע לְאִינוּן תַּנִּינַיָיא דִּילְהוֹן. וְחַד דְּהָא לְשַׁעֲתָא אִתְהַדַּר בְּרוּחָא וְאִתְעָבִיד בִּרְיָה.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, תִּפַּח <Nonei></i>רוּחֵיהוֹן, דְּאִינּוּן דְּאַמְרִין, דְּלָא זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲיָיא מֵתַיָּיא, וְהֵיךְ יִתְעֲבִיד מִנַּיְיהוּ בִּרְיָה חַדְתָּא. יֵיתוּן וְיֶחמוּן אִינּוּן טִפְּשָׁאִין חַיָּיבַיָּא, רְחִיקִין מֵאוֹרַיְיתָא, רְחִיקִין מִנֵּיהּ, בִּידֵיהּ דְּאַהֲרֹן הֲוָה חוּטְרָא, אָעָא יְבֵישָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא לְפוּם שַׁעֲתָא אַהְדָּר לֵיהּ בִּרְיָה, מְשַׁנְיָא בְּרוּחָא וְגוּפָא. אִינּוּן גּוּפִין, דַּהֲווֹ בְּהוּ רוּחִין וְנִשְׁמָתִין קַדִּישִׁין, וְנָטְרוּ פִּקּוּדֵי אוֹרַיְיתָא, וְאִשְׁתַּדָּלוּ בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, וְקוּדְשָׁא בְּרִיךְ הוּא טָמִיר לוֹן בְּעַפְרָא. לְבָתַר, בְּזִמְנָא דִּיחֲדֵי עָלְמָא, עַל אַחַת כַּמָּה וְכַמָּה דְּיַעֲבִד לְהוּ בִּרְיָה חַדְתָּא.</p>\n<p>אָמַר רִבִּי חִיָּיא, וְלֹא עוֹד, אֶלָּא דְּהַהוּא גּוּפָא דְּהֲוָה, יָקוּם. מַשְׁמַע דִּכְתִּיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, וְלָא כְּתִיב יִבְרָא, מַשְׁמַע דְּבִרְיָין אִינּוּן אֲבָל יִחְיוּ. דְּהָא (בראשית קל\"ז ע\"ב) גַּרְמָא חַד, יִשְׁתְּאַר מִן גּוּפָא תְּחוֹת אַרְעָא, וְהַהוּא לָא אִתְרְקַב וְלָא אִתְבְּלֵי בְּעַפְרָא לְעָלְמִין, וּבְהַהוּא זִמְנָא, קוּדְשָׁא בְּרִיךְ הוּא יֵרַכֵּךְ לֵיהּ, וְיַעְבִיד לֵיהּ כַּחֲמִירָא בְּעִיסָה, וְיִסְתְּלַק וְיִתְפְּשַׁט לְאַרְבַּע זָוְיָין וּמִנֵּיהּ יִשְׁתַּכְלַל גּוּפָא וְכָל שַׁיְיפוֹי. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב בֵּיהּ רוּחָא לְבָתַר. אָמַר לֵיהּ רִבִּי אֶלְעָזָר הָכִי הוּא. וְתָא חֲזֵי, הַהוּא גַּרְמָא בְּמָה אִתְרְכַךְ. בַּטָּל. דִּכְתִּיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ וְגוֹ'.</p>"],[9520011576,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה אֱמוֹר אֶל אַהֲרֹן קַח מַטְּךָ וּנְטֵה יָדְךָ עַל מֵימֵי מִצְרַיִם עַל נַהֲרוֹתָם עַל יְאוֹרֵיהֶם וְעַל אֲגְמֵיהֶם וְעַל כָּל מִקְוֵה מֵימֵיהֶם וַיִּהְיוּ דָּם וְגוֹ'. אָמַר רִבִּי יְהוּדָה, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, וְהֵיךְ יָכִיל לְמֵהַךְ לְכָל הָנֵי אַתְרֵי. (ולא עוד אלא) וְתוּ, דְּהָא כְּתִיב וְיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת ה' אֶת הַיְאוֹר. אֶת הַיְאוֹר כְּתִיב, וְאַתְּ אָמַרְתְּ עַל מֵימֵי מִצְרַיִם עַל נַהֲרוֹתָם עַל יְאוֹרֵיהֶם וְעַל אֲגְמֵיהֶם.</p>\n<p>אֶלָּא, מֵימֵי מִצְרַיִם נִילוּס הֲוָה. וּמִתַּמָּן אִתְמַלְיָין כָּל אִינּוּן שְׁאַר אֲגַמִּין וִיאוֹרִין וּמַבּוּעִין וְכָל מֵימִין דִּילְהוֹן. וְעַל דָּא, אַהֲרֹן לֹא נָטָה לְמַחֲאָה אֶלָּא לְנִילוּס בִּלְחוֹדוֹי. וְתָא חֲזֵי דְּהָכִי הוּא, דִּכְתִּיב וְלא יָכְלוּ מִצְרַיִם לִשְׁתּוֹת מַיִם מִן הַיְאוֹר.</p>\n<p>אָמַר רִבִּי אַבָּא, תָּא חֲזֵי, מַיִין תַּתָּאִין מִתְפָּרְשָׁאן לְכַמָּה סִטְרִין, (נ\"א ומיין עלאי ע\"כ וגו') (עלאין דהא) וּמַיִין עִלָּאִין מִתְכַּנְשֵׁי בְּבֵי כְּנִישׁוּ מַיָּא, דִּכְתִּיב, (בראשית א׳:ט׳) וַיֹּאמֶר אֱלהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. וּכְתִיב וּלְמִקְּוֵה הַמַּיִם קָרָא יַמִּים. הַאי קְרָא אוּקְמוּהָ. וְתָא חֲזֵי, הַהוּא רְקִיעָא דְּאִית בֵּיהּ שִׁמְשָׁא וְסִיהֲרָא כּוֹכָבַיָיא וּמַזָּלֵי, דָּא אִיהוּ בֵּי כְּנִישׁוּת מַיָּא רַבָּא, דְּהוּא נָטִיל כָּל מַיִין, וְאַשְׁקֵי לְאַרְעָא, דְּהִיא עָלְמָא תַּתָּאָה, כֵּיוָן, דְּנָטַל מַיָּא בָּדַר לוֹן, וּפָלִיג לוֹן לְכָל עִיבָר, וּמִתַּמָּן אִתְשַׁקְיָין כֹּלָּא.</p>\n<p>וּבְזִמְנָא דְּדִינָא שַׁרְיָא, עָלְמָא תַּתָּאָה לָא יַנְקָא מִן הַהוּא רְקִיעָא, וְיַנְקָא מִסְּטַר שְׂמָאלָא, וּכְדֵין אִקְרֵי (ישעיהו ל״ד:ו׳) חֶרֶב לַה' מָלְאָה דָּם. וַוי לְאִינוּן דְּיַנְקִין כְּדֵין מִינָהּ, וְאִתְשַׁקְיָין מִינָהּ, דִּבְהַהוּא זִמְנָא יַמָּא יַנְקָא מִתְּרֵין סִטְרִין, הֲוָה אִתְפְּלַג לִתְרֵין חוּלָקִין, חִוָּור וְסוּמָק. וּכְדֵין שָׁדֵי לִיאוֹרָא חוּלָקָא דְּמִצְרַיִם, וְאַלְקֵי לְעֵילָּא וְאַלְקֵי לְתַתָּא. וְעַל דָּא שָׁתָאן יִשְׂרָאֵל מַיָּא. וּמִצְרָאֵי דָּמָא.</p>\n<p>אִי תֵּימָא בְּגִין גִּיעוּלָא הֲוָה וְלָא יַתִּיר. תָּא חֲזֵי, שָׁתָאן דָּמָא וְעָאל לְמֵעַיְיהוּ, וְאִסְתַּלָּק וּבָקַע, עַד דַּהֲווֹ מְזַבְּנִין לוֹן יִשְׂרָאֵל מַיָּא בְּמָמוֹנָא, וּכְדֵין שָׁתָאן מַיָּא בְּגִינִי כַּךְ שֵׁירוּתָא לְאַלְקָאָה לוֹן הֲוָה דָּמָא.</p>\n<p>רִבִּי יִצְחָק פָּתַח הַאי קְרָא, (תהילים קמ״ה:א׳) אֲרוֹמִמְךָ אֱלֹהַי הַמֶּלֶךְ וַאֲבָרְכָה שִׁמְךָ לְעוֹלָם וָעֶד. תָּא חֲזֵי, דָּוִד לָקֳבֵיל דַּרְגָּא דֵּילֵיהּ קָאָמַר, דִּכְתִּיב אֱלהַי דִּידִי. בְּגִין דְּבָעָא לְסַלְּקָא שְׁבָחֵיהּ, וּלְאַעֲלָא לֵיהּ לִנְהוֹרָא עִלָּאָה, לְאִתְעָרְבָא דָּא בְּדָא, לְמֶהֱוֵי כֹּלָּא חַד. בְּגִינֵי כַּךְ, אֲרוֹמִמְךָ אֱלהַי הַמֶּלֶךְ וְגוֹ'.</p>\n<p>דְּתָנֵינָן, כָּל יוֹמוֹי דְּדָוִד, אִשְׁתַּדַּל לְאַתְקְנָא כּוּרְסְיָה, וּלְאַנְהָרָא אַנְפָּהָא, בְּגִין דְּיָגִין עָלֵיהּ וְאִיתְנְהִיר תָּדִיר נְהוֹרָא תַּתָּאָה <Nonei></i>בִּנְהוֹרָא עִלָּאָה, לְמֶהוֵי כֹּלָּא חַד. וְכַד אָתָא שְׁלֹמֹה, אַשְׁכַּח עָלְמָא שְׁלִים, וְסִיהֲרָא דְּאִתְמַלְיָא, וְלָא אִצְטְרִיךְ לְאַטְרְחָא עָלָּה לְאַנְהָרָא. (ע\"כ)</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמֵיסָב נוּקְמִין מֵעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, אִתְּעַר שְׂמָאלָא, וְאִתְמַלְיָא סִיהֲרָא מֵהַהוּא סִטְרָא דָּמָא. וּכְדֵין, נַבְעִין מַבּוּעִין וּנְחָלִין דִּלְתַתָּא, כָּל אִינּוּן דְּלִסְטַר שְׂמָאלָא דָּמָא. וְעַל דָּא, דִּינָא דִּילְהוֹן דָּמָא.</p>\n<p>תָּא חֲזֵי, כַּד הַאי דָּמָא אִתְּעַר (נ\"א כד דינא אתער על עלמא בגין ההוא דמא דקטולין קודשא בריך הוא אתער) עַל עַמָּא, הַהוּא דָּמָא דְּקָטוּלִין אִיהוּ דְּיִתְּעַר עָלַיְיהוּ עַמָּא אַחֲרָא וְקָטִיל לוֹן. אֲבָל (השתא) בְּמִצְרַיִם, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַיְיתָאָה עָלַיְיהוּ עַמָּא אַחֲרָא לְאַתְעֲרָא עָלַיְיהוּ דָּמָא בְּגִין דְּיִשְׂרָאֵל הֲווֹ בֵּינַיְיהוּ, וְלָא יִצְטַעֲרוּן בְּגִין דְּדַיְירִין בְּאַרְעָא דִּילְהוֹן, אֲבָל קוּדְשָׁא בְּרִיךְ הוּא מָחָא לוֹן בְּדָמָא, בְּנַהֲרִין דִּלְהוֹן, דְּלָא הֲווֹ יַכְלִין לְמִשְׁתֵּי.</p>\n<p>וּבְגִין דְּשׁוּלְטָנוּתָא דִּלְהוֹן, שַׁלְטָא בְּהַהוּא נַהֲרָא, פָּקִיד קוּדְשָׁא בְּרִיךְ הוּא לְשׁוּלְטָנוּתָא דִּלְהוֹן בְּקַדְמִיתָא, בְּגִין דְּיַלְקֵי דַּחֲלָא דִּלְהוֹן בְּקַדְמִיתָא, בְּגִין דְּנִילוּס חַד דַּחֲלָא דִּלְהוֹן הֲוָה, וְכֵן שְׁאַר דַּחֲלִין דִּלְהוֹן נַבְעִין דָּמָא. הֲדָא הוּא דִכְתִיב וְהָיָה דָם בְּכָל אֶרֶץ מִצְרַיִם וּבָעֵצִים וּבָאֲבָנִים.</p>\n<p>ר' חִיָּיא קַם לֵילְיָא חַד לְמִלְעֵי בְּאוֹרַיְיתָא, וַהֲוָה עִמֵּיהּ ר' יוֹסֵי זוּטָא, דְּהֲוָה רַבְיָא. פָּתַח ר' חִיָּיא וְאָמַר, (קהלת ט׳:ז׳) לֵךְ אֱכוֹל בְּשִׂמְחָה לַחְמֶךָ וּשְׁתֵה בְלֶב טוֹב יִיִנֶךָ כִּי כְבָר רָצָה הָאֱלהִים אֶת מַעֲשֶׂיךָ. מַאי קָא חָמָא שְׁלמֹה דְּאָמַר הַאי קְרָא.</p>\n<p>אֶלָּא שְׁלֹמֹה כָּל מִלּוֹי בְּחָכְמָה הֲווֹ, וְהַאי דְּאָמַר לֵךְ אֱכוֹל בְּשִׂמְחָה לַחְמֶךָ, בְּשַׁעֲתָא דְּבַר נָשׁ אָזִיל בְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא מְקָרֵב לֵיהּ לְגַבֵּיהּ, וְיָהִיב לֵיהּ שַׁלְוָה וְנַיְיחָא, כְּדֵין נַהֲמָא וְחַמְרָא דְּאָכִיל וְשָתֵי, בְּחֶדְוָה דְּלִבָּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּעוֹבָדוֹי.</p>\n<p>אֲמַר לֵיהּ הַהוּא רַבְיָא, אִי הָכִי, הָא אָמַרְתְּ דְּכָל מִלּוֹי דְּשְׁלֹמֹה בֶּחָכְמְתָא הֲווֹ, אָן הוּא חָכְמְתָא הָכָא. אֲמַר לֵיהּ בְּרִי תְּבַשֵּׁל בִּשּׁוּלָךְ, וְתֶחֱמֵי הַאי קְרָא. אֲמַר לֵיהּ עַד לָא בָּשִׁילְנָא יָדַעְנָא. אֲמַר לֵיהּ מְנָא לָן.</p>\n<p>אֲמַר לֵיהּ קָלָא חַד שְׁמַעְנָא מֵאַבָּא, דְּהֲוָה אָמַר בְּהַאי קְרָא, דְּשְׁלֹמֹה קָא אַזְהַר לֵיהּ לְבַּר נָשׁ, לְאַעְטְּרָא לָהּ לכְנֶסֶת יִשְׂרָאֵל בְּשִׂמְחָה, דְּאִיהוּ סִטְרָא דִּימִינָא, וְאִיהוּ נָהֲמָא, דְּיִתְעֲטָּר בְּחֶדְוָה. וּלְבָתַר, יִתְעֲטָּר בְּחַמְרָא, דְּאִיהוּ שְׂמָאלָא, בְּגִין דְּתִשְׁתְּכַח בִּמְהֵימָנוּתָא דְּכֹלָּא, חֶדְוָותָא שְׁלֵימָתָא, בִּימִינָא וּשְׂמָאלָא, וְכַד תֶּהוֵי בֵּין תַּרְוַויְיהוּ כְּדֵין כָּל בִּרְכָּאן שָׁרָאן בְּעָלְמָא. וְכָל דָּא, כַּד אִתְרְעֵי קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, הֲדָא הוּא דִכְתִיב כִּי כְבָר רָצָה הָאֱלֹהִים אֶת מַעֲשֶׂיךָ. אָתָא ר' חִיָּיא וּנְשָׁקֵיהּ, אָמַר, חַיֶּיךָ בְּרִי הַאי מִלָּה שָׁבַקְנָא בְּגִינָךְ, וְהַשְׁתָּא יָדַעְנָא, דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַעְטְּרָא לָךְ בְּאוֹרַיְיתָא.</p>\n<p>תּוּ פָּתַח ר' חִיָּיא וְאָמַר, אֱמוֹר אֶל אַהֲרֹן קַח מַטְּךָ וּנְטֵה יָדְךָ עַל מֵימֵי מִצְרַיִם. מַאי טַעְמָא אַהֲרֹן וְלא מֹשֶׁה. אֶלָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַהֲרֹן מַיִין קַיְימִין בְּדוּכְתֵּיהּ, וּשְׂמָאלָא בָּעֵי לְנַגְדָּא מַיִין מִתַּמָּן, אַהֲרֹן דְּאָתֵי מֵהַהוּא סִטְרָא יִתְּעַר לֵיהּ, וְכַד שְׂמָאלָא נָקִיט לוֹן, אִינּוּן יִתְהַדְּרוּן דָּמָא.</p>\n<p>תָּא חֲזֵי תַּתָּאָה דְּכָל דַּרְגִּין מָחָא בְּקַדְמִיתָא. אָמַר רַבִּי שִׁמְעוֹן מִתַּתָּאָה שָׁרָא קוּדְשָׁא בְּרִיךְ הוּא. וְיַדָא דִּילֵיהּ, מָחָא בְּכָל אֶצְבְּעָא וְאֶצְבְּעָא. וְכַד מָטָא לְדַרְגָּא עִלָּאָה דְּכָל דַּרְגִּין, עָבֵד אִיהוּ דִּילֵיהּ, וְעָבַר בְּאַרְעָא דְּמִצְרַיִם, וְקָטַל כֹּלָּא. וּבְגִינֵי כַּךְ קָטַל כָּל בּוּכְרִין בְּאַרְעָא דְּמִצְרַיִם, בְּגִין דְּאִיהוּ דַּרְגָּא עִלָּאָה וּבוּכְרָא דְּכֹלָּא.</p>\n<p>וְתָא חֲזֵי, פַּרְעֹה הֲוָה שׁוּלְטָנֵיהּ בְּמַיָּא, (נ\"א בקדמיתא ומתתאה שרא קודשא בריך הוא וכד מטא לדרגא עילאה דילהון דאיהו בוכרא דכל דרגין דילהון קטל כל בוכרא בארעא דמצרים בגין ההוא דרגא עילאה ובוכרא דכולא ותא חזי פרעה הוה בוכרא ושולטניה במיא) דִּכְתִּיב, (יחזקאל כ״ט:ג׳) הַתַּנִּים הַגָּדוֹל הָרוֹבֵץ בְּתוֹךְ יְאוֹרָיו, בְּגִין כָּךְ אִתְהַפַּךְ נַהֲרֵיהּ בְּדָמָא בְּקַדְמִיתָא. לְבָתַר צְפַרְדְּעִים דִּמְשַׁמְּטֵי לוֹן בְּקָלִין טְסִירִין מְקַרְקְרִין בְּגוֹ מֵעַיְיהוּ, (נ\"א מקרקרין בגו יאורא) וְנַפְקֵי מִגּוֹ יְאוֹרָא, וְסַלְקֵי בְּיַבֶּשְׁתָּא וְרָאמִין קָלִין בְּכָל סִטְרִין, עַד דְּאִינּוּן נַפְלִין כְּמֵתִין בְּגוֹ בֵּיתָא.</p>\n<p>וְרָזָא דְּמִלָּה, כָּל אִינּוּן עֶשֶׂר אָתִין דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ הֲווֹ מִגּוֹ יָדָא תַּקִּיפָא, וְהַהוּא יָדָא אִתְתְּקַף עַל אִינּוּן דַּרְגִּין <Nonei></i>כּוּלְּהוּ שֻׁלְטָנוּתָא דִּלְהוֹן, בְּגִין לְבַלְבְּלָא דַּעְתַּיְיהוּ, וְלָא הֲווֹ יַדְעֵי לְמֶעְבַּד מִידִי. תָּא חֲזֵי, כָּל אִינּוּן דַּרְגִּין דִּלְהוֹן, כֵּיוָן דְּנַפְקֵי לְמֶעְבַּד מִידִי, דְּאִתְחָזֵי לְכֹלָּא לָא יַכְלִין (לבתר) לְמֶעְבַּד מִידִי. (אימת כד) (נ\"א בגין ההוא) יָדָא תַּקִּיפָא (ס\"א שריא) דְּשַׁרְיָא עָלַיְיהוּ.</p>"],[9520011577,"<p>(דכתיב) (שמות ז׳:כ״ח) וְשָׁרַץ הַיְאוֹר צְפַרְדְּעִים וְעָלוּ וּבָאוּ בְּבֵיתֶךָ. ר' שִׁמְעוֹן פָּתַח וְאָמַר, (ירמיהו ל״א:ט״ו) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ וְגוֹ'. תָּא חֲזֵי, הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אַתְרֵי. וְהַאי קְרָא קַשְׁיָא, רָחֵל מְבַכָּה עַל בָּנְיהָ, בְּנָהָא דְּרָחֵל יוֹסֵף וּבִנְיָמִין הֲווֹ וְלָא יַתִּיר, וְלֵאָה (כולהו) שִׁית שְׁבָטִין הֲווֹ דִּילָהּ, אֲמַאי בָּכַת רָחֵל וְלֹא לֵאָה.</p>\n<p>אֶלָּא הָכִי אָמְרוּ כְּתִיב, (בראשית כ״ט:י״ז) וְעֵינֵי לֵאָה רַכּוֹת. אֲמַאי רַכּוֹת. בְּגִין דְּכָל יוֹמָא נַפְקַת לְפָרָשַׁת אֹרְחִין, וְשָׁאָלַת עַל עֵשָׂו, וַהֲווּ אַמְרִין לָהּ עוֹבָדוֹי דְּהַהוּא רָשָׁע, וְדָחִילַת לְמִנְפַּל בְּגוֹ עַדְבֵיהּ, וַהֲוַת בָּכַת כָּל יוֹמָא, עַד דְּאִתְרְכָּכוּ עֵינָהָא.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר, אַנְתְּ בָּכַת בְּגִין הַהוּא צַדִּיקָא, דְּלָא תֶּהֱוֵי בְּעַדְבֵיהּ דְּהַהוּא רָשָׁע. חַיָּיִךְ, אַחֲתָךְ תָּקוּם בְּפָרָשַׁת אֹרְחִין, וְתִבְכֵּי עַל גָּלְוּתְהוֹן דְּיִשְׂרָאֵל, וְאַתְּ תָּקוּם לְגוֹ וְלָא תִּבְכֵּי עָלַיְיהוּ וְרָחֵל אִיהִי בָּכַת עַל גָּלְוּתְהוֹן דְּיִשְׂרָאֵל.</p>\n<p>אֲבָל הַאי קְרָא, אִיהוּ עַל מַה דְּאַמָרָן. אֲבָל רָזָא דְּמִלָּה, דְּרָחֵל וְלֵאָה תְּרֵי עָלְמִין נִינְהוּ. חַד עָלְמָא דְּאְתְכַּסְיָא, וְחַד עָלְמָא דְּאִתְגַּלְיָא. וְעַל דָּא, דָּא אִתְקַבְּרַת וְאִתְחֲפִיאַת לְגוֹ בִּמְעַרְתָּא וְאִתְכְּסִיאַת. וְדָא קַיְּימָא בְּפָרָשַׁת אָרְחִין בְּאִתְגַּלְיָא. וְכֹלָּא כְּגַוְונָא עִלָּאָה. וּבְגִין כַּךְ לָא אָעִיל לָהּ יַעֲקֹב בִּמְעַרְתָּא, וְלָא בַּאֲתָר אַחֲרָא, דְּהָא כְּתִיב (בראשית מ״ח:ז׳) בְּעוֹד כִּבְרַת אֶרֶץ לָבוֹא אֶפְרָתָה, וְלָא אָעִיל לָהּ לְמָתָא. בְּגִין דְּהֲוָה יָדַע דְּאַתְרָהּ הֲוָה בְּאַתְרָא דְּאִתְגַּלְיָא.</p>\n<p>תָּא חֲזֵי, כְּנֶסֶת יִשְׂרָאֵל הָכִי אִקְרֵי, רָחֵל. כְּמָה דְּאַתְּ אָמֵר, (ישעיה נ\"ב) וּכְרָחֵל לִפְנִי גּוֹזְזֶיהָ נְאֱלָמָה. אֲמַאי נְאֱלָמָה. דְּכַד שַׁלְטִין שְׁאַר עַמִּין, קָלָא אִתְפְּסָק מִינָהּ, וְהִיא אִתְאַלְּמַת.</p>\n<p>וְדָא הוּא דִּכְתִּיב, קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים. קוֹל בְּרָמָה נִשְׁמָע דָּא יְרוּשָׁלַיִם לְעֵילָּא. רָחֵל מְבַכָּה עַל בָּנֶיהָ, כָּל זִמְנָא דְּיִשְׂרָאֵל אִינּוּן בְּגָלוּתָא, אִיהִי מְבַכָּה עָלַיְיהוּ דְּאִיהִי אִימָּא דִּלְהוֹן. מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ. מַאי טַעְמָא. כִּי אֵינְנּוּ. כִּי אֵינָם מִבָּעֵי לֵיהּ. אֶלָּא, בְּגִין דְּבַעְלָהּ דְּאִיהוּ קוֹל, אִסְתַּלָּק מִינָהּ, וְלָא אִתְחֲבָּר בַּהֲדָהּ.</p>\n<p>וְתָא חֲזֵי, לָאו שַׁעֲתָא חֲדָא, אִיהִי דְּבָכַת עָלַיְיהוּ דְּיִשְׂרָאֵל, אֶלָּא בְּכָל זִמְנָא וְזִמְנָא דְּאִינּוּן בְּגָלוּתָא. וּבְגִינֵי כַּךְ, קוּדְשָׁא בְּרִיךְ הוּא גָּרַם לוֹן קָלָא לְמִצְרָאֵי, דִּכְתִּיב, (שמות י״א:ו׳) וְהָיְתָה צְעָקָה גְּדוֹלָה בְּכָל אֶרֶץ מִצְרָיִם אֲשֶׁר כָּמוֹהוּ לֹא נִהְיָתָה וְגוֹ'. וְזָמִין לוֹן קָלִין אַחֲרָנִין, בְּאִינּוּן עוּרְדְּעָנִין, דְּרָמָאן קָלִין בְּמֵעַיְיהוּ, וַהֲווּ נַפְלֵי בַּשְּׁוָקֵי כַּמֵּתִים.</p>\n<p>וַתַּעַל הַצְּפַרְדֵּעַ, חֲדָא הֲוָת, וְאוֹלִידַת, וְאִתְמַלְיָית אַרְעָא מִינַיְיהוּ. וַהֲווּ כֻּלְּהוּ מַסְרִין גַּרְמַיְיהוּ לְאֶשָּׁא, דִּכְתִּיב וּבְתַנּוּרֶיךָ וּבְמִשְׁאֲרוֹתֶיךָ, וּמַאי הֲווֹ אָמְרוּ. (תהילים ס״ו:י״ב) בָּאנוּ בָּאֵשׁ וּבַמַּיִם וַתּוֹצִיאֵנוּ לָרְוָיָה. וְאִי תֵּימָא אִי הֲכִי מַאי אִיכְפָּת לְהוּ לְמִצְרָאֵי דְעֲאלִין לְאֶשָׁא כָּל אִינוּן עוֹרְדֵעַנִין אֶלָּא כֻּלְהוּ עֲאלִין לְאֶשָׁא וְאֲזְלִין בְּתַּנוּרָא וְלָא מֵתִין. וְאִינוּן דְמֵתִּין מַאי קַא עַבְדֵי. נַהֲמָא הַוָה בְּתַּנוּרָא וְעֲאלִין בְּגוֹ נַהֲמָא וּמִתְבַּקְעִין וְנַפְקֵי מִנַיְיהוּ אַחֲרָנִין וְאִשְׁתַאֲרִין בְּנַהָמָּא. אָתוּ לְמֵיכַל מִּינֵה הַהוּא פִּתָא אִתְהַדְרוּ עוֹרְדֵעַנָיָיא בֵּמֶעֲיְיהוּ וְרַקְדָן וְרַמָּאן קַלִין עַד דְהַווּ מֵתִים. וְדָא קָשְׁיָיא לוֹן מִכֹּלָא. תָּא חָזֵי כְּתִיב וְשָׁרָץ הַיְאוֹר צְפַרְדֶעִים וְעָלוּ וּבָאוּ בְּבֵיתֶךָ וּבַחֲדַר מִשְׁכָּבְךָ וְעַל מִטָּתְךָ. פַּרְעֹה אִיהוּ אַלְקֵי קַדְמָאַה מִּכֻּלְהוּ וְיָתִּיר מִּכֻּלְהוּ. לֵיהוֵי שְׁמֵיהּ דִי אֱלַהָא מְבֹרָךְ מִן עַלְמָא וְעַד עַלְמָא דְהָוָה פָּקִיד עוֹבַדִין דִבְנֵי נָשָׁא בְכָל מָה דְעֲבְדֵי.</p>\n<p>כְּתִיב (בראשית י״ב:ט״ו) וַיִּרְאוּ אוֹתָהּ שָׂרֵי פַרְעֹה וַיְהַלְלוּ אוֹתָהּ אֶל פַּרְעֹה וַתֻּקַּח הָאִשָּׁה בֵּית פַּרְעֹה. הַאי קְרָא לִדְּרָשָׁא הוּא דְּאָתָא. תְּלַת פַרְעֹה <Nonei></i>הָכָא. חַד, בְּהַהוּא זִמְנָא. וְחַד, בְּיוֹמוֹי דְּיוֹסֵף. וְחַד, בְּיוֹמוֹי דְּמֹשֶׁה דְּאַלְקֵי בְּקוֹלְפוֹי. (ס\"א האי קרא כלא אתקיים בפרעה קדמאה אבל בשעתא וכו' והאי קרא אתקיים)</p>\n<p>פַּרְעֹה קַדְמָאָה, בְּשַׁעֲתָה דְּאִתְנְסִיבַת שָׂרָה לְגַבֵּיהּ, רָמַז לְאוּמָנִין, וְצִיְּירוּ הַהוּא דִּיּוּקְנָא בְּאִדָּרֵיהּ, עַל עַרְסֵיהּ בְּכוֹתָלָא, לָא נָח דַּעְתֵּיהּ, עַד דְּעָבְדוּ דִּיּוּקְנָא דְּשָׂרָה בִּנְסִירוּ, וְכַד סָלִיק לְעַרְסֵיהּ, סָלִיק לָהּ עִמֵּיהּ. כָּל מַלְכָּא דְּאָתָא אֲבַתְרֵיהּ, הֲוָה חָמֵי הַהוּא דִּיּוּקְנָא מְצַיְּירָא צִיּוּרָא, וַהֲווּ עָאלִין קָמֵיהּ בְּדִיחִין, כַּד סָלִיק לְעַרְסֵיהּ הֲוָה אִתְהֲנֵי בְּהַהוּא צִיּוּר. בְּגִין כַּךְ, מַלְכָּא אַלְקֵי הָכָא יַתִּיר מִכֹּלָּא. (תא חזי) הַיְינוּ דִּכְתִּיב, וּבַחֲדַר מִשְׁכָּבְךָ וְעַל מִטָּתֶךָ. וּלְבָתַר, וּבְבֵית עֲבָדֶיךָ וּבְעַמֶּךָ. וּבְכֻלְּהוּ לָא כְּתִיב עַל מִטָּתָם, אֶלָּא לֵיהּ בִּלְחוֹדֵיהּ.</p>\n<p>ר' אַבָּא פָּתַח, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת. הַאי קְרָא אִתְּמַר, וְאַמְרֵי לֵיהּ חַבְרַיָּיא. אֲבָל תָּא חֲזֵי, כַּד אִינּוּן נָחֲלִין עָאלִין לְגוֹ יַמָּא, וְיַמָּא נָקִיט לוֹן, וְשָׁאִיב לוֹן בְּגַוֵּיהּ, בְּגִין דְּקָפָאן מַיָּא בְּגוֹ יַמָּא, וְהַהוּא גְלִידִי שָׁאִיב כָּל מַיָּא דְּעָאלִין בֵּיהּ, וּלְבָתַר נָפְקִין מַיָּא בְּתּוּקְפָא דְּדָרוֹם, וְאַשְׁקֵי יַת כָּל חֵיוַת בָּרָא, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי.</p>\n<p>(זהו הנזכר הכא) וְתָא חֲזֵי, יַמָּא דְּקָפָא שָׁאִיב כָּל מַיָּא, וְאִשְׁתְּרֵי בְּתּוּקְפָא דְּדָרוֹם, כְּמָה דְּאִתְּמַר, וּבְגִין כַּךְ אֵינֶנּוּ מָלֵא, וְאִתְּמַר.</p>\n<p>וְהָא אִתְּעָרוּ בֵּיהּ חַבְרַיָּיא. אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת. מַאי טַעֲמָא הֵם שָׁבִים. בְּגִין דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן לָא פָּסִיק לְעָלְמִין, וְהוּא אַפִּיק תָּדִיר מַיָּא לְיַמָּא, וְעַל דָּא, מַיִין שָׁבִין לָלֶכֶת, וְתָבִין, וְאַזְלִין וְתָבִין, וְלָא פָּסְקִין לְעָלְמִין. וְכַד אִיהוּ תָּב לָלֶכֶת, בְּגִין לְמֵהַךְ לְאַשְׁקָאָה לְכֹלָּא, וְאָתֵי רוּחַ (וארא כ\"ד ע\"א) צָפוֹן וְקָפֵי מַיָּא, וְרוּחָא דְּדָרוֹם דְּאִיהוּ חֲמִימָא, (ס\"א שרי) שָׁדֵּי לוֹן לְמֵהַךְ לְכָל סְטָר. וְעַל דָּא, הַאי יַמָּא יָתִיב בֵּין תְּרֵי סִטְרֵי אִלֵּין, וּבְגִינַיְיהוּ קַיְּימָא, וְאַרְבִין אַזְלִין וְנַטְלִין לְכָל סְטָר.</p>\n<p>תָּא חֲזֵי, כַּד מַלְכָּא, אָתֵי לְעַרְסֵיהּ, בְּשַׁעֲתָא דְּאִתְפְּלִיג לֵילְיָא, רוּחָא דְּצָפוֹן אִתְּעַר, דְּאִיהוּ אִתְּעַר חֲבִיבוּתָא לְגַבֵּי מַטְרוֹנִיתָא, דְּאִלְמָלֵא אִתְעָרוּתָא דְּצָפוֹן, לָא אִתְחֲבָּר מַלְכָּא בַּהֲדָהּ, בְּגִין דְּצָפוֹן שָׁארֵי חֲבִיבוּתָא, כְּמָה דְּאִתְּמַר, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְדָרוֹם חָבִיק בִּרְחִימוּ דִּכְתִּיב וִימִינוֹ תְּחַבְּקֵנִי, כְּדֵין כַּמָּה בְּדִיחִין מִתְעָרִין שִׁירָתָא, עַד דְּאָתֵי צַפְרָא, דִּכְתִּיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כּוֹכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים.</p>\n<p>וְכַד אָתֵי צַפְרָא, כֻּלְּהוּ עִלָּאֵי וְתַתָּאֵי אַמְרֵי שִׁירָתָא, וְיִשְׂרָאֵל כְּגַוְונָא דָּא לְתַתָּא, דִּכְתִּיב, (ישעיהו ס״ב:ו׳-ז׳) הַמַּזְכִּירִים אֶת יְיָ' אַל דֳּמִי לָכֶם. אַל דֳּמִי לָכֶם לְתַתָּא דַּיְיקָא. (בלילה)</p>\n<p>כַּד אִתְפְּלִיג לֵילְיָא, אִינּוּן דְּתִיאוּבְתָּא דִּילְהוֹן לְאַדְכְּרָא תָּדִיר לְקוּדְשָׁא בְּרִיךְ הוּא, לָא יָהֲבֵי שְׁכִיבוּ לְלִבָּא, וְקַיְימִין לְאַדְכְּרָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. כַּד סָלִיק צַפְרָא מַקְדִּימִין לְבֵי כְּנִישְׁתָּא, וּמְשַׁבְּחָאן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֵן בָּתַר פַּלְגּוּת יוֹמָא. וְכֵן בְּלֵילְיָא, כַּד אִתְחֲשָׁךְ וְאִתְדְּבַק לֵילְיָא בְּחָשׁוֹכָא, וּבַת שִׁמְשָׁא. עַל אִלֵּין כְּתִיב הַמַּזְכִּירִים אֶת יְיָ' אַל דֳּמִי לָכֶם. וְדָא עַמָּא קַדִּישָׁא דְּיִשְׂרָאֵל.</p>\n<p>וְעַל דָּא, אַדְכַּר לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, וְסָלִיק עַל פַּרְעֹה, אִלֵּין דְּלָא מִשְׁתַּכְכֵי יְמָמָא וְלֵילְיָא, וּמַאן אִינּוּן. אוּרְדְּעַנְיָא, דְּקַלֵהוֹן לָא מִשְׁתְּכַךְ תָּדִיר, בְּגִין דְּאַתְקִיף בְּעַמָּא קַדִּישָׁא, דְּלָא מִשְׁתַּכְכֵי יְמָמָא וְלֵילֵי, לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וְלָא הֲוָה בַּר נָשׁ בְּמִצְרַיִם, דְּיָכִיל לְמִשְׁתָּעֵי בַּהֲדֵי הֲדָדֵי. וּמִנַּיְיהוּ אִתְחַבְּלָת אַרְעָא. וּמִקַּלֵּהוֹן הֲווֹ יְנוֹקִין וְרַבְיָין מֵתִין.</p>\n<p>וְאִי תֵּימָא הֵיךְ לָא יַכְלִין לְקָטְלָא לוֹן. אֶלָּא, אִי אֲרִים בַּר נָשׁ חוּטְרָא, אוֹ אֲבָנָא, לְקָטְלָא חֲדָא, אִתְבַקְעַת, וְנָפְקִין שִׁית מִינָהּ, מִגּוֹ מְעָהָא, וְאַזְלֵי וְטַרְטָשֵׁי בְּאַרְעָא, עַד דְּהַוִי, מִתְמַנָע לְמִקְרָב בְּהוּ.</p>\n<p>תָּא חֲזֵי, כַּמָּה נָהֲרִין, כַּמָּה יְאוֹרִין, נַפְקָא מִגּוֹ יַמָּא עִלָּאָה, כַּד אִתְמַשְּׁכָן וּמִשְׁתְּרָן מַיָּא, (ויחי רמ\"ג) וּמִתְפַּלְגִין <Nonei></i>כַּמָּה נְחָלִין, לְכַמָּה סִטְרִין, לְכַמָּה יְאוֹרִין, לְכַמָּה נָהֲרִין. וְחוּלָקָא דִּמְמָנָא דְּסִטְרָא דְּמִצְרַיִם אִינּוּן מַיִין (בראשית קכ\"ט) מְרַחֲשָׁן אִלֵּין, דְּלֵית לָךְ מַיִין דְּנָפְקִין מִגּוֹ יַמָּא, דְּלָא מַפְקֵי נוּנִין לְזִינִין.</p>\n<p>מַאן אִינּוּן נוּנִין. אִינּוּן שְׁלִיחָן בְּעָלְמָא, מְמָנָן לְמֶעְבַּד רְעוּתָא דְּמָארֵיהוֹן, מְמָנָן בְּרוּחָא דְּחָכְמְתָא. וְעַל דָּא תָּנֵינָן, אִית מַיִין מְגַדְּלִין חַכִּימִין. וְאִית מַיִין מְגַדְּלִין טִפְּשִׁין. לְפוּם אִינּוּן נָהֲרִין דְּמִתְחַלְּקִין לְכָל סִטְרִין.</p>\n<p>וְהָכָא נַהֲרֵי דְּמִצְרָאֵי, מְגַדְּלִין מָארֵי דְּחָרָשִׁין, נוּנִין בְּסִיטִין, קְפִיטִין בְּעֶשֶׂר דַּרְגִּין דְּחָרָשִׁין, דִּכְתִּיב, (דברים י״ח:י׳-י״א) קוֹסֵם, קְסָמִים, מְעוֹנֵן, וּמְנַחֵשׁ, וּמְכַשֵּׁף, וְחוֹבֵר חָבֶר, וְשׁוֹאֵל אוֹב, וְיִדְּעוֹנִי, וְדוֹרֵשׁ אֶל הַמֵּתִים. הָא עֶשֶׂר זִינִין דְּחָכְמְתָא דְּחָרָשַׁיָּא.</p>\n<p>וּבְהַהוּא זִמְנָא, אוֹשִׁיט קוּדְשָׁא בְּרִיךְ הוּא אֶצְבְּעָא דִּידֵיהּ, וּבַלְבֵּל אִינּוּן נְחָלִין נַהֲרִין דְּמִצְרָאֵי, וְאִתְמְנָעוּ אִינּוּן נוּנֵי דְּחָכְמְתָא דִּילְהוֹן. חַד אִתְהַפַּךְ לְדָמָא, וְחַד דְּסָלִיקוּ נוּנֵי קָלִין, (דכולהו נונין תליין) בְּלֹא תּוֹעַלְתָּא, וְלָא אָתֵי עָלַיְיהוּ רוּחָא דְּאִינּוּן חָכְמְתָן.</p>\n<p>עָרוֹב: כִּי הַאי גַּוְונָא, דְּעִרְבֵּב לוֹן זִינֵי דְּחָכְמְתָא דִּילְהוֹן, וְלָא יַכְלִין לְאִתְדַּבְּקָא, וְלא עוֹד, אֶלָּא אֲפִילּוּ דְּהָנֵי דְּאִשְׁתְּכָחוּ בְּאַרְעָא, מְחַבְּלָן לוֹן בְּאַרְעָא, וּמְחַבְּלָן אוֹרְחַיְיהוּ. עָרוֹב, מַאי עָרוֹב. עִרְבּוּבְיָא. כְּמָה דְאַתְּ אָמֵר (ויקרא י״ט:י״ט) וּבֶגֶד כִּלְאַיִם. עִרוּבִין: (ויקרא י״ט:י״ט) שָׂדְךָ לֹא תִּזְרַע כִּלְאָיִם: זִינִין סַגִּיאִין בְּאָרָמוּת יְדָא.</p>\n<p>תָּא חֲזֵי, כַּמָּה חֵילִין אִתְעָרוּ לְעֵילָּא כְּחַד, וּבַלְבֵּל לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּחֲדָא, בְּגִין לְבַלְבְּלָא חֵיילַיְיהוּ תַּקִּיפָא לְעֵילָּא. וְכָל אִינּוּן גְּבוּרָן דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, בִּידָא חֲדָא הֲוָה, דְּאָרִים יְדֵיהּ עָלַיְיהוּ, לְעֵילָּא וְתַתָּא, וּמִתַּמָּן אִתְאֲבִידַת חָכְמְתָא דְּמִצְרַיִם, דִּכְתִּיב, (ישעיהו כ״ט:י״ד) וְאָבְדָה חָכְמַת חֲכָמָיו וּבִינַת נְבוֹנָיו תִּסְתַּתָּר.</p>\n<p>וְתָא חֲזֵי, כְּתִיב, (ישעיהו י״ט:ב׳) וְסִכְסַכְתִּי מִצְרַיִם בְּמִצְרַיִם. מִצְרַיִם לְעֵילָּא, בְּמִצְרַיִם לְתַתָּא. בְּגִין דְּאִינּוּן חֵילִין לְעֵילָּא, מְמָנָן עַל חֵילִין דִּלְתַתָּא, וְאִתְעָרְבוּ כֻּלְּהוּ. אִתְעָרְבוּ לְעֵילָּא, דְּלָא הֲווֹ מִצְרָאֵי יַכְלֵי לְאִתְקַשְּׁרָא בְּחָרָשַׁיְיהוּ, בְּאִינּוּן דּוּכְתֵּי דַּהֲווֹ מִתְקַשְּׁרֵי בְּקַדְמִיתָא, דְּהָא אִתְבַּלְבָּלוּ. וְעַל דָּא אַיְיתֵי עָלַיְיהוּ עָרוֹב, חִיוָון דַּהֲווֹ מִתְעָרְבֵי דָּא בְּדָא.</p>\n<p>כִּנִּים, דְּסַלְּקָא עַפְרָא דְּאַרְעָא. וְתָא חֲזֵי, כָּל אִיבָא דְּאִתְיְלִידַת בְּאַרְעָא, מֵחֵילָא דִּלְעֵילָּא מְמָנָא דְּאִזְדְּרַע עָלָה אִיהוּ, וְכֹלָּא הֲוָה כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>וְתָא חֲזֵי, שִׁבְעָה רְקִיעִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, כְּגַוְונָא דָּא שִׁבְעָה אַרְעָאן. וְאִינּוּן תְּחוּמִין דְּמִתְפָּרְשָׁן בְּדוּכְתַּיְיהוּ. ז' רְקִיעִין לְעֵילָּא, שִׁבְעָה תְּחוּמֵי אַרְעָא לְעֵילָּא, כְּהַאי גַּוְונָא לְתַתָּא מִתְפָּרְשָׁן דַּרְגִּין, ז' רְקִיעִין, וְז' תְּחוּמֵי אַרְעָא. וְהָא אוּקְמוּהוּ חַבְרַיָּיא, בְּז' אַרְעִין כְּסוּפְטָא דָּא עַל דָּא.</p>\n<p>וְאִינּוּן ז' תְּחוּמֵי אַרְעָא לְעֵילָּא, כָּל חַד וְחַד (מתפרשאן לשבעין ממנן) מִתְפָּרְשָׁן לְעֶשֶׂר, וְאִינּוּן מִתְפָּלְּגָאן לְע' מְמָנָן, דִּמְמָנָן עַל שִׁבְעִין עַמִּין. (בלק ר\"ט ע\"ב) וְהַהוּא אַרְעָא, תְּחוּמָא דְּכָל עַמָּא וְעַמָּא, סַחֲרָא לְאַרְעָא קַדִּישָׁא דְּיִשְׂרָאֵל. כְּמָה דְאַתְּ אָמֵר (שיר השירים ג׳:ז׳) הִנִּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל וַעֲשָׂרָה בְּגַוַויְיהוּ טְמִירִין, וְאִינּוּן ע' דְּסַחֲרָן אַרְעָא קַדִּישָׁא. וְדָא הוּא לְעֵילָּא, כְּגַוְונָא דָּא לְתַתָּא.</p>\n<p>וְתָּא חֲזֵי, הַהוּא אַרְעָא, תְּחוּמָא דְּחוּלָקָא דְּמִצְרָאֵי, בְּהַהוּא זִמְנָא, אוֹשִׁיט קוּדְשָׁא בְּרִיךְ הוּא אֶצְבְּעָא דִּילֵיהּ, וְאִתְיְלִידוּ טַפְסִירִין בְּהַהוּא תְּחוּמָא, וְאִתְיְבָשׁוּ כָּל אִינּוּן תְּחוּמִין דְּרַכִּיכוּ מַיָּא. וְכָל יְרוֹקָא דְּמַיִין דְּנַבְעִין, כְּדֵין לְתַתָּא, אִתְחֲזִיאוּ קִלְמִין מֵעַפְרָא דְּאַרְעָא.</p>\n<p>וְהָא אִתְּמַר דְּאַהֲרֹן הֲוָה מָחֵי. אֲבָל בְּגִין דָּא אַהֲרֹן הֲוָה מָחֵי, לְאַחֲזָאָה דִּימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא תָּבַר לְשַׂנְאִין, כְּמָה דְאַתְּ אָמֵר, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. כְּגַוְונָא דָּא, זָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַיְיתָאָה עַל קַרְתָּא דְּרוֹמִי רַבְּתָא, דִּכְתִּיב, (ישעיהו ל״ד:ט׳) וְנֶהֶפְכוּ נְחָלֶיהָ לְזֶפֶת וַעֲפָרָהּ לְגָפְרִית. וְעַל דָּא, כָּל עֲפַר הָאָרֶץ הָיָה כִנִּים בְּכָל אֶרֶץ מִצְרָיִם.</p>"],[9520011578,"<p>רִבִּי יְהוּדָה וְרִבִּי חִיָּיא, הֲווֹ אַזְלֵי בְּאוֹרְחָא. אָמַר רִבִּי חִיָּיא, חַבְרַיָּיא כַּד אִינּוּן בְּאוֹרְחָא, <Nonei></i>בַּעְיָין לְמֵהַךְ בְּלִבָּא חַד. וְאִי אִיעֲרָעוּ, אוֹ אַזְלֵי בְּגַוַויְיהוּ חַיָּיבֵי עָלְמָא, אוֹ בְּנֵי נָשָׁא דְּלָאו אִינּוּן מֵהֵיכָלָא דְּמַלְכָּא, בָּעוּ לְאִתְפָּרְשָׁא מִנַּיְיהוּ. מְנָא לָן. מִכָּלֵב, דִּכְתִּיב, (במדבר י״ד:כ״ד) וְעַבְדִּי כָלֵב עֵקֶב הָיְתָה רוּחַ אַחֶרֶת עִמּוֹ וַיְמַלֵּא אַחֲרָי. מַאי רוּחַ אַחֶרֶת. דְּאִתְפְּרַשׁ מֵאִינוּן מְאַלְּלִין, דִּכְתִּיב, (במדבר י״ד:כ״ד) וַיַּעֲלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן. דְּאִתְפְּרַשׁ מֵאִינוּן מְאַלְּלִין וְאָתָא אִיהוּ בִּלְחוֹדוֹי לְחֶבְרוֹן, לְאִשְׁתַּטְּחָא עַל קִבְרֵי אֲבָהָן.</p>\n<p>וְחֶבְרוֹן, אִתְיְהִיב לֵיהּ חוּלָק אַחֲסָנָא לְאִתַּתְקְפָא בֵּיהּ, כְּמָה דְּאַתְּ אָמֵר, (דברים א׳:ל״ו) וְלוֹ אֶתֵּן אֶת הָאָרֶץ אֲשֶׁר דָּרַךְ בָּהּ. אֲמַאי יָהִיבוּ לֵיהּ חֶבְרוֹן. אִי בְּגִין דְּאִשְׁתָּטַּח בְּקִבְרֵי אֲבָהָן לְאִשְׁתְּזָבָא מֵהַהוּא עֵיטָא דִּילְהוֹן דְּאִשְׁתְּזִיב. לָא.</p>\n<p>אֶלָּא, רָזָא דְּמִלָּה שְׁמַעְנָא. כְּגַוְונָא דָּא כְּתִיב, (שמואל ב ב׳:א׳) וַיִּשְׁאַל דָּוִד בַּיְיָ' לֵאמֹר הַאֶעֱלֶה בְּאַחַת עָרֵי יְהוּדָה וַיֹּאמֶר יְיָ' אֵלָיו עֲלֵה וַיֹּאמֶר דָּוִד אָנָּה אֶעֱלֶה וַיֹּאמֶר חֶבְרוֹנָה. הָכָא אִית לְאִסְתַּכְּלָא, כֵּיוָן דְּהָא מִית שָׁאוּל, וְדָוִד בְּיוֹמֵי דְּשָׁאוּל אִתְמְשַׁח לְקַבְּלָא מַלְכוּ. כֵּיוָן דְּמִית שָׁאוּל אֲמַאי לָא אַמְלִיכוּ לֵיהּ לְדָוִד, וְלָא קַבִּיל מַלְכוּ עַל כָּל יִשְׂרָאֵל, וְאָתָא לְחֶבְרוֹן, ומַלְכוּ קַבִּיל עַל יְהוּדָה בִּלְחוֹדוֹי שֶׁבַע שָׁנִים, וְאִתְעַכָּב תַּמָּן כָּל הָנֵי שֶׁבַע שָׁנִים. וּלְבָתַר דְּמִית אִישׁ בּוֹשֶת, קַבִּיל מָלְכוּ עַל כָּל יִשְׂרָאֵל בִּירוּשָׁלַיִם.</p>\n<p>אֶלָּא, כֹּלָּא הוּא רָזָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, מַלְכוּתָא קַדִּישָׁא לָא קַבִּיל מַלְכוּ שְׁלֵימָתָא, עַד דְּאִתְחֲבָּר (בראשית ע\"ט ע\"ב) בַּאֲבָהָן. וְכַד אִתְחֲבָּר בְּהוּ, אִתְבְּנִי בְּבִנְיָינָא שְׁלִימוּ, מֵעָלְמָא עִלָּאָה, וְעָלְמָא (בראשית רמ\"ז ע\"א) עִלָּאָה אִקְרֵי שֶׁבַע שָׁנִים, בְּגִין דְּכֻלְּהוּ בֵּיהּ.</p>\n<p>וְסִימָנִיךָ (מלכים א ו׳:ל״ח) וַיִּבְנֵהוּ שֶׁבַע שָׁנִים, דָּא עָלְמָא עִלָּאָה. וְלָא כְּתִיב וַיִּבְנֵהוּ בְּשֶׁבַע שָׁנִים. כְּמָה דְּאַתְּ אָמֵר, (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. מַאן שֵׁשֶׁת יָמִים, דָּא אַבְרָהָם. דִּכְתִּיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּאַבְרָהָם. וְאַבְרָהָם שֵׁשֶׁת יָמִים אִקְרֵי. וּבְגִין (נ\"א וביה) דְּאִיהוּ שֵׁשֶׁת יָמִים, אִתְבְּנֵי עָלְמָא. בְּהַהוּא (נ\"א בהאי) גַּוְונָא וַיִּבְנֵהוּ שֶׁבַע שָׁנִים.</p>\n<p>וְתָא חֲזֵי, דָּוִד בָּעָא לְאִתְבְּנָאָה בְּמַלְכוּ שְׁלֵימָתָא לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, וְלָא אִתְבְּנֵי, עַד דְּאָתָא וְאִתְחֲבָּר בַּאֲבָהָן. וְקָאִים שֶׁבַע שָׁנִים לְאִתְבְּנָאָה בְּגַוַויְיהוּ. לְבָתַר שֶׁבַע שָׁנִים, אִתְבְּנֵי בְּכֹלָּא, אִתְמַשְּׁכָא מַלְכוּתֵיהּ דִּי לָא תַּעְדֵּי לְעָלְמִין. וְאִי לָאו דְּאִתְעָבַד בְּחֶבְרוֹן לְאִתְחַבְּרָא בְּדוּכְתֵּיהּ, לָא אִתְבְּנִי מַלְכוּתֵיהּ לְאִתְמַשְׁכָא כְּדְקָא יֵאוֹת. כְּהַאי גַּוְונָא כָּלֵב, אִתְנְהִיר בֵּיהּ רוּחָא דְּחָכְמְתָא, וְאָתָא לְחֶבְרוֹן, לְאִתְחַבְּרָא בַּאֲבָהָן, וּלְדוּכְתֵּיהּ אָזִל, וּלְבָתַר, דּוּכְתֵּיהּ הֲוָה, וְיָרִית לֵיהּ.</p>"],[9520011579,"<p>רִבִּי יֵיסָא (נדפס מקץ קצ\"ו ע\"ב) וְרִבִּי חִזְקִיָּה, הֲווֹ אַזְלֵי מִקַּפּוּטְקִיָּא לְלוּד, וַהֲוָה עִמְּהוֹן חַד יוּדָאי בְּמָטוּל דְּקַטְפִירָא דַּחֲמָרָא. עַד דַּהֲווֹ אַזְלֵי, אָמַר רִבִּי יֵיסָא לְרִבִּי חִזְקִיָּה, אַפְתַּח פּוּמָךְ, וְאֵימָא חַד מִלָּה, מֵאִינוּן מִלֵּי מְעַלְּיָיתָא דְּאוֹרַיְיתָא, דְּאַתְּ אֲמַרְתְּ בְּכָל יוֹמָא, קָמֵי בּוּצִינָא קַדִּישָׁא.</p>\n<p>פָּתַח וְאָמַר, (משלי ג׳:י״ז) דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דְּרָכֶיהָ דַּרְכֵי נֹעַם, אִלֵּין אוֹרְחִין דְּאוֹרַיְיתָא, דְּמַאן דְּאָזִיל בְּאוֹרְחֵי דְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא, אַשְׁרֵי עָלֵיהּ נְעִימוּתָא דִּשְׁכִינְתָּא, דְּלָא תַּעְדֵּי מִנֵיהּ לְעָלְמִין. וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם, דְּכָל שְׁבִילִין דְּאוֹרַיְיתָא, כּוּלְהוֹן שְׁלָם. שְׁלָם לֵיהּ לְעֵילָּא, שְׁלָם לֵיהּ לְתַתָּא. שְׁלָם לֵיהּ בְּעָלְמָא דֵּין, שְׁלָם לֵיהּ בְּעָלְמָא דְּאָתֵי.</p>\n<p>אָמַר הַהוּא יוּדָאי, אִיסוּרָא בְּקִיסְטְרָא, בְּהַאי קְרָא אִשְׁתְּכַח. אֲמַר לֵיהּ מְנַּיִין לָךְ. אָמַר לֵיהּ, מֵאַבָּא שְׁמַעְנָא, וְאוֹלִיפְנָא הָכָא בְּהַאי קְרָא מִלָּה טָבָא.</p>\n<p>פָּתַח וְאָמַר, הַאי קְרָא בִּתְרֵין גַּוְונִין אִיהִי, וּבִתְרֵין סִטְרִין. קָרֵי בֵּיהּ דְּרָכִים, וְקָרֵי בֵּיהּ נְתִיבוֹת. קָרֵי בֵּיהּ נוֹעַם, וְקָרֵי בֵּיהּ שָׁלוֹם. מַאן דְּרָכִים. וּמַאן נְתִיבוֹת. מַאן נֹעַם. וּמַאן שָׁלוֹם.</p>\n<p>אֶלָּא, דְּרָכֶיהָ דַּרְכֵי נֹעַם, הַיְינוּ דִּכְתִּיב, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ. דְּהָא כָּל אֲתָר דְּאִקְרֵי בְּאוֹרַיְיתָא דֶּרֶךְ, הוּא אוֹרְחָא פְּתִיחָא לְכֹלָּא. כְּהַאי אוֹרְחָא דְּהוּא פָּתִיחַ לְכָל בַּר נָשׁ. כַּךְ דְּרָכֶיהָ, אִלֵּין דְּרָכִים דְּאִינּוּן פְּתִיחָן מֵאֲבָהָן, דְּכָרָאן בְּיַמָּא <Nonei></i>רַבָּא, וְעָאלִין בְּגַוֵּיהּ. וְאִינּוּן אוֹרְחִין מִתְפַּתְּחִין לְכָל עִיבָר, וּלְכָל סִטְרֵי עָלְמָא.</p>\n<p>וְהַאי נֹעַם, הוּא נְעִימוּ דְּנָפִיק מֵעָלְמָא דְּאָתֵי, (נ\"א ומעלמא דאתי נהרין כל בוצינין) וְנָהִיר לְכָל בּוּצִינִין, וּמִתְפָּרְשִׁין (נ\"א נהורין) לְכָל עִיבָר, וְהַהוּא טִיבוּ, וּנְהוֹרָא דְּעָלְמָא דְּאָתֵי, דְּיַנְקִין אֲבָהָן, אִקְרֵי נֹעַם. דָּבָר אַחֵר, עָלְמָא דְּאָתֵי, אִקְרֵי נֹעַם. וְכַד אִתְּעַר עָלְמָא דְּאָתֵי, כָּל טִיבוּ, וְכָל חֵידוּ, וְכָל נְהוֹרִין, וְכָל חֵירוּ דְּעָלְמָא אִתְּעַר. וּבְגִינֵי כַּךְ, אִקְרֵי נֹעַם.</p>\n<p>וְעַל דָּא תָּנֵינָן, חַיָּיבִין דְּגֵיהִנָּם, בְּשַׁעֲתָא דְּעָאל שַׁבְּתָא, כֻּלְּהוּ נַיְיחִין, וְאִית לְהוּ (ס\"א חירו) חֵידוּ, וְנַיְיחָא בְּשַׁבָּתָא. כֵּיוָן דְּנָפִיק שַׁבְּתָא, אִית לָן לְאַתְעָרָא חֵידוּ עִלָּאָה עָלָנָא, דְּנִשְׁתֵּזִיב מֵהַהוּא עוֹנְשָׁא דְּחַיָּבָיא, דְּאִתְדָּנוּ מֵהַהִיא שַׁעֲתָא וּלְהָלְאָה. וְאִית לָן לְאַתְעֲרָא וְלֵימָא, (תהילים צ׳:י״ז) וִיהִי נֹעַם יְיָ' אֱלֹהֵינוּ עָלֵינוּ. דָּא הוּא נֹעַם עִלָּאָה, (חירו) חֵידוּ דְּכֹלָּא. וְעַל דָּא, דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם.</p>\n<p>מַאן נְתִיבוֹתֶיהָ. אִלֵּין אִינּוּן נְתִיבוֹת וּשְׁבִילִין, דְּנַפְקֵי מִלְּעֵילָּא, וְכֻלְּהוּ נָקִיט לוֹן בְּרִית יְחִידָאי, דְּאִיהוּ אִקְרֵי שָׁלוֹם, שְׁלָמָא דְּבֵיתָא, וְעָאִיל לוֹן לְיַמָּא רַבָּא, כַּד אִיהוּ בְּתוּקְפֵּיהּ. וּכְדֵין יָהִיב לֵיהּ שְׁלָם. הֲדָא הוּא דִכְתִיב וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. (ע\"כ) אָתוּ רִבִּי יֵיסָא ור' חִזְקִיָּה, וְנָשְׁקוּ לֵיהּ, אָמְרוּ וּמַה כָּל הָנֵי מִלִּין עִלָּאִין טְמִירִין גַּבָּךְ, וְלָא יָדַעְנָא. אָזְלוּ. כַּד מָטוּ חַד בֵּי חֲקַל, חָמוּ בְּעִירֵי דְּבֵי חֲקַל מֵתִין, אָמְרוּ וַדַּאי דֶּבֶר דִּבְעִיִרִי אִית בַּאֲתַר דָּא.</p>"],[9520011580,"<p>אָמַר הַהוּא יוּדָאִי, הָא דְּאַמְרִיתּוּ דְּקוּדְשָׁא בְּרִיךְ הוּא קָטַל בְּמִצְרַיִם, כָּל אִינּוּן עָאנֵי, כָּל אִינּוּן בְּעִירֵי. תְּלַת מוֹתָנֵי הֲווֹ בִּבְעִירֵי. חַד, דֶּבֶר. וְחַד, אִינּוּן דְּקָטִיל בָּרָד. וְחַד, אִינּוּן בּוּכְרֵי דִּבְעִירֵי.</p>\n<p>וּמַה הֲוָה מוֹתָנָא דִּילְהוֹן. אֶלָּא, הָא, כְּתִיב בְּקַדְמִיתָא, (שמות ט׳:ג׳) הִנֵּה יַד יְיָ' הוֹיָה בְּמִקְנְךָ אֲשֶׁר בַּשָּׂדֶה, אֲמַאי בְּכֻלְּהוּ לָא כְּתִיב יַד יְיָ'. אֶלָּא, הָכָא (נ\"א לא כתיב יד אלהים אלא יד יי) (ס\"א אל יד ה') אִיהוּ יָדָא בַּחֲמִשָּׁה אֶצְבְּעָאן. דְּהָא בְּקַדְמִיתָא כְּתִיב, אֶצְבַּע אֱלֹהִים הִיא. וְהָכָא כֻּלְּהוּ חָמֵשׁ אֶצְבְּעָאן, וְכָל אֶצְבְּעָא וְאֶצְבְּעָא, קָטַל זִּינָא חֲדָא. וַחֲמִשָּׁה זִינִין הֲווֹ, דִּכְתִּיב, בַּסּוּסִים, בַּחֲמוֹרִים, בַּגְּמַלִּים, בַּבַּקָר, וּבַצֹּאן. הָא חֲמִשָּׁה זִינִין, לַחֲמִשָּׁה אֶצְבְּעָאן, דְּאִקְרוּן יַד. בְּגִינֵי כַּךְ, הִנֵּה יַד יְיָ' הוֹיָה וְגוֹ' דֶּבֶר כָּבֵד מְאֹד. דַּהֲווֹ מֵתִים מִגַּרְמַיְיהוּ, וְאִשְׁתְּכָחוּ מֵתִים.</p>\n<p>בָּתַר דְּלָא אֲהַדְרוּ מִצְרָאֵי, אִינּוּן אַתְוָון מַמָּשׁ, אֲהַדְרוּ וְקָטְלוּ כָּל אִינּוּן דְּאִשְׁתָּאָרוּ. וְדֶבֶר, אַהְדָּר בָּרָד. מַה בֵּין הַאי לְהַאי. אֶלָּא דָּא בְּנִיחוּתָא, וְדָא בִּתְקִיפוּ דְּרוּגְזָא. וּתְרֵין אִלֵּין, הֲווֹ בַּאֲתַר חַד, בְּחָמֵשׁ אֶצְבְּעָאן.</p>"],[9520011581,"<p>תָּא חֲזֵי, דֶּבֶר אַתְוָון דַּהֲווֹ בְּנִיחוּתָא, מוֹתָנָא בְּנַיְיחָא, דַּהֲווֹ מֵתִין מִגַּרְמַיְיהוּ. בָּרָד, דְּאִתְהַדָּרוּ אַתְוָון בִּתְקוֹף רוּגְזָא, וְקָטַל כֹּלָּא. יָתְבוּ בְּהַהוּא חֲקָל, חָמוּ עָאנֵי דְּאַתְיָין לַאֲתָר חַד, וּמֵתִין תַּמָּן, קָם הַהוּא יוּדָאִי לְגַבֵּי הַהוּא אֲתָר, וְחָמָא תְּרֵין קַטְפִירֵי, דְּמַלְיָין אַקוּסְטְרָא.</p>\n<p>פָּתַח וְאָמַר, כְּתִיב (בראשית י״ב:ב׳) וְאֶעֶשְׂךָ לְגוֹי גָּדוֹל וַאֲבָרֶכְךָ וַאֲגַדְּלָה שְׁמֶךָ וְהְיֵה בְּרָכָה, הַאי מִלָּה דְּרִבִּי אֶלְעָזָר, דְּאָמַר, וְאֶעֶשְׂךָ לְגוֹי גָּדוֹל, לָקֳבֵל לֶךְ לְךָ. וַאֲבָרֶכְךָ, לָקֳבֵל מֵאַרְצְךָ. וַאֲגַדְּלָה שְׁמֶךָ, לָקֳבֵל וּמִמּוֹלַדְתְּךָ. וֶהְיֵה בְּרָכָה, לָקֳבֵל וּמִבֵּית אָבִיךָ. וְדָא לָקֳבֵל דָּא.</p>\n<p>ר' שִׁמְעוֹן אָמַר, רָזָא דְּחָכְמְתָא הָכָא. וְאֶעֶשְׂךָ לְגוֹי גָּדוֹל, לָקֳבֵל סְטָר יְמִינָא. וַאֲבָרֶכְךָ, לָקֳבֵל סְטָר שְׂמָאלָא. וַאֲגַדְּלָה שְׁמֶךָ, לָקֳבֵל סְטָר אֶמְצָעִיתָא. וֶהְיֵה בְּרָכָה, לָקֳבֵל סְטָר אַרְעָא דְּיִשְׂרָאֵל. וְכֹלָּא רָזָא דִּרְתִּיכָא קַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, בְּאִתְעָרוּתָא דִּלְתַתָּא, אִתְּעַר לְעֵילָּא. וְעַד לָא יִתְּעַר לְתַתָּא, לָא יִתְּעַר לְעֵילָּא, לְאַשְׁרָאָה עָלֵיהּ. מַה כְּתִיב בְּאַבְרָהָם, (בראשית י״א:ל״א) וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים. וַיֵּצְאוּ אִתָּם, וַיֵּצְאוּ אִתּוֹ מִבָּעֵי לֵיהּ. דְּהָא כְּתִיב וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ (ואת לוט בן הרן) וְגוֹ'. מַהוּ וַיֵּצְאוּ אִתָּם. אֶלָּא, תֶּרַח וְלוֹט נָפְקוּ עִם אַבְרָהָם וְשָׂרָה, דְּכֵיוָן דְּאִשְׁתְּזִיב אַבְרָהָם מִן נוּרָא, אִתְהַדַּר תֶּרַח לְמֶעְבַּד רְעוּתֵיהּ. וּבְגִין <Nonei></i>כַּךְ, וַיֵּצְאוּ אִתָּם. כֵּיוָן דְּאִינּוּן אִתְעֲרוּ בְּקַדְמִיתָא, אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לֶךְ לְךָ.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, לֶךְ לְךָ. לְתִקּוּנָךָ לְגַרְמָךְ. מֵאַרְצְךָ, מֵהַהוּא סִטְרָא דְּיִשּׁוּבָא דְּאַתְּ תָּקִיל, דְּאִתְיְלִידַת בֵּיהּ. וּמִמּוֹלַדְתְּךָ, מֵהַהוּא תּוֹלְדָה דִּילָךְ. וּמִבֵּית אָבִיךָ, דְּאַתְּ אַשְׁגַּח בְּשָׁרָשָׁא דִּלְהוֹן. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ, תַּמָן אִתְגְּלֵי לָךְ, מַה דְּאַתְּ בָּעֵי, הַהוּא חֵילָא דִּמְמָנָא עָלָּה, דְּאִיהוּ עָמִיק וְסָתִים. מִיָּד, וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ'. וַאֲנָן קָא בָּעֵינָן לְמֵהַךְ מֵהָכָא לְמִנְדַּע רָזָא דְּחָכְמְתָא (חסר).</p>"],[9520011582,"<p>רִבִּי יוֹסֵי וְרִבִּי חִיָּיא הֲווֹ אַזְלֵי בְּאוֹרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי חִיָּיא, אֲמַאי אַתְּ שָׁתִיק, הָא אוֹרְחָא לָא אִתְתְּקַן, אֶלָּא בְּמִלֵּי דְּאוֹרַיְיתָא. אִתְנְגִיד רִבִּי חִיָּיא, וּבָכָה, פָּתַח וְאָמַר, (בראשית י״א:ל׳) וַתְּהִי שָׂרַי עֲקָרָה אֵין לָהּ וָלָד וַוי עַל דָּא, וַוי עַל הַהוּא זִמְנָא דְּאוֹלִידַת הָגָר לְיִשְׁמָעֵאל.</p>\n<p>(פתח רבי אבא ואמר (צפניה ג׳:ט׳) כי אז אהפוך אל עמים שפה ברורה לקרא כלם בשם יי' לעבדו שכם אחד. וכתיב (זכריה י״ד:ט׳) והיה יי' למלך וגו' ביום ההוא יהיה יי' אחד ושמו אחד) אֲמַר לֵיהּ רִבִּי יוֹסֵי, אֲמַאי. וְהָא אוֹלִידַת לְבָתַר, וַהֲוָה לָהּ בְּרָא גִּזְעָא קַדִּישָׁא. אֲמַר לֵיהּ, אַתְּ חָמֵי, וַאֲנָא חֲמֵינָא, וְהָכִי שְׁמַעְנָא מִפּוּמוֹי דְּרַבִּי שִׁמְעוֹן מִלָּה, וּבָכֵינָא (ס\"א אמרז ליה מאי היא אמר ליה ווי וכו') וַוי עַל הַהוּא זִמְנָא, דִּבְגִין דְּשָׂרָה אִתְעַכְּבַת, כְּתִיב, (בראשית ט״ז:ה׳) וַתֹּאמֶר שָׂרַי אֶל אַבְרָם וְגוֹ' בֹּא נָא אֶל שִׁפְחָתִי וְגוֹ'. וְעַל דָּא, קַיְּימָא שַׁעֲתָא לְהָגָר, לְמֵירַת לְשָׂרָה גְּבִירְתָּהּ, וַהֲוָה לָהּ בְּרָא מֵאַבְרָהָם.</p>\n<p>וְאַבְרָהָם אָמַר, (בראשית י״ז:י״ח) לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךָ, וְאַף עַל גַּב דְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מְבַשֵּׂר לֵיהּ עַל יִצְחָק, אִתְדְּבַק אַבְרָהָם בְּיִשְׁמָעֵאל, עַד דְקוּדְשָׁא בְּרִיךְ הוּא אָתִיב לֵיהּ, (בראשית י״ז:כ׳) וּלְיִשְׁמָעֵאל שְׁמַעְתִּיךָ וְגוֹ'. לְבָתַר אִתְגְּזַר, וְעָאל בְּקַיְּימָא קַדִּישָׁא, עַד לָא יִפּוּק יִצְחָק לְעָלְמָא.</p>\n<p>וְתָּא חֲזֵי, אַרְבַּע מְאָה שְׁנִין, קַיְּימָא הַהוּא מְמָנָא דִּבְנִי יִשְׁמָעֵאל, וּבָעָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, אֲמַר לֵיהּ, מַאן דְּאִתְגְּזַר אִית לֵיהּ חוּלָקָא בִּשְׁמָךְ. אֲמַר לֵיהּ אִין. אֲמַר לֵיהּ וְהָא יִשְׁמָעֵאל דְּאִתְגְּזַר, (ולא עוד אלא דאתגזר בר תליסר שנין) אֲמַאי לֵית לֵיהּ חוּלָקָא בָּךְ כְּמוֹ יִצְחָק. אֲמַר לֵיהּ, דָּא אִתְגְּזַר כְּדְקָא יֵאוֹת וּכְתִיקּוּנוֹי, וְדָא לָאו הָכִי. וְלֹא עוֹד, אֶלָּא דְּאִלֵּין מִתְדַּבְּקִין בִּי כְּדְקָא יֵאוֹת, לִתְמַנְיָא יוֹמִין וְאִלֵּין רְחִיקִין מִנִּי עַד כַּמָּה יָמִים. אֲמַר לֵיהּ, וְעִם כָּל דָּא, כֵּיוָן דְּאִתְגְּזַר לָא יְהֵא לֵיהּ אֲגָר טָב בְּגִינֵיהּ.</p>\n<p>וַוי עַל הַהוּא זִמְנָא, דְּאִתְיְלִיד יִשְׁמָעֵאל בְּעָלְמָא, וְאִתְגְּזַר. מַה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, אַרְחִיק לְהוּ לִבְנֵי יִשְׁמָעֵאל, מִדְּבֵקוּתָא דִּלְעֵילָּא, וְיָהַב לְהוּ חוּלָקָא לְתַתָּא בְּאַרְעָא קַדִּישָׁא, בְּגִין הַהוּא גְּזִירוּ דִּבְּהוֹן.</p>\n<p>וּזְמִינִין בְּנֵי יִשְׁמָעֵאל, לְמִשְׁלָט בְּאַרְעָא קַדִּישָׁא, כַּד אִיהִי רֵיקַנְיָא מִכֹּלָּא, זִמְנָא סַגִּי, כְּמָה דִּגְזִירוּ דִּלְהוֹן בְּרֵיקַנְיָּא בְּלא שְׁלִימוּ. וְאִינּוּן יְעַכְּבוּן לְהוֹן לִבְנִי יִשְׂרָאֵל לְאָתָבָא לְדוּכְתַיְיהוּ, עַד דְּאִשְׁתְּלִים הַהוּא זְכוּתָא דִּבְנֵי יִשְׁמָעֵאל.</p>\n<p>וּזְמִינִין בְּנֵי יִשְׁמָעֵאל, לְאַתְעֲרָא קְרָבִין תַּקִּיפִין בְּעָלְמָא, וּלְאִתְכַּנְּשָׁא בְּנִי אֱדוֹם עָלַיְיהוּ, וְיִתְעָרוּן קְרָבָא בְּהוּ, חַד עַל יַמָּא, וְחַד עַל יַבֶּשְׁתָּא וְחַד סָמוּךְ לִירוּשְׁלֵים, וְיִשְׁלְטוּן אִלֵּין בְּאִלֵּין, וְאַרְעָא קַדִּישָׁא לָא יִתְמְסָר לִבְנִי אֱדוֹם.</p>\n<p>בְּהַהוּא זִמְנָא, יִתְּעַר עַמָּא חַד מִסַּיְיפֵי עָלְמָא, עַל רוֹמִי חַיָּיבָא, וְיִגַּח בָּהּ קְרָבָא תְּלַת יַרְחִין, וְיִתְכַּנְּשׁוּן תַּמָּן עֲמַמְיָּא, וְיִפְּלוּן בִּידַיְיהוּ, עַד דְּיִתְכַּנְּשׁוּן כָּל בְּנִי אֱדוֹם עָלָּה, מִכָּל סַיְיפֵי עָלְמָא. וּכְדֵין יִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ד:ו׳) כִּי זֶבַח לַיְיָ' בְּבָצְרָה וְגוֹ'. וּלְבָתַר דָּא מַה כְּתִיב, לֶאֱחוֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ' וִישֵׁיצֵי לִבְנֵי יִשְׁמָעֵאל מִינָהּ, וְיִתְבַּר כָּל חֵילִין דִּלְעֵילָּא וְלָא יִשְׁתְּאַר חֵילָא לְעֵילָּא עַל עַמָּא דְּעָלְמָא, אֶלָּא חֵילָא דְּיִשְׂרָאֵל בִּלְחוֹדוֹי. הֲדָא הוּא דִכְתִיב, (תהילים קכ״א:ה׳) יְיָ' צִלְּךָ עַל יַד יְמִינֶךָ.</p>\n<p>בְּגִין דִּשְׁמָא קַדִּישָׁא בִּימִינָא, וְאוֹרַיְיתָא בִּימִינָא, וְעַל דָּא בִּימִינָא תַּלְיָא כֹּלָּא וְתָנֵינָן, דְּבָעֵי לְזַקְפָא יְמִינָא עַל שְׂמָאלָא, כְּמָה דְּאוּקְמוּהָ. דִּכְתִּיב, (דברים ל\"ג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. וּבְזִמְנָא דְּאָתֵי, (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי. וּבְהַהוּא זִמְנָא כְּתִיב, (צפניה ג׳:ט׳) כִּי אָז אֶהְפּוֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יְיָ' לְעָבְדוֹ שְׁכֶם אֶחָד. וּכְתִיב, (זכריה י״ד:ט׳) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9520011583,"<p><Nonei></i>(שמות י׳:א׳) וַיֹּאמֶר יְיָ אֶל מֹשֶׁה בֹּא אֶל פַּרְעֹה כִּי אֲנִי הִכְבַּדְתִּי אֶת לִבּוֹ וְגוֹ'. רִבִּי יְהוּדָה פָּתַח ואָמַר, (תהלים פ\"ט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה יְיָ' בְּאוֹר פָּנְיךָ יְהַלֵּכוּן. כַּמָּה אִצְטְרִיכוּ בְּנֵי נָשָׁא, לְמֵהַךְ בְּאָרְחֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִטַר פִּקּוּדֵי אוֹרַיְיתָא, בְּגִין דְּיִזְכּוּן בָּהּ לְעָלְמָא דְּאָתֵי, וּלְשֵׁזָבָא לוֹן מִכָּל קִטְרוּגִין דִּלְעֵילָּא וְתַתָּא. בְּגִין, דְּהָא כְּמָה דְּאִשְׁתְּכָחוּ מְקַטְרְגִין בְּעָלְמָא לְתַתָּא, הָכִי נָמֵי אִשְׁתְּכָחוּ מְקַטְרְגִין לְעֵילָּא דְּקַיְימֵי עָלַיְיהוּ דִּבְנֵי נָשָׁא.</p>\n<p>אִינּוּן דְּעַבְדִין פִּקּוּדֵי אוֹרַיְיתָא, וְאַזְלֵי בְּאוֹרַח מֵישָׁר, בִּדְחֲלָא דְּמָארֵיהוֹן, כַּמָּה אִינּוּן סַנֵּיגוֹרִין דְּקַיְימִין עָלַיְיהוּ לְעֵילָּא, כְּמָה דְּאַתְּ אָמַר (איוב ל״ג:כ״ג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף וְגוֹ'. וּכְתִיב וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. בְּגִין כַּךְ, זַכָּאָה אִיהוּ מַאן דְּנָטִיר פִּקּוּדֵי אוֹרַיְיתָא.</p>\n<p>אָמַר לֵיהּ רִבִּי חִיָּיא, אִי הָכִי, אֲמַאי אִצְטְרִיךְ הָכָא מַלְאָךְ דְּלֶיהֱוִי סַנֵּיגוֹרָא עָלֵיהּ דְּבַר נָשׁ וְהָא כְּתִיב (משלי ג׳:כ״ו) כִּי יְיָ' יִהְיֶה בְּכִסְלֶךָ ושָׁמַר רַגְלְךָ מִלָּכֶד, וּכְתִיב (תהילים קכ״א:ז׳) יְיָ' יִשְׁמָרְךָ מִכָּל רָע. דְּהָא חָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כָּל מַה דְּבַר נָשׁ עָבִיד בְּעָלְמָא, הֵן טָב הֵן בִּישׁ. וְכֵן הוּא אוֹמֵר, (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לא אֶרְאֶנּוּ נְאֻם יְיָ'.</p>\n<p>אָמַר לֵיהּ רִבִּי יְהוּדָה, כֹּלָּא הָכִי הוּא וַדַּאי. אֲבָל הָא כְּתִיב, (איוב ב׳:ה׳) וְגַע אֶל עַצְמוֹ וְאֶל בְּשָׂרוֹ. וּכְתִיב, (איוב ב׳:ה׳) וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ חִנָּם. לְאַחֲזָאָה דְּהָא רְשׁוּ אִתְמְסָר לְסִטְרָא אַחֲרָא לְקַטְרְגָא, (ורשו אתמסר) עַל מִלִּין דְּעָלְמָא, (למאן דלא אצטריך) וּלְאִתְמַסְּרָא בִּידוֹי. וְכָל אִלֵּין אָרְחִין טְמִירִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְלֵית אַנְתְּ כְּדַאי לְמֵהַךְ אֲבַתְרַיְיהוּ, בְּגִין דְּאִינּוּן נִמּוּסִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְנֵי נָשָׁא לָאו אִינּוּן רַשָּׁאִין לְדַקְדְּקָא אֲבַתְרַיְיהוּ, בַּר אִינּוּן זַכָּאֵי קְשׁוֹט דְּיַדְעִין רָזֵי אוֹרַיְיתָא, וְאָזְלִין בְּאָרְחָא דְּחָכְמְתָא לְמִנְדַּע אִינּוּן מִלִּין סְתִימִין דְּאוֹרַיְיתָא.</p>"],[9520011584,"<p>רִבִּי אֶלְעָזָר פָּתַח, (איוב א׳:ו׳) וַיְהִי הַיּוֹם וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל יְיָ' וַיָּבוֹא גַּם הַשָּׂטָן בְּתוֹכָם. וַיְהִי הַיּוֹם: דָּא (מ\"ד א') רֹאשׁ הַשָּׁנָה, דְּקוּדְשָׁא בְּרִיךְ הוּא קָאִים לְמֵידָן עָלְמָא. כְּגַוְונָא דָּא, (מלכים ב ד׳:י״א) וַיְהִי הַיּוֹם וַיָּבֹא שָׁמָּה. הַהוּא יוֹמָא יוֹם טוֹב דְּרֹאשׁ הַשָּׁנָה הֲוָה.</p>\n<p>וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים, אִלֵּין רַבְרְבִין מְמָנָן שְׁלִיחָן בְּעָלְמָא, לְאַשְׁגְּחָא בְּעוֹבָדִין דִּבְנִי נָשָׁא. לְהִתְיַצֵּב עַל ה': כְּמָה דְּאַתְּ אָמֵר, (מלכים א כ״ב:י״ט) וְכָל צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו מִימִינוֹ וּמִשְּׂמֹאלוֹ. אֲבָל לְהִתְיַצֵּב עַל ה' בְּהַאי קְרָא אַשְׁכַּחְנָא רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ דְּיִשְׂרָאֵל. בְּגִין, דְּהָנֵי שְׁלִיחָן, דְּאִינּוּן מְמָנָן לְאַשְׁגָּחָא עַל עוֹבָדִין דִּבְנֵי נָשָׁא, אַזְלִין וְשָׁאטִין וְנַטְלִין אִינּוּן עוֹבָדִין כֻּלְּהוּ, וּבְיוֹמָא דְּקָאֵי דִּינָא לְמֵיקָם, לְמֵידָן עָלְמָא, אִתְעָבִידוּ קַטֵיגוֹרִין לְמֵיקָם עָלַיְיהוּ דִּבְנֵי נָשָׁא. וְתָא חֲזֵי, מִכָּל עַמִּין דְּעָלְמָא, לָא קַיְימִין לְאַשְׁגָּחָא בְּעוֹבָדֵיהוֹן, בַּר בְּיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, בְּגִין דְּאִלֵּין בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְכַד לָא אִשְׁתְּכָחוּ עוֹבָדִין דְּיִשְׂרָאֵל כְּדְקָא יֵאוֹת, כִּבְיָכוֹל אִינּוּן מְמָנָן שְׁלִיחָן, כַּד בָּעָאן לְקַיְּימָא עַל אִינּוּן עוֹבָדִין דְּיִשְׂרָאֵל, עַל ה' וַדַּאי קַיְימִין, דְּהָא כַּד יִשְׂרָאֵל עַבְדִין עוֹבָדִין דְּלָא כַּשְׁרָן, כִּבְיָכוֹל מַתִּישִׁין חֵילָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְכַד עַבְדִין עוֹבָדִין דְּכַשְׁרָן, יַהֲבִין תּוּקְפָּא וְחֵילָא לְקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (תהילים ס״ח:ל״ה) תְּנוּ עֹז לֵאלֹהִים. בְּמָה. בְּעוֹבָדִין דְּכַשְׁרָן. וְעַל דָּא, בְּהַהוּא יוֹמָא, כֻּלְּהוּ רַבְרְבָן מְמָנָן אִתְכָּנָשׁוּ עַל ה'. עַל ה' וַדַּאי, דְּהָא כֵּיוָן דְּעַל יִשְׂרָאֵל אִתְכָּנָשׁוּ, עָלֵיהּ אִתְכָּנָשׁוּ.</p>\n<p>וַיָּבֹא גַּם הַשָּׂטָן בְּתוֹכָם, גַּם, לְאַסְגָּאָה עָלַיְיהוּ, דְּכֻלְּהוּ אַתְיָין לְמֶהֱוֵי קַטֵיגוֹרִין עָלַיְיהוּ דְּיִשְׂרָאֵל, <Nonei></i>וְדָא אִתּוֹסָף עָלַיְיהוּ, בְּגִין דְּאִיהוּ דַּילְטוֹרָא רַבְרְבָא מִכֻּלְּהוּ, קַטֵיגוֹרָא מִכֻּלְּהוּ, כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא, דְּכֻלְּהוּ אַתְיָין לְקַטְרְגָא. מִיָּד וַיֹּאמֶר יְיָ' אֶל הַשָּׂטָן מֵאַיִן תָּבֹא. וְכִי לא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא, מֵאָן הֲוָה אָתֵי. אֶלָּא לְאַיְיתָאָה עוֹבָדָא לִרְעוּתֵיהּ.</p>\n<p>וַיֹּאמֶר יְיָ' אֶל הַשָּׂטָן וְגוֹ' וַיַּעַן הַשָּׂטָן אֶת יְיָ' וַיֹּאמַר מִשּׁוּט בָּאָרֶץ. מִכָּאן אוֹלִיפְנָא, דְּיִשּׁוּבָא דְּאַרְעָא אִתְמְסָר לְסִטְרִין אַחֲרָנִין, בַּר אַרְעָא דְּיִשְׂרָאֵל בִּלְחוֹדָהָא. כֵּיוָן דְּאָמַר מִשּׁוּט בָּאָרֶץ, אַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא, דְּבָעֵי לְמֶהֱוֵי דַּלְטוֹרָא עָלַיְיהוּ דְּיִשְׂרָאֵל. מִיָּד, (איוב א׳:ח׳) וַיֹּאמֶר יְיָ אֶל הַשָּׂטָן הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב כִּי אֵין כָּמוֹהוּ בָּאָרֶץ.</p>\n<p>חָמָא שַׁעֲתָא לְמֵיהַב לֵיהּ חוּלָקָא, בְּמָה (נח ס\"ד ע\"א) דְּיִתְעֲסַק, וְיִתְפְּרַשׁ מִנַּיְיהוּ דְּיִשְׂרָאֵל, וְהָא אוּקְמוּהָ, לְרַעְיָא דְּבָעָא לְמֶעְבַּר עָאנֵיהּ בְּחַד נַהֲרָא וְכוּ', מִיַּד אִתְעַסַּק בֵּיהּ הַהוּא שָׂטָן, וְלֹא קִטְרֵג עָלַיְיהוּ דְּיִשְׂרָאֵל.</p>\n<p>וַיַּעַן הַשָּׂטָן אֶת יְיָ וַיֹּאמַר הֲחִנָּם יָרֵא אִיּוֹב אֱלֹהִים. לָאו תָּוָוהָא לְעַבְדָּא דְּמָארֵיהּ עָבִיד לֵיהּ כָּל רְעוּתֵיהּ, דִּיהֵא דָּחִיל לֵיהּ, אַעְדֵּי אַשְׁגָּחוּתָךְ מִנֵיהּ, וְתֶחמֵי אִי דָּחִיל לָךְ וְאִם לָאו.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּעָאקוּ, כַּד אִתְיְיהִב חוּלָקָא חֲדָא לְהַאי סְטָר לְאִתְעַסְּקָא בֵּיהּ, אִתְפְּרִישׁ לְבָתַר מִכֹּלָּא. כְּגַוְונָא דָּא שָׂעִיר בְּרֹאשׁ חוֹדֶשׁ. שָׂעִיר בְּיוֹמָא דְּכִפּוּרֵי. בְּגִין דְּאִתְעַסַּק בֵּיהּ, וְשָׁבִיק לְהוּ לְיִשְׂרָאֵל בְּמַלְכֵיהוֹן, וְהָכָא, מָטָא זִמְנָא לְמֵיטָל חוּלָקָא דָּא, מִכָּל זַרְעָא דְּאַבְרָהָם, בְּסִטְרָא אַחֲרָא. כְּמָה דְּאַתְּ אָמֵר, (בראשית כ״ב:כ׳) הִנֵּה יָלְדָה מִלְכָּה גַּם הִיא וְגוֹ' אֶת עוּץ בְּכוֹרוֹ וְגוֹ'.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּאָמַר מִשּׁוּט בָּאָרֶץ, בָּעָא מִינֵּיהּ, לְמֶעְבַּד דִּינָא בְּיִשְׂרָאֵל, דְּהָא דִּינָא הֲוָה לֵיהּ עַל אַבְרָהָם, לְמִתְבַּע מְקּוּדְשָׁא בְּרִיךְ הוּא. בְּגִין, דְּלָא אִתְעָבִיד דִּינָא בְּיִצְחָק, כַּד אִתְקְרִיב עַל גַּבֵּי מַדְבְּחָא, דְּהָא לָא הֲוָה לֵיהּ לְאַחְלְפָא קָרְבְּנָא דְּאַזְמִין עַל מַדְבְּחָא, בָּאֳחָרָא, (וכן בכל סטרא דליה) כְּמָה דְּאַתְּ אָמַר, (ויקרא כ\"ז) לא יַחֲלִיפֶנּוּ. וְהָכָא קָאִים יִצְחָק עַל גַּבֵּי מַדְבְּחָא, וְלָא אִשְׁתְּלִים מִנֵּיהּ קָרְבְּנָא, וְלָא אִתְעָבִיד בֵּיהּ דִּינָא, וּבָעָא דָּא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּבָעָא דִּינִיהּ דְּיוֹסֵף לְכַמָּה דָּרִין. וְכָל מַה דְּבָעָא, בְּאוֹרַח דִּינָא בָּעָא.</p>\n<p>וּמֵהַהוּא זִמְנָא דְּאִשְׁתְּזִיב יִצְחָק, וְאִתְחַלַּף קָרְבָּנֵיהּ, זַמִּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לְהַהוּא מְקַטְרְגָא, הַאי לְחוּלָקֵיהּ, כְּמָה דְּאַתְּ אָמֵר הִנֵּה יָלְדָה מִלְכָּה גַּם הִיא וְגוֹ' אֶת עוּץ בְּכוֹרוֹ. וְהָכָא, מָטָא לְמֵיטָל חוּלָקֵיהּ עָלֵיהּ, מִכָּל זַרְעֵיהּ דְּאַבְרָהָם, וְלָא יִקְרַב בְּסִטְרָא אַחֲרָא.</p>\n<p>וְכֹלָּא בְּדִינָא אָתָא. (ס\"א לגביה) כְּמָה דְּאִיהוּ דָּן, הָכִי אִתְּדָן. בְּגִין דְּאִיּוֹב מִקְּרִיבֵי עֵיטָא דְּפַרְעֹה הֲוָה, וְכַד קָם פַּרְעֹה עָלַיְיהוּ דְּיִשְׂרָאֵל, בָּעָא לְקָטְלָא לוֹן. אָמַר לֵיהּ לָא, אֶלָּא טוֹל מָמוֹנֵהוֹן וּשְׁלוֹט עַל גּוּפֵיהוֹן, בְּפוּלְחָנָא קַשְׁיָא, וְלָא תִּקְטוֹל לוֹן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, חַיֶּיךָ, בְּהַהוּא דִּינָא מַמָּשׁ, תְּהֵא דָּאִין, מַה כְּתִיב, (איוב ב׳:ה׳) אוּלָם שְׁלַח נָא יָדְךָ וְגַע אֶל עַצְמוֹ וְאֶל בְּשָׂרוֹ וְגוֹ'. בְּמָה דְּאִיהוּ דָּן, הָכִי אִתְּדָן. וְאַף עַל גַּב דִּבְכָל שְׁאַר הֲוָה דָּחִיל לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, אַךְ אֶת נַפְשׁוֹ שְׁמוֹר. וְאִתְיְהִיב לֵיהּ רְשׁוּ, לְמִשְׁלַט עַל בִּשְׂרָא, בְּגִין רָזָא דִּכְתִּיב, (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְאוּקְמוּהָ, בָּא לְפָנַי וַדַּאי, וְדָא אִיהוּ (שלח ק\"ט ע\"א) קֵץ כָּל בָּשָׂר, וְלֹא רוּחָא. וְאִיתְּמַר, דְּאִיהוּ קֵץ דְּאָתֵי מִסִּטְרָא דְּחֹשֶׁךְ, כְּמָה דְּאַתְּ אָמֵר, (איוב כ״ח:ג׳) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר. וּלְכָל בִּשְׂרָא, בְּגִין דְּאִית קֵץ אַחֲרָא, וְאִקְרֵי (דניאל י\"ב) קֵץ הַיָּמִין, וְדָא אִיהוּ קֵץ אַחֲרָא, מִסִּטְרָא דִּשְׂמָאלָא, דְּאִיהוּ חֹשֶׁךְ. וְעַל דָּא אִתְיְיהִיב לֵיהּ רְשׁוּ בְּעַצְמוֹ וּבְשָׂרוֹ.</p>\n<p>וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ. אִי הָכִי, לָאו בְּדִינָא הֲוָה, אֶלָּא בְּמֵימַר הַהוּא מְקַטְרְגָא, דְּאָסִית לֵיהּ, וְאַסְטֵי לֵיהּ. אֶלָּא, כֹּלָּא בְּדִינָא הֲוָה, וְהָכִי אָמַר לוֹ אֱלִיהוּא, (איוב ל״ד:י״א) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִיאֶנּוּ. וְהָכִי הֲוָה כְּמָה דְּאִתְּמַר, כְּמָה דְּאִיהוּ גָּזַר, הָכִי אִתְגְּזַר עָלֵיהּ.</p>\n<p>וְהַאי דְּאָמַר וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ חִנָּם, וַתְּסִיתֵנִי לְבַלְּעוֹ לָא כְּתִיב, אֶלָּא וַתְּסִיתֵנִי בוֹ, בֵּיהּ קַיְּימָא בְּדַעְתֵּיהּ, דְּאִיהוּ חָשִׁיב דְּהָא תְּסִיתֵנִי, כְּמָה דְּאָמַר (איוב י׳:ג׳) וְעַל עֲצַת רְשָׁעִים הוֹפָעְתָּ. (אמר איוב אתפתית על מימר דההוא מקטרגא) כְּגַוְונָא דָּא, (תהלים ע\"ה) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוּ לוֹ. וַיְפַתּוּהוּ וַיְכַזְּבוּ לוֹ. לָא כְּתִיב, אֶלָּא וַיְפַתּוּהוּ בְּפִיהֶם. בְּפִיהֶם קַיְּימָא מִלָּה דָּא דְּהָא אִתְפַּתָּה.</p>\n<p><Nonei></i>אָמַר רִבִּי אַבָּא, כֹּלָּא הוּא שַׁפִּיר, אֲבָל הָכִי אוֹלִיפְנָא, דִּתְנָן, סָלִיק וְאַסְטִין. וְכִי אִיהוּ יָכִיל לְאַסְטָנָא, אִין. דְּהָא אִיהוּ (ריש וישב תיקון קמ\"א) מֶלֶךְ זָקֵן וּכְסִיל, דִּכְתִּיב, (קהלת ד׳:י״ג) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל. וְעַל דָּא, יָכִיל לְאַסְטָנָא לְבַר נָשׁ. מַאי טַעֲמָא. בְּגִין דְּאִיהוּ מְהֵימָן עַל עוֹבָדוֹי דִּבְנֵי נָשָׁא.</p>\n<p>תָּא חֲזֵי, הַאי בְּדִינָא דְּיָחִיד, אֲבָל בְּדִינָא דְּעָלְמָא, כְּתִיב, (בראשית י\"א) וַיֵּרֶד יְיָ' לִרְאוֹת. (בראשית י״ח:כ״א) אֵרַדָה נָּא וָאֶרְאֶה. דְּלָא אִתְיְיהִיב מְהֵימָנוּתָא אֶלָּא בִּידֵיהּ בִּלְחוֹדוֹי, דְּהָא לָא בָּעָא לְאוֹבָדָא עָלְמָא, עַל מֵימָר דְּהַהוּא מְקַטְרְגָא, דְּתִיאוּבְתֵּיהּ אִיהוּ תָּדִיר לְשֵׁיצָאָה. מְנָלָן דִּכְתִּיב, (איוב כ״ח:ג׳) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר. לְשֵׁיצָאָה כֹּלָּא, הוּא חוֹקֵר. וְדָא אִיהוּ קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וַדַּאי בְּגִין לְשֵׁיצָאָה.</p>\n<p>וְתָּא חֲזֵי, וַיְהִי הַיּוֹם וַיָּבוֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל יְיָ'. כְּמָה דְּאִתְּמַר. וְהַהוּא יוֹמָא, קַיְימִין תְּרֵין סִטְרִין, לְקַבְּלָא בְּנִי עָלְמָא. כָּל אִינּוּן דְּאַתְיָין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא בִּתְיוּבְתָּא וּבְעוֹבָדִין טָבִין, אִינּוּן זַכְיָן לְמֶהֱוֵי כְּתִיבִין לְגַבֵּיהּ דְּהַהוּא סִטְרָא דְּאִיהוּ חַיִּים, וְאַפִּיק תּוֹצְאוֹת חַיִּים. וּמַאן דְּאִיהוּ מִסִּטְרֵיהּ, אַכְתִּיב לְחַיִּים. וְכָל אִינּוּן דְּאַתְיָין בְּעוֹבָדִין בִּישִׁין, אִינּוּן כְּתִיבִין לְהַהוּא סִטְרָא אַחֲרָא דְּאִיהוּ מוֹתָא, וְאִקְרֵי (רס\"ה א') מָוְת, וּבֵיהּ שַׁרְיָא מוֹתָא.</p>\n<p>וּבְהַהוּא יוֹמָא, קַיְימִין אִלֵּין תְּרֵין סִטְרִין: חַיִּים, וּמָוֶת. אִית מַאן דְּאַכְתִּיב לְסִטְרָא דְּחַיִּים. וְאִית מַאן דְּאַכְתִּיב לְסִטְרָא דְּמָוֶת. וּלְזִמְנִין דְּעָלְמָא שַׁרְיָא בְּאֶמְצָעִיתָא, אִי קַיְּימָא חַד זַכָּאָה בְּעָלְמָא, דְּאַכְרַע עָלַיְיהוּ, כֻּלְּהוּ קַיְימִין וְאַכְתִּיבוּ לְחַיִּים. וְאִי חַד חַיָּיבָא אַכְרַע עָלְמָא, כֻּלְּהוּ אַכְתִּיבוּ לְמִיתָה.</p>\n<p>וְהַהוּא זִמְנָא, עָלְמָא הֲוָה קַיָּים בְּאֶמְצָעִיתָא, וְהַהוּא מְקַטְרְגָא בָּעָא לְאַסְטָאָה. מִיָּד מַה כְּתִיב, הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב כִּי אֵין כָּמוֹהוּ בָּאָרֶץ וְגוֹ'. כֵּיוָן דְּאִשְׁתְּמוֹדָע אִיהוּ בִּלְחוֹדוֹי, מִיַּד אַתְקִיף בֵּיהּ מְקַטְרְגָא. וְעַל דָּא תָּנֵינָן, דְּלָא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְאִתְפָּרְשָׁא מִכְּלָלָא דְּסַגִּיאִין, בְּגִין דְּלָא יִתְרְשִׁים אִיהוּ בִּלְחוֹדוֹי, וְלָא יְקַטְרְגוּן עָלֵיהּ לְעֵילָּא.</p>\n<p>דִּכְתִּיב, בַּשּׁוּנַמִּית, (מלכים ב ד׳:י״ג) וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. לָא בְּעֵינָא לְאַפָּקָא גַּרְמָי מִכְּלָלָא דְּסַגִּיאִין, בְּתוֹךְ עַמִּי יָתִיבְנָא, עַד יוֹמָא דָּא, וּבְתוֹךְ עַמִּי, בִּכְלָלָא חֲדָא אִשְׁתְּמוֹדָע לְעֵילָּא. וְהָכָא אִיּוֹב, כֵּיוָן דְּאִשְׁתְּמוֹדָע לְעֵילָּא וְאִתְרְשִׁים, מִיַּד אַתְקִיף בֵּיהּ מְקַטְרְגָא, וְאָמַר הֲחִנָּם יָרֵא אִיּוֹב אֱלהִים, כָּל מַה דְּדָחִיל לָךְ וְאִתְתָּקַף, לָאו לְמַגָּנָא עָבִיד, הֲלֹא אַתָּה שַׂכְתָּ בַעֲדוֹ וּבְעַד וְגוֹ'. אֲבָל טוֹל כָּל הַאי טָבָא דְּאַנְתְּ עָבֵד לֵיהּ, וּמִיָּד אִם לא עַל פָּנְיךָ יְבָרְכֶךָּ. יִשְׁבּוֹק לָךְ, וְיִתְדַּבַּק בְּסִטְרָא אַחֲרָא, דְּהָא הַשְׁתָּא בְּפָתוֹרָךְ אִיהוּ אָכִיל, סָלִיק פָּתוֹרָךְ מִנֵיהּ, וְנֶחֱזֵי מִמָּאן אִיהוּ, וּבְאָן סִטְרָא יִתְדַּבַּק.</p>\n<p>מִיָּד, וַיֹּאמֶר יְיָ אֶל הַשָּׂטָן הִנֵּה כָל אֲשֶׁר לוֹ בְּיָדֶךָ. לְאַחֲזָאָה, דִּדְחִילוּ דְּאִיּוֹב לְגַבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, הוּא לְנַטְרָא עוּתְרֵיהּ. וּמֵהָכָא אוֹלִיפְנָא, דְּכָל אִינּוּן דְּדַחֲלִין לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, עַל עוּתְרַיְיהוּ, אוֹ עַל בְּנַיְיהוּ, לָאו אִיהוּ דְּחִילוּ כְּדְקָא יֵאוֹת. וְעַל דָּא קִטְרֵג הַהוּא מְקַטְרְגָא וְאָמַר, הֲחִנָּם יָרֵא אִיּוֹב אֱלֹהִים הֲלא אַתָּה שַׂכְתָּ בַעֲדוֹ וְגוֹ' מַעֲשֵׂה יָדָיו בֵּרַכְתָּ. וְעַל דָּא אִיהוּ דָּחִיל לָךְ וְאִתְיְיהִיב לֵיהּ רְשׁוּ לְקַטְרְגָא בֵּיהּ, וּלְאַחֲזָאָה, דְּלָא פָּלַח אִיּוֹב לְקוּדְשָׁא בְּרִיךְ הוּא בִּרְחִימוּ.</p>\n<p>דְּכֵיוָן דְּאִתְנַסֵּי, נָפַק מֵאוֹרְחָא, וְלָא קָאִים בְּקִיוּמֵיהּ, מַה כְּתִיב, בְּכָל זֹאת לא חָטָא אִיּוֹב בִּשְׂפָתָיו. לֹא חָטָא בִּשְׂפָתָיו אֲבָל בִּרְעוּתֵיהּ חָטָא, וּלְבָתַר חָטָא בְּכֹלָּא.</p>\n<p>וְאִי תֵּימָא דְּלָא אִתְנַסֵּי בַּר נָשׁ, הָא כְּתִיב (תהילים י״א:ה׳) ה' צַדִּיק יִבְחָן וְגוֹ'. וּבְגִין כַּךְ אִתְנַסֵּי אִיּוֹב. וְאַף עַל גַּב דְּלָא קָאִים בְּקִיוּמֵיהּ כְּדְקָא יֵאוֹת, לָא נָפַק מִתְּחוֹת רְשׁוּתָא דְּמָרֵיהּ לְאִתְדַּבְּקָא בְּסִטְרָא אַחֲרָא.</p>\n<p>וְכַמָּה הֲוָה הַהוּא נִסּוּתָא דִּילֵיהּ. תְּרֵיסַר יַרְחֵי, שׁוּלְטָנוּתָא דְּהַהוּא סִטְרָא אַחֲרָא. כְּמָה דְּתָנֵינָן, דִּינָא דְּחַיָּבַיָא בַּגֵּיהִנָּם י\"ב יַרְחֵי, וּבְגִין דְּלָא אִתְדַּבַּק בְּסִטְרָא אַחֲרָא כְּתִיב, (איוב מ״ב:י״ב) וַיְיָ' בֵּרַךְ אֶת <Nonei></i>אַחֲרִית (נדפס קפ\"א ע\"ב) אִיּוֹב מֵרֵאשִׁיתוֹ.</p>\n<p>ר' שִׁמְעוֹן אָמַר, הַאי דְּאִיּוֹב, לָאו נִסּוּתָא אִיהוּ דְקוּדְשָׁא בְּרִיךְ הוּא, כְּנִסוּתָא דִּשְׁאַר צַדִּיקַיָּא, דְּהָא לָא כְּתִיב וְהָאֱלֹהִים נִסָּה אֶת אִיּוֹב, כְּמָה דִּכְתִּיב, (בראשית כ״ב:א׳) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. דְּאַבְרָהָם, אִיהוּ בִּידֵיהּ אַקְרִיב לִבְרֵיהּ יְחִידָאי דִּילֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִיּוֹב לָא יָהִיב כְּלוּם, וְלָא מָסַר לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא כְּלוּם.</p>\n<p>וְלָא אִתְּמַר לֵיהּ, דְּהָא גַּלֵּי קָמֵיהּ, דְּלָא יָכִיל לְקַיְּימָא בֵּיהּ, אֲבָל אִתְמְסָר בִּידָא דִּמְקַטְרְגָא. וּבְדִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעָבִיד, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר דִּינָא (בדינא) דָּא, לְהַהוּא מְקַטְרְגָא לְגַבֵּיהּ, הֲדָא הוּא דִכְתִיב, (איוב א׳:ח׳) הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב וְגוֹ'.</p>\n<p>פָּתַח וְאָמַר, (בראשית ד׳:ג׳) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה. מִקֵּץ יָמִים, וְלא מִקֵּץ יָמִין. אִיהוּ דָּחָה לְקֵץ יָמִין, וְאִתְקְרִיב לְקֵץ יָמִים. וְהָא אוֹקִימְנָא, (דניאל י״ב:י״ג) וְאַתָּה לֵךְ לְקֵץ. וְאָמַר דָּנִיאֵל, לְאָן קֵץ, לְקֵץ הַיָּמִין, אוֹ לְקֵץ הַיָּמִים. עַד דְּאֲמַר לֵיהּ לְקֵץ הַיָּמִין. וְעַל דָּא דָּוִד דָּחִיל וְאָמַר, (תהילים ל״ט:ה׳) הוֹדִעֵנִי יְיָ' קִצִּי וּמִדַּת יָמַי מַה הִיא, אוֹ לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין. וְהָכָא מַה כְּתִיב וַיְהִי מִקֵּץ יָמִים, וְלֹא מִקֵּץ יָמִין, וּבְגִין כָּךְ לָא אִתְקַבַּל קָרְבָּנֵיהּ, דְּהָא מִסִּטְרָא אַחֲרָא הֲוָה. (כלא)</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וְהֶבֶל הֵבִיא גַּם הוּא. מַאי גַּם הוּא. לְאַסְגָּאָה דָּא בְּדָא, קָרְבָּנֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה כֹּלָּא, וְעִקָרָא דְּקָרְבְּנָא לְּקוּדְשָׁא בְּרִיךְ הוּא, וְיָהַב חוּלָקָא לְסִטְרָא אַחֲרָא, כְּמָה דְאַתְּ אָמֵר וּמֵחֶלְבֵיהֶן. וְקַיִן, עִקָרָא עָבֵד מִקֵּץ יָמִים, רָזָא דְּסִטְרָא אַחֲרָא, וְיָהִיב חוּלָקָא לְּקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא לָא אִתְקַבַּל.</p>\n<p>בְּאִיּוֹב מַה כְּתִיב, (איוב א׳:ד׳) וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ', וְשָׁלְחוּ וְקָרְאוּ לִשְׁלֹשֶׁת אַחְיוֹתֵיהֶם לֶאֱכֹל וְלִשְׁתּוֹת עִמָּהֶם וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה וְגוֹ', וּבְמִשְׁתְּיָא בְּכָל יוֹמָא מְקַטְרְגָא שְׁכִיחַ, וְלָא יָכִיל לֵיהּ. מְנָא לָן. דִּכְתִּיב, (איוב א׳:י׳) הֲלֹא אַתָּה שַׂכְתָּ בַעֲדוֹ וּבְעַד בֵּיתוֹ וּבְעַד כָּל אֲשֶׁר לוֹ מִסָּבִיב וּלְעוֹלָם לָא יָהִיב חוּלָקָא כְּלָל לְגַבֵּיהּ, דְּהָא (נ\"א מה) כְּתִיב (איוב א׳:ה׳) וְהֶעֱלָה עוֹלוֹת מִסְפַּר כּוּלָּם. עוֹלָה סַלְּקָא לְעֵילָּא לְעֵילָּא, וְלָא יָהִיב חוּלָקָא לְסִטְרָא אַחֲרָא. דְּאִלְמָלֵא יָהַב לֵיהּ חוּלָקָא, לָא יָכִיל לֵיהּ לְבָתַר, וְכָל מַה דְּנָטַל מִדִּילֵיהּ נָטַל.</p>\n<p>וְאִי תֵּימָא אֲמַאי אַבְאִישׁ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא. דְּאִלְמָלֵא יָהַב לֵיהּ חוּלָקָא, יִפְנִי אָרְחָא וְיִסְתְּלַק מֵעַל מַקְדְּשָׁא, וְסִטְרָא דִּקְדוּשָּׁה אִסְתְּלִיק לְעֵילָּא לְעֵילָּא. וְאִיהוּ לָא עָבֵד כֵּן, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא תָּבַע בְּדִינָא.</p>\n<p>תָּא חֲזֵי, כְּמָה דְּאִיהוּ אִתְפְּרַשׁ, וְלָא אַכְלִיל טוֹב וָרָע, אִיהוּ דָּן לֵיהּ בְּהַהוּא גַּוְונָא, יָהִיב לֵיהּ טוֹב, וּלְבָתַר רָע, וּלְבָתַר אֲהַדְרֵיהּ לְטוֹב. דְּהָכִי אִתְחָזֵי לְבַּר נָשׁ, לְמִנְדַּע טוֹב, וּלְמִנְדַּע רַע, וּלְאַהְדָּרָא גַּרְמֵיהּ לְטוֹב, וְדָא אִיהוּ רָזָא דִּמְהֵימָנוּתָא. תָּא חֲזֵי, אִיּוֹב מֵעַבְדֵי פַּרְעֹה הֲוָה, וְדָא הוּא דִּכְתִּיב בֵּיהּ, (שמות ט׳:כ׳) הַיָּרֵא אֶת דְּבַר יְיָ' מֵעַבְדֵי פַּרְעֹה. תָּא חֲזֵי, דְלָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲקַרָא אִיּוֹב מֵאַתְרֵיהּ דְּאִיהוּ הַוָה מִכְסֵי (נ\"א כולא בעא קודשא בהך הוא לאעקרא מאתרייהו איוב הוה מכסי) (נ\"א איוב חכים הוה) עַל פַּרְעֹה כֵּיוָן דְאִתְחַלָשׁ עָבַד נוּקְמִין לְפַרְעֹה</p>"],[9520011585,"<p>אָמַר רִבִּי שִׁמְעוֹן, הַשְׁתָּא אִית לְגַלָּאָה רָזִין, דְּאִינּוּן מִתְדַּבְּקִין לְעֵילָּא וְתַתָּא, מַה כְּתִיב בֹּא אֶל פַּרְעֹה, לֵךְ אֶל פַּרְעֹה מִבָּעֵי לֵיהּ, מַאי בֹּא. אֶלָּא, דְּעָיִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִדָּרִין בָּתַר אִדָּרִין, לְגַבֵּי תַּנִּינָא חֲדָא עִלָּאָה תַּקִּיפָא, דְּכַמָּה דַּרְגִּין מִשְׁתַּלְשְׁלֵין מִנֵּיהּ. וּמַאן אִיהוּ. רָזָא דְּהַתַּנִּין הַגָּדוֹל.</p>\n<p>וּמֹשֶׁה דָּחִיל מִנֵּיהּ, וְלָא קָרִיב אֶלָּא לְגַבֵּי אִינּוּן יְאוֹרִין, וְאִינּוּן דַּרְגִּין דִּילֵיהּ, אֲבָל לְגַבֵּיהּ דָּחִיל וְלָא קָרִיב, בְּגִין דְּחָמָא לֵיהּ מִשְׁתָּרִשׁ בְּשָׁרָשִׁין עִלָּאִין.</p>\n<p>כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא דְּדָחִיל מֹשֶׁה, וּשְׁלִיחָן מְמָנָן אַחֲרָנִין לְעֵילָּא, לָא יַכְלִין לְקָרְבָא לְגַבֵּיהּ. אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, (יחזקאל כ״ט:ג׳) הִנְנִי עָלֶיךָ פַּרְעֹה מֶלֶךְ מִצְרָיִם הַתַּנִּים הַגָּדוֹל הָרוֹבֵץ בְּתוֹךְ יְאוֹרָיו. וְקוּדְשָׁא בְּרִיךְ הוּא אִצְטְרִיךְ לְאַגָּחָא בֵּיהּ קְרָבָא, וְלֹא אַחֲרָא. כְּמָה דְּאַתְּ אָמַר, אֲנִי ה', וְאוּקְמוּהָ רָזָא דְּחָכְמְתָא דְּהַתַּנִּים הַגָּדוֹל הָרוֹבֵץ בְּתוֹךְ יְאוֹרָיו לְאִינוּן מָארֵי מִדִּין, דְּיַדְעִין בְּרָזִין דְּמָארֵיהוֹן.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית א׳:כ״א) וַיִּבְרָא אֱלהִים אֶת הַתַּנִּינִם הַגְּדוֹלִים וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרוֹמֶשֶׂת אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵיהֶם. הַאי קְרָא אוּקְמוּהָ לֵיהּ. אֲבָל וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִים הוּא רָזָא דָּא <Nonei></i>לִוְיָתָן וּבַת זוּגוֹ. (קע\"ו ע\"ב) תַּנִּינִם חָסֵר כְּתִיב, בְּגִין דְּקָטַל לְנוּקְבָּא, וְסַלְּקָא קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּא. וְאוּקְמוּהָ.</p>\n<p>הַתַּנִּים הַגָּדוֹל, תֵּשַׁע יְאוֹרִין אִינּוּן, דְּאִיהוּ רָבִיץ בֵּינַיְיהוּ, וְחַד יְאוֹרָא אִיהוּ, דְּמֵימָיו שְׁכִיכִין, וּבְרֵכָאן דְּמֵימִין דְּגִנְתָּא, נַפְלִין בֵּיהּ תְּלַת זִמְנִין בְּשַׁתָּא. וְכַד תְּרֵין זִמְנִין, מִתְבָּרֵךְ הַהוּא יְאוֹרָא וְלא כָּל כַּךְ, וְכַד חַד לָאו הָכִי.</p>\n<p>וְהַאי תַּנִּינָא, עָאל בְּהַהוּא יְאוֹרָא, אִתְתָּקִיף וְאָזִיל וְשָׁאט עָאל גּוֹ יַמָּא, וּבָלַע נוּנִין לְכַמָּה זִינִין, וְשָׁלִיט, וְתָב לְהַהוּא יְאוֹרָא. אִלֵּין תִּשְׁעָה יְאוֹרִין אַזְלִין וְסַלְּקִין וְסַחֲרָנֵיהּ כַּמָּה אִילָנִין. וַעֲשָׂבִין לְזִנַיְיהוּ.</p>\n<p>יְאוֹרָא קַדְמָאָה, נָפְקָא מִסִּטְרָא שְׂמָאלָא, בְּחַד צִנּוֹרָא דְּנָגִיד וְנָפִיק, תְּלַת טִפִּין, וְכָל טִפָּה וְטִפָּה אִתְפְּרַשׁ לִתְלַת טִפִּין, וְכָל טִפָּה וְטִפָּה אִתְעָבִיד מִנֵּיהּ יְאוֹרָא חַד, וְאִלֵּין אִינּוּן תִּשְׁעָה יְאוֹרִין, דְּמִתְתָּקְפִין וְאַזְלִין וְשָׁטָאן וְסָחֲרָן בְּכָל אִינּוּן רְקִיעִין.</p>\n<p>מִמַּה דְּאִשְׁתְּאַר מֵאִינּוּן טִפִּין כַּד סַיְימִין לְמֵיפַק, אִשְׁתְּאַר טִפָּה חֲדָא, דְּנָפְקָא בִּשְׁכִיכוּ, נָפַל בֵּינַיְיהוּ, וְאִתְעָבִיד מִנֵּיהּ יְאוֹרָא חֲדָא. הַאי יְאוֹרָא אִיהוּ, הַהוּא דְּאַמָרָן דְּאַזְלָא בִּשְׁכִיכוּ.</p>\n<p>הַאי יְאוֹרָא, כַּד הַהוּא נָהָר דְּנָגִיד וְנָפִיק, אַפִּיק טִפִּין אַחֲרָנִין רַבְרְבָא (ס\"א דברכאן') מִסִּטְרָא דִּימִינָא, מַה דְּאִשְׁתְּאַר מֵאִינּוּן טִפִּין, אִשְׁתְּאַר טִפָּה חֲדָא בִּשְׁכִיכוּ מֵאִינּוּן בִּרְכָּאן, וְנָפַל בְּהַהוּא יְאוֹרָא דְּאִיהוּ שָׁכִיךְ. וְהַאי אִיהוּ יְאוֹרָא דְּעָדִיף מִכֻּלְּהוּ.</p>\n<p>כַּד נָפְקִין וּמִתְפָּרְשָׁן אִינּוּן אַרְבַּע נַהֲרִין דְּנָפְקִין מִגִּנְתָּא דְּעֵדֶן, הַהוּא דְּאִקְרֵי פִּישׁוֹן, נָפִיל בְּהַהוּא יְאוֹרָא וְאִתְכְּלִיל בֵּיהּ. וְעַל דָּא מַלְכוּת בָּבֶל, אִתְכְּלִיל בְּהַאי. וּפִישׁוֹן אִיהוּ מַלְכוּת בָּבֶל. מִיְאוֹרָא דָּא אִתְּזָנוּ וְאִתְמַלְיָין כָּל אִינּוּן יְאוֹרִין אַחֲרָנִין.</p>\n<p>בְּכָל יְאוֹרָא וִיאוֹרָא, אַזְלָא וְשָׁאט חַד תַּנִּינָא, וְאִינּוּן תֵּשַׁע. וְכָל חַד וְחַד נָקִיב נוּקְבָּא בְּרֵישֵׁיהּ, כְּמָה דְאַתְּ אָמֵר, (תהילים ע״ד:י״ג) שִׁבַּרְתָּ רָאשֵׁי תַנִּינִים וְגוֹ'. וַאֲפִילּוּ הַאי הַתַּנִּין הַגָּדוֹל הָכִי הוּא, בְּגִין דְּכֻלְּהוּ נַפְחִין רוּחִין לְגַבֵּי עֵילָּא וְלא לְתַתָּא.</p>\n<p>כְּתִיב (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלהִים. וּכְתִיב וַיִּבְרָא אֱלהִים אֶת הַתַּנִּינִים הַגְּדוֹלִים, בְּכָל עוֹבָדָא דְּאִינּוּן עֶשֶׂר אֲמִירָן, קַיְימִין לְקָבְלַיְיהוּ אִינּוּן עֶשֶׂר יְאוֹרִין. וְחַד תַּנִּינָא מִתְפָּרְפֶּרָא (ס\"א מתפרשא) (ס\"א מתרפרפא) בְּרוּחָא, לְקָבֵל כָּל חַד וְחַד.</p>\n<p>וְעַל דָּא, חַד לְשִׁבְעִין שְׁנִין מִזְדַעְזָע עָלְמָא, בְּגִין דְּהַאי הַתַּנִּין הַגָּדוֹל כַּד הוּא סָלִיק סְנַפִּירוֹי וְאִזְדַּעְזַע, כְּדֵין כֻּלְּהוּ מִזְדַּעְזְעָן בְּאִינּוּן יְאוֹרִין, וְכָל עָלְמָא מִזְדַּעְזְעָא, וְאַרְעָא מִתְחַלְחֱלֶת, וְכֻלְּהוּ כְּלִילָן בְּהַאי תַּנִּין הַגָּדוֹל.</p>\n<p>וְהָאָרֶץ הָיְתָה תוֹהוּ וְגוֹ', אָמַר רִבִּי שִׁמְעוֹן, עוֹבָדָא דִּבְרֵאשִׁית, חַבְרַיָּא לָעָאן בֵּיהּ, וְיַדְעִין בֵּיהּ, אֲבָל זְעִירִין אִינּוּן, דְּיַדְעִין לְרַמְּזָא עוֹבָדָא דִּבְרֵאשִׁית, בְּרָזָא דְּתַנִּין הַגָּדוֹל. וְעַל דָּא תָּנֵינָן, דְּכָל עָלְמָא לָא מִשְׁתַּלְשְׁלָא אֶלָּא עַל סְנַפִּירוֹי דְּדָא.</p>\n<p>תָּא חֲזֵי וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְגוֹ', תָּנֵינָן הָיְתָה, וְאוֹקִימְנָא. בְּגִין דִּבְּהַאי יְאוֹרָא קַדְמָאָה דְּקַאמְרָן, כַּד הַאי הַתַּנִּין הַגָּדוֹל עָאל בֵּיהּ, כְּדֵין אִתְמַלְיָיא, וְשָׂאטִי וְדָעִיךְ נִיצוֹצִין דְּאִתְלְקָטוּ בְּאִינּוּן עָלְמִין דְּאִתְחֲרָבוּ בְּקַדְמִיתָא.</p>\n<p>אִינּוּן תַּנִּינִין אַחֲרָנִין דְּקַאמְרָן, הֲווֹ וְלָא הֲווֹ, אֲמַאי. בְּגִין דְּאִתְחֲלָשׁ חֵילַיְיהוּ דְּלָא יְטַשְׁטְשׁוּן עָלְמָא, בַּר לְשִׁבְעִין שְׁנִין, חַד זִמְנָא, וְאִינּוּן אִתְתְּקָפוּ בְּחֵילָא דְּהַהוּא תַּנִּין הַגָּדוֹל, וְהַאי אִיהוּ בִּלְחוֹדוֹי לְאִתַּתְקְפָא. וְאִלְמָלֵא נוּקְבֵיהּ קַיֶּימֶת לְגַבֵּיהּ, לָא יָכִיל עָלְמָא לְמִסְבַּל לוֹן. (ובגין כך)</p>\n<p>עַד לָא קָטַל קוּדְשָׁא בְּרִיךְ הוּא לְנוּקְבָּא, הָאָרֶץ הָיְתָה תֹהוּ. (ובהו) תֹהוּ הָיְתָה. וּלְבָתַר דְּקָטַל לָהּ, הֲוָה (בראשית ע' ע\"א) בֹּהוּ, שָׁרָאת לְאִתְקַיְּימָא. וְחֹשֶׁךְ עַל. עַד לָא הֲוַת נְהִירָא עוֹבָדָא דְּעָבַד.</p>\n<p>מֶה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, מָחַץ רֵישֵׁיהּ דִּדְכוּרָא לְעֵילָּא, וְאִתְכַּפְיָא, בְּגִין דְּהָא תְּהוֹמָא לְתַתָּא, לָא הֲוָה נָהִיר. מַאי טַעְמָא לָא הֲוָה נָהִיר, בְּגִין דְּהַאי הַתַּנִּין הַגָּדוֹל, הֲוָה נָשִׁיב רוּחָא עַל תְּהוֹמָא, וְאַחְשִׁיךְ לֵיהּ, וְלָא מְרַפְרְפָא לְתַתָּא.</p>\n<p>וְעָבַר (נ\"א ועם כל דא) רוּחָא אַחֲרָא דִּלְעֵילָּא, וְנָשַׁב (נ\"א דנשב) וּבָטַשׁ בְּהַהוּא רוּחָא, וְשָׁכִיךְ לֵיהּ, הֲדָא הוּא דִּכְתִּיב וְרוּחַ אֱלהִים מְרַחֶפֶת עַל פְּנִי הַמָּיִם. וְהַיְינוּ דְּתָנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּטַשׁ רוּחָא בְּרוּחָא, וּבָרָא עָלְמָא.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, נָהִיר נְהִירוּ דִּלְעֵילָּא, וּבָטַשׁ <Nonei></i>עַל גַּבֵּי רוּחָא דְּנָשִׁיב, וְאִסְתַּלָּק מֵעַל תְּהוֹמָא, וְלָא חָפָא לֵיהּ. כֵּיוָן דִּתְהוֹמָא אִתְנְהִיר, וְאִיהוּ אִסְתַּלָּק, כְּדֵין הֲוָה נְהִירוּ.</p>\n<p>דָּא נָהִיר עַל רֵישֵׁיהּ, וּמַיָּא הֲווֹ נַפְקֵי מִגּוֹ אֲפוּתֵיהּ, וְרוּחָא נָשִׁיב לְעֵילָּא. וְנָהִיר מִנְּהִירוּ דָּא, עַד דְּהֲוָה נָחִית נְהוֹרֵיהּ, מְנַצְנְצָא לְשִׁבְעִין וּתְרֵין נְהוֹרִין דְּשִׁמְשָׁא, כֵּיוָן דְּאִינּוּן נְהוֹרִין אִתְרְשִׁימוּ בְּגוֹ שִׁמְשָׁא לְתַתָּא, הֲווֹ (קפ\"ח ע\"א) חַיָּיבַיָּא דְּעָלְמָא יַדְעִין בְּהוּ, וַהֲווּ פַּלְחִין לְשִׁמְשָׁא. כֵּיוָן דְּאִסְתַּכַּל קוּדְשָׁא בְּרִיךְ הוּא בְּאִינּוּן חַיָּיבַיָּא, סָלִיק נְהוֹרֵיהּ וְגָנִיז לֵיהּ אֲמַאי גָּנִיז לֵיהּ. בְּגִין דְּהַהוּא תַּנִּין, הֲוָה סָלִיק וְנָחִית, וּבָטַשׁ בְּאִינוּן יְאוֹרִין, עַד דְּגָנַז לֵיהּ וְלָא אִתְגַּלְיָא.</p>\n<p>וְזָרַע לֵיהּ זְרוּעָא בְּחַד צַדִּיק, דְּאִיהוּ גָּנָּנָא דְּגִנְתָּא, וּזְרוּעָא דְּזָרַע בְּגִנְתָּא, בִּגְנִיזוּ בִּטְמִירוּ (ס\"א האי) דְּהַאי אוֹר אִיהוּ.</p>\n<p>כַּד הַאי הַתַּנִּין הַגָּדוֹל, חָמֵי דְּצָמַח בְּגִנְתָּא זְרוּעָא דְּאוֹר דָּא, כְּדֵין אִתְּעַר לְסִטְרָא אָחֲרָא, לְהַהוּא נָהָר דְּאִקְרֵי גִּיחוֹן. וְאִתְפְּלָגוּ מֵימוֹי דְּהַאי גִּיחוֹן, חַד שְׁבִילָא דִּילֵיהּ, אִיהוּ אָזִיל גּוֹ הַהוּא זְרוּעָא דְּאַצְמְחָא גּוֹ גִּנְתָּא, וְאַנְהִיר בֵּיהּ בִּרְבוּ דִּזְרוּעָא דָּא, וְאִקְרֵי גִּיחוֹן.</p>\n<p>וּמִגּוֹ הַהוּא רְבוּ דִּזְרוּעָא דָּא, אִסְתְּלַק לִרְבוּ דְּשְׁלֹמֹה מַלְכָּא, כַּד אִסְתְּלַק לְמַלְכוּ, דִּכְתִּיב, (מלכים א א׳:ל״ג-ל״ד) וְהוֹרַדְתֶּם אוֹתוֹ אֶל גִּיחוֹן, וּכְתִיב וּמָשַׁח אוֹתוֹ שָׁם. שָׁם, וְלֹא בַּאֲתַר אַחֲרָא, בְּגִין דְּהֲוָה יָדַע דָּוִד מַלְכָּא דָּא, וּמֵימוֹי אַחֲרָנִין אִסְתָּלָקוּ לְמַלְכוּ אַחֲרָא, וְדָא אִיהוּ מַלְכָּא דְּאִיהוּ תַּקִּיפָא.</p>\n<p>וְהַאי הַתַּנִּין הַגָּדוֹל, אִתְּעַר לֵיהּ, וְאִסְתַּלָּק סְנַפִּירוֹי דְּהַאי תַּנִּין, בְּהַהוּא נָהָר, לְאִתַּתְקְפָא בֵּיהּ. וְכָל אִינּוּן שְׁאַר יְאוֹרִין כֻּלְּהוּ, סַלְּקִין וְנַחְתִּין בְּתֻּקְפָּא דְּהַאי הַתַּנִּין הַגָּדוֹל, וְתָאַב וְעָאל לְהַהוּא יְאוֹרָא שְׁכִיכָא, וְאִשְׁתְּכַךְ בֵּיהּ.</p>\n<p>וּכְדֵין, כַּד הַהוּא אוֹר אִתְגְּנִיז (ס\"א לנטלא) לְעִיוּלָא לֵיהּ הַהוּא גָּנָּנָא דְּקַאמְרָן, כְּדֵין נָפַק חֹשֶׁךְ קַדְמָאָה, וּבָטַשׁ עַל רֵישֵׁיהּ, בְּהַהוּא נוּקְבָּא דְּאִתְמַתְּחָא בֵּיהּ, וְאִתְפְּרַשׁ חַד חוּטָא, בֵּין הַהוּא נְהִירוּ דְּאוֹר דָּא דְּאִתְגְּנִיז, וּבֵין הַהוּא חֲשׁוֹכָא דְּחֹשֶׁךְ דָּא, דִּכְתִּיב, (בראשית א׳:ד׳) וַיַּבְדֵּל אֱלהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>הַאי תַּנִּין, תָּב בְּהַהוּא פְּרִישׁוּ דְּהַאי חוּטָא דְּאַפְרִישׁ, וְאַפְרִישׁ לְאִינוּן (נ\"א בין אינון) יְאוֹרִין, גּוֹ חֲשׁוֹכָא, וְאִתְפְּרָשׁוּ נוּנִין לְזִנַיְיהוּ אִלֵּין מֵאִלֵּין, בְּהַהוּא פְּרִישׁוּ.</p>\n<p>וְכַד אִתְפְּרָשׁוּ מַיִין עִלָּאִין קַדִּישִׁין. כָּל אִינּוּן יְאוֹרִין אִתְפְּרָשׁוּ, וְעָאלוּ לְגוֹ הַהוּא יְאוֹרָא שְׁכִיכָא דְּאִתְבְּרִיר מִכֻּלְּהוּ, וְנָפִיק וְעָאלִין בֵּיהּ תְּלַת (בלק קצ\"ו) זִמְנִין בְּיוֹמָא.</p>\n<p>וְכָל אִינּוּן נוּנִין דִּמְגַדְּלָן גּוֹ אִינּוּן יְאוֹרִין, פְּרִישָׁן אִלֵּין מֵאִלֵּין, וְאִקְרוּן לֵילוֹת, וְאִלֵּין אִינּוּן רָאשִׁין לְכָל אִינּוּן נוּנִין דְּנָפְקִין לְבַר, וְאִלֵּין שַׁלְטִין עַל כֻּלְּהוּ. וְאִלֵּין אִקְרוּן בְּכוֹרֵי מִצְרַיִם, וּמֵהָכָא אִתְבַּדָר לְבַר בּוּכְרִין, וְכֻלְּהוּ אִתְּזָנוּ מִשַּׁקְיוּ דְּאִינּוּן יְאוֹרִין. וְהַאי הַתַּנִּין הַגָּדוֹל, שַׁלְטָא עַל כֻּלְּהוּ.</p>\n<p>וְכֹלָּא בִּפְרִישׁוּ דְּמַיִין עִלָּאִין, דִּכְתִּיב וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, וְאִתְרְשִׁימוּ מַיִין קַדִּישִׁין עִלָּאִין, וְאִתְפְּרָשׁוּ לְעֵילָּא, וּמַיִין תַּתָּאִין, אִתְפְּרָשׁוּ כֻּלְּהוּ אִלֵּין מֵאִלֵּין, קַדִּישִׁין וּדְלָא קַדִּישִׁין, וְעַל דָּא אִקְרוּן מַלְאָכִין עִלָּאִין פְּרִישָׁן, בְּגִין דְּאִתְפְּרָשׁוּ אִלֵּין מֵאִלֵּין לְזִנַיְיהוּ.</p>\n<p>וַיֹּאמֶר אֱלֹהִים תַדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע, רָזָא דָּא, כַּד הַאי הַתַּנִּין הַגָּדוֹל, הֲוָה נָשִׁיב רוּחָא בְּהַהוּא נוּקְבָּא, וּמְרַפְרְפָא לְגַבֵּי עֵילָּא, כָּל אִינּוּן עֲשָׂבִין הֲוָה מְהַפֵּךְ לוֹן לִיבִישׁוּ, עַד דְּרוּחָא אַחֲרָא נָשִׁיב בְּהַהוּא רוּחָא, וְשָׁכִיךְ לֵיהּ לְתַתָּא, וַעֲשָׂבִין צָמְחוּ כְּמִלְּקַדְּמִין. וְשַׁלְטִין וּמְשַׁבְּחָן וְאוֹדָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מִסְּטַר שְׂמָאלָא, וּלְגוֹ יְאוֹרָא שְׁכִיכָא, נָפְקִין בְּעִירִין לְזִנַיְיהוּ, וְאַזְלִין לְמִקְרַב לְגַבֵּי דְּאִינּוּן עֲשָׂבִין וְלָא יַכְלִין, וְתָבִין לְּאַתְרַיְיהוּ. כָּל אִלֵּין יְאוֹרִין אַזְלִין וְשָׁאטִין, עִם הַהוּא תַּנִּינָא דְּשַׁלִיט בְּהוּ, וְסַחֲרִין לְאִינוּן עֲשָׂבִין, וְלָא יַכְלִין. בַּר לְזִמְנִין, דְּרוּחָא עִלָּאָה לָא נָשִׁיב, וְאִיהוּ מְרַפְרְפָא רוּחָא בְּהַהוּא נוּקְבָּא דִּלְעֵילָּא, כְּמָה דְּאוֹקִימְנָא, כְּדֵין שָׁלִיט הַהוּא רוּחָא עַל אִינּוּן עֲשָׂבִין.</p>\n<p>וִיאוֹרָא שְׁכִיכָא תָּב לְאַתְרֵיהּ, וְסַלְּקָא וְנַחְתָּא. וּבְגִין דְּמֵימוֹי שְׁכִיכִין, אָזִיל בִּשְׁכִיכוּ, וְהַאי הַתַּנִּים הַגָּדוֹל סַלְּקָא לְגַבֵּי אִינּוּן יְאוֹרִין, וַעֲשָׂבִין כֻּלְּהוּ מְגַדְּלָן סַחֲרָנֵיהּ דְּהַהוּא יְאוֹרָא שְׁכִיכָא וְאִלֵּין (נ\"א ואינון) מְגַדְּלִין בְּכָל עִיבָר, כְּדֵין סַלְּקָא הַהוּא תַּנִּינָא וְאִתְרַבֵּי בֵּינַיְיהוּ, וְתָב לְכָל אִינּוּן יְאוֹרִין.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, דָּא אִיהוּ נָחָשׁ בָּרִיחַ. אֲמַאי בָּרִיחַ. בְּגִין דְּסָגִיר לִתְרֵין סִטְרִין, וְלָא נָפִיק לְעָלְמִין אֶלָּא חַד זִמְנָא לְיוֹבְלָא.</p>\n<p>וּבְסִפְרֵי קַדְמָאֵי, דָּא נָחָשׁ עֲקַלָּתוֹן, דְּאִיהוּ בְּעַקִּימוּ תָּדִיר, וְאַיְיתֵי לְוָוטִין עַל עָלְמָא, כַּד הַאי קָם, אִתְּבַר תּוּקְפֵּיהּ <Nonei></i>דְּהַהוּא תַּנִּינָא, וְלָא יָכִיל לְמֵיקָם, עַד דְּאָבִיד גִּשְׁמֵיהּ. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא כָּפִיף לֵיהּ גּוֹ יַמָּא, כַּד עָאל לְגַבֵּיהּ. וְאִיהוּ דָּרַךְ עַל תֻּקְפֵּיהּ דְּיַמָּא. וְתֻקְפֵּיהּ דְּיַמָּא דָּא, אִיהוּ תַּנִּינָא, כְּמָה דְאַתְּ אָמֵר (איוב ט׳:ח׳) וְדוֹרֵךְ עַל בָּמֳתֵי יָם.</p>\n<p>וְכַד הַאי נָחָשׁ קָם, כְּדֵין מַה כְּתִיב, (ישעיהו כ״ז:א׳) וְהָרַג אֶת הַתַּנִּין אֲשֶׁר בַּיָּם, דָּא אִיהוּ הַתַּנִּין הַגָּדוֹל. וְעַל דָּא כְּתִיב, (יחזקאל כ״ט:ג׳) הִנְנִי עָלֶיךָ. וְדָא נָחָשׁ, אִיהוּ מְאֹרֹת, בִּלְוָוטִין לְכֹלָּא, בְּגִין דְּאִיהוּ תַּקִּיפָא עָלֵיהּ, בְּתֻקְפֵּיהּ דְּהַהוּא נָהָר רַבְרְבָא, דְּאִקְרֵי חִדֶּקֶל, וְהָא אוֹקִימְנָא.</p>\n<p>הַהוּא נָחָשׁ אִיהִי בְּיַבֶּשְׁתָּא כַּד נָפְקִין דָּא בְּדָא, דָּא דִּבְיַבֶּשְׁתָּא אִתְתְּקַף תָּדִיר, בְּגִין דְּכָל אוֹרְחוֹי וְתֹקְפוֹי בְּיַבֶּשְׁתָּא אִיהוּ, וְאָכִיל אַרְעָא וְעַפְרָא תָּדִיר, כְּמָה דְאַתְּ אָמֵר (בראשית ג׳:י״ד) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ. דָּא גַּדִּיל בְּעַפְרָא, וְדָא גַּדִּיל בְּמַיָּא. נָחָשׁ דְּאִתְגַּדִּיל בְּמַיָּא, לָאו תַּקִּיפָא כְּהַאי דְּאִתְגַּדִּיל בְּיַבֶּשְׁתָּא, וְעַל דָּא כְּתִיב (בראשית א') מְאֹרֹת חָסֵר.</p>\n<p>וְדָא אִזְדָּמַן לְגַבֵּי הַהוּא דְּמַיָּא. וְאַף עַל גַּב (ודא לא) דְּאִזְדְּמַן לְגַבֵּיהּ, לָא אֲגַח לְגַבֵּיהּ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דְּקָטִיל לֵיהּ מִגּוֹ יַמָּא, כְּמָה דְּאוֹקִימְנָא בְּגִין גַּסּוּת רוּחָא דְּבֵיהּ, כְּמָה דְאַתְּ אָמֵר (יחזקאל כ\"ט) אֲשֶׁר אָמַר לִי יְאֹרִי וְגוֹ'.</p>"],[9520011586,"<p>וְעָבַר יְיָ' לִנְגּוֹף אֶת מִצְרַיִם וְגוֹ'. תָּנָא אָמַר רִבִּי יוֹסֵי, הַאי קְרָא קַשְׁיָא, וְכִי וְרָאָה אֶת הַדָּם וְאַחַר כַּךְ וּפָסַח, דְּמַשְׁמַע דְּסִימָנָא הוּא דְּעָבִיד. וְאִי תֵּימָא בְּגִין דָּמָא דְּאִיהוּ מִצְוָה, אֲמַאי לְבַר. וַאֲמַאי בִּתְלַת דּוּכְתֵּי דְּפִתְחָא. וְהָא כְּתִיב (דניאל ב׳:כ״ב) הוּא גַּלֵּי עֲמִיקָתָא וְגוֹ'. וּמַאי טַעְמָא בָּעָא דְּאִתְגַּלְיָא דָּמָא עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזוֹת.</p>\n<p>אֶלָּא תָּנָא, כְּתִיב, (דברים ל\"ב) וַיַּרְא יְיָ' וַיִּנְאָץ, וּכְתִיב, (בראשית ו׳:ה׳) וַיַּרְא יְיָ' כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ. וְתָנֵינָן לָא אִתְחָזֵי אַשְׁגָּחוּתָא דִּלְעֵילָּא, אֶלָּא כַּד אִתְחָזֵי לְתַתָּא עוֹבָדָא דְּאִתְעָבֵידוּ עוֹבָדָא מִנֵּיהּ וְעַל דָא (נ\"א ועד דעבדין עובדא לתתא) לָא מַשְׁגִּיחִין (נ\"א לאבאשא), בַּר הִרְהוּרָא דְּעֲבוֹדָה זָרָה, דִּכְתִּיב, (דברים י״א:ט״ז) הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם. וּמִדְּאִתְעָבֵיד עוֹבָדָא, אַשְׁגָּחוּתָא דִּלְעֵילָּא אִתְּעַר, וּבְגִין כַּךְ, כֹּלָּא, בֵּין לְטָב וּבֵין לְבִישׁ, בְּעוֹבָדָא תַּלְיָא מִלְּתָא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כָּל שְׁוָקֵי מִצְרַיִם, מַלְיָין טַעֲוָון הֲווֹ, וְעוֹד דִּבְכָל בֵּיתָא וּבֵיתָא, הֲווֹ שְׁכִיחֵי זִינִין, דְּמִתְקַטְרֵי בְּחָרָשַׁיְיהוּ, בְּאִינּוּן כִּתְרִין תַּתָּאִין דִּלְתַתָּא, וּמִתְעָרִין רוּחַ מִסְאֲבָא בְּגַוַויְיהוּ.</p>\n<p>וְרָזָא דְּמִלָּה תָּנָא, כְּתִיב, וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם אֶל הַמַּשְׁקוֹף וְאֶל שְׁתֵּי הַמְּזוּזוֹת. אֲגוּדַּת אֵזוֹב לָמָּה. בְּגִין לְבַעֲרָא רוּחַ מִסְאֲבָא מִבֵּינַיְיהוּ, (נ\"א האי קרא קשיא וכי וראה את הדם ואחר כך ופסח דמשמע דסימנא הוא דעביד אמאי והא כלא גלייא קמיה קודשא בריך הוא וכתיב הוא גלי עמיקתא ומסתרתא אלא תנא כתיב וירא יי' וינאץ וגו' וכתיב וירא יי' כי רבה רעת וגו' ותנינן לא אתחזי אשגחותא לעילא אלא כד אתחזי לתתא עובדא ומדאתעבד עובדא אשגחותא לעילא אתער ובגין כך כולא בין לטב בין לביש בעובדא תלייא מלתא. ולקחתם אגודת אזוב וגו' אגודת אזוב למה ומאי טעמא בעא דאתגלייא דמא על המשקוף ועל שתי המזוזות. אמר רבי יוסי כל שוקי מצרים מליין טעוון הוו ובכל ביתא וביתא הוו שכיחי זינין דמקטרין בחרשייהו באינון בתרין תתאין דלתתא ומתערין רוח מסאבא בגוייהו ועל דא אגודת אזוב בגין לבערא רוחי מבינייהו) וּלְאַחֲזָאָה בְּפִתְחַיְיהוּ, בְּהָנֵי תְּלַת דּוּכְתֵּי, מְהֵימָנוּתָא שְׁלֵימָתָא. חַד הָכָא, וְחַד הָכָא, וְחַד בְּגַוַויְיהוּ בְּגִין כַּךְ, וּפָסַח יְיָ' עַל הַפֶּתַח וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגּוֹף, מִשּׁוּם דְּחָמֵי שְׁמָא קַדִּישָׁא רָשִׁים עַל פִּתְחָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי הָכִי אֲמַאי דָּמָא, דְּהָא תָּנֵינָן, חִוָּור וְסוּמָק וְחַד דְּכָלִיל בֵּינֵי גַּוְונֵי. אֲמַר לֵיהּ, תְּרֵי דָּמֵי הֲווֹ, חַד דְּמִילָה, וְחַד דְּפִסְחָא. דְּמִילָה רַחֲמֵי. דְּפִסְחָא דִּינָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, לָאו הָכִי, אֶלָּא כְּמָה דְּאוֹלִיפְנָא, דְּאַחְזָר הַהוּא דָּמָא קוּדְשָׁא בְּרִיךְ הוּא לְרַחֲמֵי, כְּאִילּוּ הֲווֹ חִוָּור בְּגוֹ גַּוְונֵי, הֲדָא הוּא דִכְתִיב, (יחזקאל ט״ז:ו׳) וָאֶעֱבוֹר עָלַיִךְ וָאֶרְאֵךְ מִתְבּוֹסֶסֶת בְּדָמָיִךְ וְאוֹמַר לָךְ בְּדָמַיִךְ חֲיִי וְגוֹ'. וְאַף עַל גַּב דְּהֲוָה סוּמָקָא, אִתְחֲזָר לְרַחֲמֵי, דִּכְתִּיב בְּדָמַיִךְ חֲיִי. וּבְגִין כָּךְ, רָשִׁים פִּתְחָא בִּתְלַת סִטְרִין, חַד הָכָא, וְחַד הָכָא, וְחַד בֵּינַיְיהוּ.</p>\n<p>תָּאנֵי ר' חִזְקִיָּה, תְּרֵין דָּמֵי אִתְחָזוּ, לָקֳבֵל תְּרֵי כִּתְרִין, דְּאִתְחָזוּ (נ\"א דאתערו) לְעֵילָּא בְּהַהִיא שַׁעֲתָא. אָמַר רִבִּי יוֹסֵי, חַד כִּתְרָא דִּכְלִילָא בִּתְרֵין סִטְרִין טְמִירִין, <Nonei></i>בְּרַחֲמֵי וְדִינָא.</p>\n<p>אָמַר רִבִּי אַבָּא, בְּכַמָּה אַתְרִין חָס קוּדְשָׁא בְּרִיךְ הוּא עַל בְּנוֹי: עָבֵד בַּר נָשׁ בֵּיתָא, וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ, כְּתוֹב שְׁמִי, וְשַׁוֵּי לְפִתְחָךְ, וְאַתְּ שָׁרֵי לְגוֹ בֵּיתָא, וַאֲנָא אוֹתִיב לְבַר בְּפִתְחָךְ לְנַטְרָא לָךְ. וְהָכָא אָמַר, רָשִׁים עַל פִּתְחָא רָזָא דִּמְהֵימָנוּתָא דִּילִי, וְאַתְּ שָׁרֵי לְגוֹ בֵּיתָךְ, וַאֲנָא נָטִיר לָךְ לְבַר, דִּכְתִּיב וְאַתֶּם לא תֵּצֵאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר, וּכְתִיב וְרָאָה אֶת הַדָּם עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזוֹת וּפָסַח ד' עַל הַפֶּתַח וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגּוֹף.</p>\n<p>תּוּ אָמַר רִבִּי אַבָּא, כְּגַוְונָא דִּשְׁמָא קַדִּישָׁא עֲבָדוּ בְּהַהוּא שַׁעֲתָא. מַה שְּׁמָא קַדִּישָׁא ה אִתְחֲזָר בְּהַאי שַׁעֲתָא דִּינָא, אוּף הָכִי אִתְחֲזָר הַאי דָּמָא בְּהַאי שַׁעֲתָא דִּינָא, דִּכְתִּיב וְרָאָה אֶת הַדָּם עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזוֹת, רְשִׁימָא דְּכֻלְּהוּ סוּמָקָא, לְאִתְחֲזָאָה, דְּהָא אִתְחֲזָר בְּדִינָא, לְמֶעְבַּד נוּקְמִין.</p>\n<p>וְרָזָא דְּמִלָּה, כְּגַוְונָא דְּהַוֵי לְעֵילָּא בְּהַהוּא שַׁעֲתָא, כַּד בָּעֵי לְאִתְחֲזָאָה לְתַתָּא, אִי רַחֲמֵי רַחֲמֵי, וְאִי דִּינָא דִּינָא, הֲדָא הוּא דִּכְתִּיב, וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם וְגוֹ'. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה. דְּזַמִּין לְאַחֲזָאָה (נ\"א לאתחזרא) כֻּלְּהוּ דִּינָא לְמֶעְבַּד נוּקְמִין.</p>\n<p>וְאַתֶּם לֹא תֵּצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מַאי טַעֲמָא, מִשּׁוּם דְּתָנֵינָן, אָמַר רִבִּי יִצְחָק, (אמר רבי ירמיה) לָא לִיבָעֵי לֵיהּ לְאִינִשׁ לְמֵיזַל בְּשׁוּקָא, וּלְאִשְׁתַּכְּחָא בְּשׁוּקָא, בְּזִמְנָא דְּדִינָא תַּלְיָא בְּמָתָא, דְּכֵיוָן דִּרְשׁוּתָא אִתְיְיהִיב לִמְחַבְּלָא, מַאן דְּפָגַע בֵּיהּ אִתְּזַק. וְהָכָא מִשּׁוּם דְּדִינָא אִשְׁתְּכַח, לָא בַּעְיָא לְנָפְקָא לְבַר.</p>\n<p>תַּנְיָא אָמַר רִבִּי יוֹסֵי, בְּהַהוּא מַמָּשׁ דְּאִשְׁתְּכַח דִּינָא לְמִצְרָאֵי, בְּהַהוּא מַמָּשׁ אִשְׁתְּכַח רַחֲמֵי לְיִשְׂרָאֵל, הֲדָא הוּא דִּכְתִּיב, וְרָאִיתִי אֶת הַדָּם וּפָסַחְתִּי עֲלֵיכֶם. וְכֵן תָּנָא, בְּכָל אִינּוּן כִּתְרִין קַדִּישִׁין דִּלְעֵילָּא, כְּמָה דְּאִשְׁתְּכַח דִּינָא, אִשְׁתְּכַח רַחֲמֵי, וְכֹלָּא בְּשַׁעֲתָא חֲדָא. תָּנָא רִבִּי חִזְקִיָּה, כְּתִיב, (ישעיהו י״ט:כ״ב) וְנָגַף יְיָ' אֶת מִצְרַיִם נָגוֹף וְרָפֹא. נָגוֹף לְמִצְרַיִם, וְרָפֹא לְיִשְׂרָאֵל. מַאי וְרָפֹא. מִמַאי שֶׁנִּימוֹלוּ צְרִיכִים רְפוּאָה.</p>\n<p>וְתָנָא, בְּאוֹתָה שָׁעָה שֶׁנִּגְּפוּ מִצְרָאֵי, בְּאוֹתָה שָׁעָה נִתְרַפְּאוּ יִשְׂרָאֵל. דְּתַנְיָא אָמַר רִבִּי יוֹסֵי, (אמר רבי חזקיה) מַהוּ דִּכְתִּיב, וּפָסַח יְיָ עַל הַפֶּתַח, מַאי עַל הַפֶּתַח. וּפָסַח יְיָ' עֲלֵיכֶם מִבָּעֵי לֵיהּ. אֲבָל עַל הַפֶּתַח, עַל הַפֶּתַח מַמָּשׁ זֶהוּ פֶּתַח הַגּוּף. וְאֵי זֶהוּ פֶּתַח הַגּוּף. הוֵי אוֹמֵר זוֹ מִילָה.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, בְּשַׁעֲתָא דְּאִתְפְּלַג לֵילְיָא, וְכִתְרָא קַדִּישָׁא אִתְּעַר לְגַבָּהּ (נ\"א אתערב ביה) דְּכוּרָא. וּמַאן דְּכוּרָא. חֶסֶד עִלָּאָה, דְּמַשְׁמַע, דְּדָא בְּלָא דָּא לָא סַלְּקָא, וּבְגִין דָּא, דָּא מָחֵי, וְדָא מַסֵּי, וְכֹלָּא בְּשַׁעֲתָא חֲדָא.</p>\n<p>וּכְתִיב, וּפָסַח יְיָ עַל הַפֶּתַח הַיָּדוּעַ. מַאי הַפֶּתַח, מִשּׁוּם דְּאִיהוּ פִּתְחָא וּמְשִׁיכָא דְּרוּחָא וְגוּפָא, וְתָא חֲזֵי, עַד לָא אִתְגְּזַר אַבְרָהָם, הֲוָה אָטִים וְסָתִים מִכָּל סִטְרוֹי. מִדְּאִתְגְּזַר אִתְפְּתַח מִכֹּלָּא, וְלָא הֲוֵי אָטִים וְסָתִים כְּקַדְמִיתָא.</p>\n<p>וְהַיְינוּ רָזָא דְּתָנֵינָן, (בראשית י״ח:א׳) וְהוּא ישֶׁב פֶּתַח הָאֹהֶל. מִשּׁוּם דְּאִתְגַּלְיָיא יוֹ\"ד. מַאי קָא מַיְירֵי. אֶלָּא אָמַר רִבִּי יִצְחָק דְּהוּא אַשְׁרֵי בְּגִלּוּיָא דָּא, חֶסֶד בְּצֶדֶק. וְדָא הוּא פִּתְחָא, דְּמַשְׁכְּנָא עִלָּאָה קַדִּישָׁא, מַשְׁמַע דִּכְתִּיב הָאֹהֶל, הָאֹהֶל הַיָּדוּעַ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, כַּד אִתְגַּלְּיָיא הַאי יוֹ\"ד, אִתְבָּשַּׂר, (נ\"א אתבשם) וְאִתְבְּרַךְ בְּפֶתַח הָאֹהֶל, דְּהִיא צֶדֶק, לְאִתְבַּסְּמָא בְּחֶסֶ\"ד. הֲדָא הוּא דִּכְתִּיב, כְּחוֹם הַיּוֹם, דְּהוּא שַׁעֲתָא דְּשַׁלְטָא חֶסֶד, חוּלָקָא דְּאַבְרָהָם. וּמְנָא לָן דְּהַאי פֶּתַח הָאֹהֶל, אִתְבַּסַּם לְקָבְלֵיהּ דְּאַבְרָהָם. דִּכְתִּיב, (בראשית כ״ד:א׳) וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, דְּאִתְבָּסָּם בְּחֶסֶ\"ד, מִדְּאִתְגַּלְיָיא יוֹ\"ד.</p>\n<p>אָמַר רִבִּי אַבָּא, וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל, כְּמָה דִּכְתִּיב וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. דְּדָא הוּא פִּתְחָא קַדִּישָׁא, כִּתְרָא עֲשִׁירָאָה. כְּחוֹם הַיּוֹם, כְּמָה דְּאִתְיְיהִיב לֵיהּ כִּתְרָא דְּחֶסֶד, הֲדָא הוּא דִּכְתִּיב כְּחוֹם הַיּוֹם. כְּמָה דְּיָתִיב בְּהַאי, כַּךְ יָתִיב בְּהַאי, דְּלָא סָלִיק הַאי בְּלא הַאי.</p>\n<p>דָּבָר אַחֵר <Nonei></i>וְעָבַר יְיָ לִנְגּוֹף אֶת מִצְרַיִם. מַאי וְעָבַר. דְּעָבַר עַל שׁוּרֵי דִּינָא דְּכִתְרִין, (נ\"א דקטרין) דַּהֲווֹ מִתְקַשְּׁרֵי בְּכִתְרִין אַחֲרָנִין דִּלְעֵילָּא, וְשָׁרָא לְהוּ מִקִּיּוֹמֵיהוֹן, וְעָבַר עַל אוֹרְחוֹי, בְּגִין לְמֶעְבַּד בְּהוּ דִּינָא, וּלְנַטְרָא לְהוּ לְיִשְׂרָאֵל, וּכְדֵין הוּא, כָּל וְעָבַר, וְעָבַרְתִּי, וַיַּעֲבֹר, דְּקוּדְשָׁא בְּרִיךְ הוּא אַעְבַר עַל כָּל אוֹרְחוֹי, אוֹ לְדִינָא, אוֹ לְרַחֲמֵי. הָכָא וְעָבַר, בְּגִין לְמֶעְבַּד דִּינָא, הָתָם וַיַּעֲבֹר, בְּגִין לְרַחֲמָא.</p>"]]});
